function normAngle(a){while(a>180)a-=360;while(a<-180)a+=360;return a}
function dist2(x1,y1,x2,y2){var dx=x2-x1,dy=y2-y1;return Math.sqrt(dx*dx+dy*dy)}
function clamp(v,lo,hi){return v<lo?lo:v>hi?hi:v}

function avoidObs(obs,mem){
  var r=obs.rays,s=0,minD=15;
  for(var i=0;i<9;i++){
    var d=r[i],a=(i-4)*20;
    if(d<minD)minD=d;
    if(d<7){
      var u=clamp((7-d)/7,0,1);
      if(a===0){
        var l=Math.min(r[5],r[6],r[7],r[8]),rt=Math.min(r[0],r[1],r[2],r[3]);
        s+=(l>=rt?1:-1)*u*0.5;
      }else{
        s+=(a>0?-1:1)*u*(1-Math.abs(a)/80)*0.25;
      }
    }
  }
  var sf=minD<10?clamp(minD/10,0.1,1):1;
  if(mem.avoidTimer>0)s+=mem.bumpDir*0.3;
  return{steer:clamp(s,-1,1),speedFactor:sf};
}

function navTo(obs,mem,tx,ty){
  var tH=obs.heading-mem.compassBias;
  var dx=tx-obs.x,dy=ty-obs.y;
  var d=Math.sqrt(dx*dx+dy*dy);
  var tA=Math.atan2(dy,dx)*180/Math.PI;
  var hE=normAngle(tA-tH);
  var dE=hE-mem.headingErrPrev;
  mem.headingErrPrev=hE;
  var hs=0.005*hE+0.001*dE;
  var av=avoidObs(obs,mem);
  var ts=clamp(hs+av.steer,-0.8,0.8);
  var spd=1;
  if(d<15)spd=clamp(0.12+d/15*0.88,0.12,1);
  if(d<4)spd=Math.min(spd,0.3);
  if(d<2)spd=Math.min(spd,0.15);
  spd*=(1-Math.abs(hE)/90*0.5);
  spd*=av.speedFactor;
  if(mem.avoidTimer>0)spd=Math.min(spd,0.3);
  if(obs.x<20||obs.x>mem.mapSize-20||obs.y<20||obs.y>mem.mapSize-20)spd=Math.min(spd,0.3);
  spd=clamp(spd,0,1-Math.abs(ts));
  return{left:clamp(spd-ts,-1,1),right:clamp(spd+ts,-1,1),drill:false};
}

function steerToBr(obs,mem,br,ds){
  var s=clamp(0.008*br,-0.5,0.5);
  var spd=clamp(ds/5,0.08,0.5);
  if(ds<3)spd=Math.min(spd,0.15);
  if(ds<2)spd=Math.min(spd,0.1);
  spd*=(1-Math.abs(br)/120);
  var av=avoidObs(obs,mem);
  var ts=clamp(s+av.steer,-0.5,0.5);
  spd*=av.speedFactor;
  spd=clamp(spd,0,1-Math.abs(ts));
  return{left:clamp(spd-ts,-1,1),right:clamp(spd+ts,-1,1),drill:false};
}

function holdPos(obs,mem){
  var spd=mem.signedSpeed||0,err=-spd;
  mem.holdIntegral=clamp(mem.holdIntegral+err*0.1,-0.4,0.4);
  var f=clamp(err*2.5+mem.holdIntegral,-0.35,0.35);
  return{left:f,right:f,drill:true};
}

function stuckRec(obs,mem){
  mem.stuckRecoverTimer+=0.1;
  if(mem.stuckRecoverTimer<1.5)return{left:-0.4,right:-0.4,drill:false};
  if(mem.stuckRecoverTimer<3)return{left:0.3,right:-0.3,drill:false};
  mem.stuckTimer=0;mem.stuckRecoverTimer=0;
  return{left:0.3,right:0.3,drill:false};
}

function planRoute(mem,obs){
  var av=[];
  for(var i=0;i<mem.hints.length;i++){
    if(!mem.hints[i].done&&!mem.hints[i].rejected)av.push(mem.hints[i]);
  }
  if(!av.length){mem.route=[];mem.routeIdx=0;return;}
  var route=[],cx=obs.x,cy=obs.y,tT=0;
  var maxS=Math.min(mem.capacity+2,av.length);
  var budget=obs.timeLeft*0.7;
  for(var i=0;i<maxS;i++){
    var best=null,bS=-1,bTT=0;
    for(var j=0;j<av.length;j++){
      var h=av[j];
      if(route.indexOf(h.id)>=0)continue;
      var d=dist2(cx,cy,h.x,h.y);
      var tt=d/1.5+6;
      var retD=dist2(h.x,h.y,mem.baseX,mem.baseY);
      if(tT+tt+retD/1.5>budget)continue;
      var sc=h.value/(tt+2);
      if(sc>bS){bS=sc;best=h;bTT=tt;}
    }
    if(best){route.push(best.id);tT+=bTT;cx=best.x;cy=best.y;}
  }
  mem.route=route;mem.routeIdx=0;
}

function act(obs,mem){
  var dt=0.1;
