  if(moved/dt>0.3&&moved>0.03){
    var gpsH=Math.atan2(dy,dx)*180/Math.PI;
    mem.compassBias=mem.compassBias*0.97+normAngle(obs.heading-gpsH)*0.03;
  }
  mem.batHistory.push(obs.battery);
  if(mem.batHistory.length>100)mem.batHistory.shift();
