  if (!Array.isArray(mem.sampled)) mem.sampled = [];
  if (!Number.isFinite(mem.ePerM)) mem.ePerM = 0.001;
  if (!Number.isFinite(mem.eDrill)) mem.eDrill = 0.0015;
  if (!Number.isFinite(mem.capacity)) mem.capacity = 5;
  if (!Number.isFinite(mem.activeHint)) mem.activeHint = -1;

  const hasTL = obs.timeLeft !== undefined &&
    obs.timeLeft !== null &&
    Number.isFinite(Number(obs.timeLeft));
  const timeLeft = hasTL
    ? Math.max(0, Number(obs.timeLeft))
    : Math.max(0, mem.totalSeconds - num(obs.t, 0));
  const now = hasTL
    ? Math.max(0, mem.totalSeconds - timeLeft)
    : Math.max(0, num(obs.t, 0));

  let dt = 0.1;
  if (Number.isFinite(mem.prevTimeLeft) && hasTL) {
    const d = mem.prevTimeLeft - timeLeft;
    if (d > 0.015 && d < 0.8) dt = d;
  } else if (Number.isFinite(mem.prevNow)) {
    const d = now - mem.prevNow;
    if (d > 0.015 && d < 0.8) dt = d;
  }
  dt = clamp(dt, 0.03, 0.3);

  const wl = num(obs.wheelLeft, 0);
  const wr = num(obs.wheelRight, 0);
  const vActual = clamp((wl + wr) * 0.5, -3.2, 3.2);
  const yawActual = clamp((wr - wl) / 0.6, -8, 8);
  const rawH = wrap(num(obs.heading, 0));
  const gpsValid = Number.isFinite(Number(obs.x)) &&
                   Number.isFinite(Number(obs.y));
  const gx = gpsValid ? Number(obs.x) : NaN;
  const gy = gpsValid ? Number(obs.y) : NaN;

  function resetCourse() {
    mem.courseN = 0;
    mem.courseDist = 0;
    mem.courseSin = 0;
    mem.courseCos = 0;
    mem.courseX = NaN;
    mem.courseY = NaN;
  }

  function updatePose() {
    if (!mem.poseReady) {
      mem.px = gpsValid ? gx : mem.baseX;
      mem.py = gpsValid ? gy : mem.baseY;
      mem.poseH = rawH;
      mem.hOff = 0;
      mem.gpsPrevX = gpsValid ? gx : NaN;
      mem.gpsPrevY = gpsValid ? gy : NaN;
      mem.gpsRepeat = 0;
      mem.gpsStillOdo = 0;
      mem.gpsFrozen = false;
      mem.odo = 0;
      mem.stepDistance = 0;
      mem.prevRawH = rawH;
      mem.vActual = 0;
      mem.yawActual = 0;
      resetCourse();
      mem.poseReady = true;
      return;
    }

    const oldX = mem.px;
    const oldY = mem.py;
    const oldH = mem.poseH;
    const dYaw = yawActual * dt * 180 / Math.PI;
    const predH = wrap(oldH + dYaw);

    let comp = wrap(rawH + num(mem.hOff, 0));
    let compErr = wrap(comp - predH);
    if (Math.abs(compErr) > 48 && Math.abs(dYaw) < 24) {
      mem.hOff = wrap(num(mem.hOff, 0) - compErr);
      compErr = 0;
    }
    const hGain = Math.abs(compErr) > 24 ? 0.05 : 0.24;
    mem.poseH = wrap(predH + hGain * compErr);

    const step = clamp(vActual * dt, -0.38, 0.38);
    const midH = wrap(oldH + dYaw * 0.5) * rad;
    let px = oldX + step * Math.cos(midH);
    let py = oldY + step * Math.sin(midH);
    mem.odo = num(mem.odo, 0) + Math.abs(step);

    let wasFrozen = !!mem.gpsFrozen;
    let rawStep = Infinity;
    if (gpsValid && Number.isFinite(mem.gpsPrevX) &&
        Number.isFinite(mem.gpsPrevY)) {
      rawStep = dist(gx, gy, mem.gpsPrevX, mem.gpsPrevY);
      if (rawStep < 0.025) {
        mem.gpsRepeat = num(mem.gpsRepeat, 0) + 1;
        mem.gpsStillOdo = num(mem.gpsStillOdo, 0) + Math.abs(step);
        if (mem.gpsRepeat > 18 && mem.gpsStillOdo > 1.0) {
          mem.gpsFrozen = true;
        }
      } else {
        mem.gpsRepeat = 0;
        mem.gpsStillOdo = 0;
        mem.gpsFrozen = false;
      }
    }

    if (gpsValid && !mem.gpsFrozen) {
      const maxJump = Math.max(4.0, Math.abs(vActual) * dt * 5 + 2.0);
      if (rawStep <= maxJump || wasFrozen) {
        const err = dist(gx, gy, px, py);
        if (err < 9 || wasFrozen) {
          let a = wasFrozen ? 0.38 : 0.25;
          if (err > 4 && !wasFrozen) a = 0.08;
          px += (gx - px) * a;
          py += (gy - py) * a;
        }
      }
    }
    mem.px = px;
    mem.py = py;
    mem.stepDistance = Math.min(0.5, dist(oldX, oldY, px, py));
    mem.vActual = vActual;
    mem.yawActual = yawActual;

    if (gpsValid) {
      mem.gpsPrevX = gx;
      mem.gpsPrevY = gy;
    }

    if (gpsValid && !mem.gpsFrozen && vActual > 0.28 &&
        Math.abs(yawActual) < 0.20) {
      if (!Number.isFinite(mem.courseX)) {
        mem.courseX = gx;
        mem.courseY = gy;
        mem.courseN = 0;
        mem.courseDist = 0;
        mem.courseSin = 0;
        mem.courseCos = 0;
      }
      mem.courseDist = num(mem.courseDist, 0) + vActual * dt;
      mem.courseSin = num(mem.courseSin, 0) + Math.sin(rawH * rad);
      mem.courseCos = num(mem.courseCos, 0) + Math.cos(rawH * rad);
      mem.courseN = num(mem.courseN, 0) + 1;
      if (mem.courseDist >= 7 && mem.courseN >= 8) {
        const cd = dist(gx, gy, mem.courseX, mem.courseY);
        const coherence = Math.hypot(mem.courseSin, mem.courseCos) /
                          Math.max(1, mem.courseN);
        if (cd > 4 && coherence > 0.86) {
          const course = Math.atan2(gy - mem.courseY, gx - mem.courseX) / rad;
          const meanRaw = Math.atan2(mem.courseSin, mem.courseCos) / rad;
          const newOff = wrap(course - meanRaw);
          const offErr = wrap(newOff - num(mem.hOff, 0));
          if (Math.abs(offErr) < 48) {
            const adj = clamp(offErr * 0.32, -8, 8);
            mem.hOff = wrap(num(mem.hOff, 0) + adj);
            mem.poseH = wrap(mem.poseH + clamp(offErr * 0.12, -4, 4));
          }
        }
        resetCourse();
      }
    } else {
      resetCourse();
    }

    mem.prevRawH = rawH;
  }

  updatePose();

  const battery = Math.max(0, num(obs.battery, 1));
  const solar = Math.max(0, num(obs.solar, 0));
  const drillProgress = Math.max(0, num(obs.drilling, 0));
  const dockedNow = !!obs.docked;
  let netDraw = 0;

  if (!mem.energyReady) {
    mem.prevBattery = battery;
    mem.prevSolar = solar;
    mem.prevEnergyNow = now;
    mem.eWindowEnergy = 0;
    mem.eWindowDist = 0;
    mem.drillEnergy = 0;
    mem.drillSeconds = 0;
    mem.prevDrillProgress = drillProgress;
    mem.energyReady = true;
  } else {
    netDraw = num(mem.prevBattery, battery) - battery +
              0.5 * (num(mem.prevSolar, solar) + solar) * dt;
    const drillingForEnergy = (drillProgress > 0 || !!mem.drillIssued) &&
                              !dockedNow;
    if (!dockedNow && !drillingForEnergy && Math.abs(vActual) > 0.10) {
      const dd = Math.max(num(mem.stepDistance, 0),
                          Math.abs(vActual) * dt * 0.35);
      mem.eWindowDist = num(mem.eWindowDist, 0) + Math.min(0.38, dd);
      mem.eWindowEnergy = num(mem.eWindowEnergy, 0) + Math.max(0, netDraw);
      if (mem.eWindowDist >= 5.5) {
        const measured = mem.eWindowEnergy / Math.max(1, mem.eWindowDist);
        if (measured > 0.00005 && Number.isFinite(measured)) {
          const target = clamp(measured * 1.16, 0.00025, 0.025);
          mem.ePerM = clamp(0.72 * mem.ePerM + 0.28 * target,
                            0.00025, 0.03);
        }
        mem.eWindowDist = 0;
        mem.eWindowEnergy = 0;
      }
    }

    if (drillingForEnergy) {
      mem.drillSeconds = num(mem.drillSeconds, 0) + dt;
      mem.drillEnergy = num(mem.drillEnergy, 0) + Math.max(0, netDraw);
    } else if (num(mem.drillSeconds, 0) >= 3) {
      const measured = num(mem.drillEnergy, 0) /
                       Math.max(1, num(mem.drillSeconds, 0));
      if (measured > 0.00002 && Number.isFinite(measured)) {
        const target = clamp(measured * 1.2, 0.0001, 0.03);
        mem.eDrill = clamp(0.7 * mem.eDrill + 0.3 * target,
                           0.0001, 0.04);
      }
      mem.drillSeconds = 0;
      mem.drillEnergy = 0;
    }

    mem.prevBattery = battery;
    mem.prevSolar = solar;
    mem.prevEnergyNow = now;
    mem.prevDrillProgress = drillProgress;
  }

  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  if (!Array.isArray(mem.rayPrev)) {
    mem.rayPrev = new Array(9);
    mem.rayBad = new Array(9).fill(false);
    mem.rayOdo = new Array(9).fill(num(mem.odo, 0));
    mem.rayTime = new Array(9).fill(now);
  }
  for (let i = 0; i < 9; i++) {
    if (i >= rays.length || !Number.isFinite(Number(rays[i]))) continue;
    const r = Number(rays[i]);
    if (!Number.isFinite(mem.rayPrev[i])) {
      mem.rayPrev[i] = r;
      mem.rayOdo[i] = num(mem.odo, 0);
      mem.rayTime[i] = now;
      continue;
    }
    if (Math.abs(r - mem.rayPrev[i]) > 0.035) {
      mem.rayPrev[i] = r;
      mem.rayOdo[i] = num(mem.odo, 0);
      mem.rayTime[i] = now;
      mem.rayBad[i] = false;
    } else if (r < 14.8 &&
               num(mem.odo, 0) - num(mem.rayOdo[i], 0) > 5.5 &&
               now - num(mem.rayTime[i], now) > 8) {
      mem.rayBad[i] = true;
    }
  }

  const science = Math.max(0, num(obs.science, 0));
  const sigLast = mem.sigPts.length ? mem.sigPts[mem.sigPts.length - 1] : null;
  if (!sigLast ||
      dist(mem.px, mem.py, sigLast.x, sigLast.y) > 1.3 ||
      now - sigLast.t > 2.2) {
    mem.sigPts.push({ x: mem.px, y: mem.py, s: science, t: now });
    if (mem.sigPts.length > 90) mem.sigPts.shift();
  }

  const carried = Math.max(0, Math.floor(num(obs.carried, 0)));

  function noteSample() {
    const sx = num(mem.drillGX, num(mem.siteGX, mem.px));
    const sy = num(mem.drillGY, num(mem.siteGY, mem.py));
    const sv = num(mem.drillValue, num(mem.siteValue, 0));
    mem.sampled.push({ x: sx, y: sy, v: sv });
    if (mem.sampled.length > 60) mem.sampled.shift();

    let closest = -1;
    let closestD = 32;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.s !== 0) continue;
      const d = dist(sx, sy, h.x, h.y);
      if (d < closestD) {
        closestD = d;
        closest = i;
      }
    }
    if (closest >= 0) mem.hints[closest].s = 1;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h && h.s === 0 && dist(sx, sy, h.x, h.y) < 4.5) h.s = 1;
    }
    if (mem.activeHint >= 0 && mem.hints[mem.activeHint]) {
      const h = mem.hints[mem.activeHint];
      if (dist(sx, sy, h.x, h.y) < 32) h.s = 1;
    }
    if (mem.activeHint >= 0 &&
        (!mem.hints[mem.activeHint] || mem.hints[mem.activeHint].s !== 0)) {
      mem.activeHint = -1;
      if (mem.srch && !mem.srch.free) mem.srch = null;
    }
    mem.drillGX = undefined;
    mem.drillGY = undefined;
    mem.drillValue = undefined;
    mem.drillIssued = false;
    mem.siteMode = false;
  }

  let justSampled = false;
  if (!Number.isFinite(mem.lastCarried)) {
    mem.lastCarried = carried;
  } else if (carried > mem.lastCarried) {
    justSampled = true;
    noteSample();
  }
  mem.lastCarried = carried;

  const siteObj = obs.site && typeof obs.site === "object" ? obs.site : null;
  if (siteObj) {
    const sd = Math.max(0, num(siteObj.distance, 99));
    const sb = num(siteObj.bearing, 0);
    const continuing = drillProgress > 0 || !!mem.drillIssued;
    if (!continuing || !mem.siteMode ||
        !Number.isFinite(mem.siteGX) || justSampled) {
      const absB = (num(mem.poseH, rawH) + sb) * rad;
      mem.siteGX = mem.px + sd * Math.cos(absB);
      mem.siteGY = mem.py + sd * Math.sin(absB);
      mem.siteValue = Math.max(0, num(siteObj.value, 1));
    }
    mem.siteMode = true;
    mem.siteLast = now;
    mem.siteLocalDist = sd;
    mem.siteLocalBear = sb;
    if (!continuing) mem.siteValue = Math.max(0, num(siteObj.value, 1));
  } else if (drillProgress > 0) {
    mem.siteMode = true;
    if (!Number.isFinite(mem.siteGX)) {
      mem.siteGX = mem.px;
      mem.siteGY = mem.py;
    }
  } else if (mem.siteMode &&
             now - num(mem.siteLast, now - 100) > 4.5) {
    mem.siteMode = false;
    mem.drillIssued = false;
  }

  const bumped = !!obs.bumped;
  if (bumped && !mem.wasBumped) {
    let leftClear = 0, rightClear = 0;
    for (let i = 0; i < 9; i++) {
      const r = i < rays.length ? num(rays[i], 0) : 0;
      if (i < 4) rightClear += r;
      else if (i > 4) leftClear += r;
    }
    mem.bumpSide = leftClear >= rightClear ? 1 : -1;
    mem.bumpStart = now;
  }
  mem.wasBumped = bumped;

  function motorCommand(target, actual, side, slopeComp) {
    let gain = side === 0 ? num(mem.gL, 2.5) : num(mem.gR, 2.5);
    const prevOut = side === 0 ? num(mem.prevOutL, 0) : num(mem.prevOutR, 0);
    const prevWheel = side === 0 ? num(mem.prevWheelL, actual) :
                                   num(mem.prevWheelR, actual);
    const prevTarget = side === 0 ? num(mem.prevTargetL, 0) :
                                    num(mem.prevTargetR, 0);

    if (Math.abs(prevTarget) > 0.35 &&
        Math.abs(actual) > 0.10 &&
        Math.abs(actual - prevWheel) < 0.14 &&
        Math.abs(prevOut) > 0.18 && Math.abs(prevOut) < 0.94 &&
        prevOut * prevTarget > 0) {
      const ratio = clamp(Math.abs(actual / prevOut), 0.55, 3.8);
      gain = clamp(0.975 * gain + 0.025 * ratio, 0.65, 3.8);
      if (side === 0) mem.gL = gain;
      else mem.gR = gain;
    }

    let u = target / Math.max(0.65, gain) + 0.18 * (target - actual);
    u += slopeComp;

    let minCmd = side === 0 ? num(mem.minCmdL, 0.075) :
                              num(mem.minCmdR, 0.075);
    let stall = side === 0 ? num(mem.stallL, 0) : num(mem.stallR, 0);
    if (Math.abs(target) > 0.22 && Math.abs(actual) < 0.055 &&
        Math.abs(prevOut) > 0.09 && prevOut * target > 0) {
      stall += 1;
      if (stall > 9) {
        minCmd = Math.min(0.32, minCmd + 0.018);
        stall = 0;
      }
    } else if (Math.abs(actual) > 0.12) {
      stall = Math.max(0, stall - 1);
      if (minCmd > 0.08) minCmd = Math.max(0.075, minCmd - 0.0004);
    } else {
      stall = Math.max(0, stall - 0.2);
    }
    if (side === 0) {
      mem.minCmdL = minCmd;
      mem.stallL = stall;
    } else {
      mem.minCmdR = minCmd;
      mem.stallR = stall;
    }

    if (Math.abs(target) > 0.085 && target * u > 0 &&
        Math.abs(u) < minCmd) {
      u = Math.sign(target) * minCmd;
    }
    return clamp(u, -1, 1);
  }

  function drive(v, omega, drill) {
    v = clamp(v, -2.4, 2.4);
    omega = clamp(omega, -2.4, 2.4);
    const pitch = num(obs.pitch, 0);
    const slopeComp = clamp(Math.sin(pitch * rad) * 0.9, -0.30, 0.30);
    const targetL = clamp(v - omega * 0.3, -2.5, 2.5);
    const targetR = clamp(v + omega * 0.3, -2.5, 2.5);
    const left = motorCommand(targetL, wl, 0, slopeComp);
    const right = motorCommand(targetR, wr, 1, slopeComp);
    mem.prevOutL = left;
    mem.prevOutR = right;
    mem.prevTargetL = targetL;
    mem.prevTargetR = targetR;
    mem.prevWheelL = wl;
    mem.prevWheelR = wr;
    mem.drillIssued = !!drill;
    return { left: left, right: right, drill: !!drill };
  }

  function chooseHeading(goalRel) {
    const rayAngles = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
    const points = [];
    let validCount = 0;
    for (let i = 0; i < 9; i++) {
      if (i >= rays.length || mem.rayBad[i]) continue;
      const rv = Number(rays[i]);
      if (!Number.isFinite(rv)) continue;
      validCount++;
      if (rv >= 14.8) continue;
      const r = Math.max(0.12, rv);
      points.push({ r: r, a: rayAngles[i] });
    }

    const candidates = [];
    for (let a = -120; a <= 120; a += 10) candidates.push(a);
    const g = clamp(goalRel, -120, 120);
    candidates.push(g, clamp(g - 5, -120, 120), clamp(g + 5, -120, 120));
    candidates.push(clamp(g - 10, -120, 120), clamp(g + 10, -120, 120));

    let bestA = g;
    let bestCost = Infinity;
    let bestRisk = Infinity;
    let bestMinS = Infinity;

    for (let ci = 0; ci < candidates.length; ci++) {
      const a = candidates[ci];
      const delta = Math.abs(wrap(a - goalRel));
      let risk = 0;
      let minS = Infinity;
      for (let j = 0; j < points.length; j++) {
        const p = points[j];
        const d = (p.a - a) * rad;
        const along = p.r * Math.cos(d);
        if (along <= 0.08 || along > 11) continue;
        const lateral = Math.abs(p.r * Math.sin(d));
        const width = 0.88 + 0.04 * along;
        if (lateral < width + 0.35) minS = Math.min(minS, along);
        if (lateral < width) {
          const overlap = (width - lateral) / width;
          let urgency = 2.4 + 7 / (along + 0.45);
          if (along < 1.35) urgency += 7;
          risk += overlap * overlap * urgency;
        } else if (lateral < width + 0.5 && along < 3.5) {
          risk += (width + 0.5 - lateral) * 0.16;
        }
      }

      let cost = 0.00085 * delta * delta + 0.000025 * a * a + risk;
      if (mem.avoidSide && Math.abs(a) > 8 &&
          Math.sign(a) !== Math.sign(mem.avoidSide) && delta < 45) {
        cost += 0.08;
      }
      if (cost < bestCost) {
        bestCost = cost;
        bestA = a;
        bestRisk = risk;
        bestMinS = minS;
      }
    }

    if (Math.abs(wrap(bestA - goalRel)) > 12 && Math.abs(bestA) > 8) {
      mem.avoidSide = Math.sign(bestA);
    } else if (Math.abs(wrap(bestA - goalRel)) < 6) {
      mem.avoidSide = 0;
    }

    let clearV = 2.0;
    if (Number.isFinite(bestMinS)) {
      clearV = Math.sqrt(1.3 * Math.max(0, bestMinS - 0.7));
      if (bestMinS < 0.95) clearV = Math.min(clearV, 0.14);
    }
    if (validCount < 3) clearV = Math.min(clearV, 0.85);
    if (bestRisk > 14) clearV = Math.min(clearV, 0.18);
    else if (bestRisk > 8) clearV = Math.min(clearV, 0.35);

    return { a: bestA, risk: bestRisk, clearV: clearV };
  }

  function navigate(goalRel, d, vmax, stopR) {
    const bumpAge = now - num(mem.bumpStart, -1000);
    if (bumpAge >= 0 && bumpAge < 1.2) {
      const side = num(mem.bumpSide, 1);
      if (bumpAge < 0.42) return drive(-0.42, side * 0.50, false);
      return drive(0, side * 0.95, false);
    }

    d = Math.max(0, num(d, 0));
    stopR = Math.max(0, num(stopR, 1));
    if (d <= stopR) return drive(0, 0, false);

    const choice = chooseHeading(wrap(goalRel));
    const alpha = choice.a;
    const err = alpha * rad;
    const avail = Math.max(0, d - stopR);
    let v = Math.min(vmax, Math.sqrt(1.1 * avail), choice.clearV);

    const absA = Math.abs(alpha);
    if (absA > 70) v = Math.min(v, 0.20);
    if (absA > 92) v = 0;
    const cf = Math.cos(absA * rad);
    if (cf < 0.18) v = 0;
    else v *= cf;

    const omega = clamp(1.8 * err - 0.32 * num(mem.yawActual, yawActual),
                        -1.6, 1.6);
    return drive(v, omega, false);
  }

  function relToPoint(tx, ty) {
    const dx = tx - mem.px;
    const dy = ty - mem.py;
    const d = Math.hypot(dx, dy);
    const bearing = d > 0.001 ? Math.atan2(dy, dx) / rad : mem.poseH;
    return { d: d, rel: wrap(bearing - mem.poseH) };
  }

  function fitGradient(cx, cy) {
    const pts = [];
    for (let i = 0; i < mem.sigPts.length; i++) {
      const p = mem.sigPts[i];
      if (now - p.t > 75 || p.t < num(mem.srch ? mem.srch.start : now, now) - 18) continue;
      if (dist(p.x, p.y, cx, cy) > 36) continue;
      pts.push(p);
    }
    if (pts.length < 4) return null;

    let mx = 0, my = 0, ms = 0;
    for (let i = 0; i < pts.length; i++) {
      mx += pts[i].x;
      my += pts[i].y;
      ms += pts[i].s;
    }
    mx /= pts.length;
    my /= pts.length;
    ms /= pts.length;

    let cxx = 0, cyy = 0, cxy = 0, cxs = 0, cys = 0, sst = 0;
    for (let i = 0; i < pts.length; i++) {
      const dx = pts[i].x - mx;
      const dy = pts[i].y - my;
      const ds = pts[i].s - ms;
      cxx += dx * dx;
      cyy += dy * dy;
      cxy += dx * dy;
      cxs += dx * ds;
      cys += dy * ds;
      sst += ds * ds;
    }
    if (cxx + cyy < 8) return null;
    const lam = Math.max(0.5, 0.035 * (cxx + cyy));
    const den = (cxx + lam) * (cyy + lam) - cxy * cxy;
    if (den <= 1e-8) return null;
    const gxg = (cxs * (cyy + lam) - cys * cxy) / den;
    const gyg = (cys * (cxx + lam) - cxs * cxy) / den;
    const mag = Math.hypot(gxg, gyg);
