  if (hardReturn) return baseAction();

  function runCandidate(atBase) {
    for (let attempt = 0; attempt < 4; attempt++) {
      if (mem.activeHint >= 0 &&
          (!mem.hints[mem.activeHint] ||
           mem.hints[mem.activeHint].s !== 0)) {
