        const i = pickCandidate(atBase);
        if (i < 0) return null;
        mem.activeHint = i;
        if (mem.srch && mem.srch.free) mem.srch = null;
        else mem.srch = null;
      }

      const i = mem.activeHint;
      const h = mem.hints[i];
      if (!h || h.s !== 0) {
        clearActive();
        continue;
      }
      const plan = candidatePlan(i, mem.px, mem.py, carried);
      if (plan.time > timeLeft - 4 ||
          plan.need > (atBase ? 1.04 : battery - 0.025)) {
