        mem.gpsFrozen = false;
      }
    }

    const recoveredGps = oldFrozen && rawGpsStep > 0.08;
    const maxGpsJump = Math.max(4.0, Math.abs(vActual) * dt * 6 + 1.5);
    if (gpsValid && !mem.gpsFrozen &&
        (rawGpsStep <= maxGpsJump || recoveredGps)) {
      const err = dist(gx, gy, px, py);
      if (err < 15 || recoveredGps) {
        let alpha = Math.abs(vActual) > 0.2 ? 0.23 : 0.07;
        if (err > 4 && !recoveredGps) alpha = 0.07;
        if (recoveredGps) alpha = 0.48;
        px += (gx - px) * alpha;
        py += (gy - py) * alpha;
      }
    }

    mem.px = px;
    mem.py = py;
    mem.stepDistance = Math.min(0.6, dist(oldX, oldY, px, py));
    mem.odo = num(mem.odo, 0) + Math.abs(step);

    const wasDrivingStraight = vActual > 0.3 &&
      Math.abs(yawActual) < 0.18 &&
      Math.abs(num(mem.prevTargetL, 0) - num(mem.prevTargetR, 0)) < 0.22;
    if (gpsValid && !mem.gpsFrozen && wasDrivingStraight) {
      if (!Number.isFinite(mem.courseX)) {
        mem.courseX = gx;
        mem.courseY = gy;
        mem.courseN = 0;
        mem.courseSin = 0;
        mem.courseCos = 0;
      }
      mem.courseN = num(mem.courseN, 0) + 1;
      mem.courseSin = num(mem.courseSin, 0) + Math.sin(rawH * rad);
      mem.courseCos = num(mem.courseCos, 0) + Math.cos(rawH * rad);
      const courseDist = dist(gx, gy, mem.courseX, mem.courseY);
      if (courseDist > 5 && mem.courseN > 15) {
        const course = Math.atan2(gy - mem.courseY, gx - mem.courseX) / rad;
        const meanRaw = Math.atan2(mem.courseSin, mem.courseCos) / rad;
        const newOff = wrap(course - meanRaw);
        const offErr = wrap(newOff - num(mem.hOff, 0));
        mem.hOff = wrap(num(mem.hOff, 0) + clamp(offErr * 0.25, -9, 9));
        mem.poseH = wrap(mem.poseH + clamp(offErr * 0.08, -3, 3));
        mem.courseX = NaN;
        mem.courseY = NaN;
        mem.courseN = 0;
        mem.courseSin = 0;
        mem.courseCos = 0;
      }
    } else {
      mem.courseX = NaN;
      mem.courseY = NaN;
      mem.courseN = 0;
      mem.courseSin = 0;
      mem.courseCos = 0;
    }

    if (gpsValid) {
      mem.gpsPrevX = gx;
      mem.gpsPrevY = gy;
    }
    mem.prevRawH = rawH;
  }

  const battery = Math.max(0, num(obs.battery, 1));
  const solar = Math.max(0, num(obs.solar, 0));
  const drillProgress = Math.max(0, num(obs.drilling, 0));
  const dockedNow = !!obs.docked;

  if (!mem.energyReady) {
    mem.prevBattery = battery;
    mem.prevSolar = solar;
    mem.energyDist = 0;
    mem.energyDraw = 0;
    mem.drillEnergy = 0;
    mem.drillSeconds = 0;
    mem.energyReady = true;
  } else {
    const netDraw = num(mem.prevBattery, battery) - battery +
      0.5 * (num(mem.prevSolar, solar) + solar) * dt;
    const drillingForEnergy =
      (drillProgress > 0.02 || !!mem.drillIssued) && !dockedNow;

    if (!dockedNow && !drillingForEnergy && Math.abs(vActual) > 0.13) {
      mem.energyDist = num(mem.energyDist, 0) +
        Math.min(0.4, Math.abs(vActual) * dt);
      mem.energyDraw = num(mem.energyDraw, 0) + netDraw;
      if (mem.energyDist >= 7) {
        const measured = mem.energyDraw / Math.max(1, mem.energyDist);
        if (measured > 0.00008 && Number.isFinite(measured)) {
          const target = clamp(measured * 1.18, 0.00025, 0.025);
          mem.ePerM = clamp(0.72 * mem.ePerM + 0.28 * target,
            0.00025, 0.03);
        }
        mem.energyDist = 0;
        mem.energyDraw = 0;
      }
    }

    if (drillingForEnergy) {
      mem.drillSeconds = num(mem.drillSeconds, 0) + dt;
      mem.drillEnergy = num(mem.drillEnergy, 0) + Math.max(0, netDraw);
    } else if (num(mem.drillSeconds, 0) >= 3) {
      const measured = num(mem.drillEnergy, 0) /
        Math.max(1, num(mem.drillSeconds, 0));
      if (measured > 0.00002 && Number.isFinite(measured)) {
        const target = clamp(measured * 1.2, 0.0001, 0.03);
        mem.eDrill = clamp(0.7 * mem.eDrill + 0.3 * target,
          0.0001, 0.04);
      }
      mem.drillSeconds = 0;
      mem.drillEnergy = 0;
    }
    mem.prevBattery = battery;
    mem.prevSolar = solar;
  }

  const science = Math.max(0, num(obs.science, 0));
  const lastSig = mem.sigPts.length
    ? mem.sigPts[mem.sigPts.length - 1]
    : null;
  if (!lastSig ||
      dist(mem.px, mem.py, lastSig.x, lastSig.y) > 1.8 ||
      now - lastSig.t > 5) {
    mem.sigPts.push({ x: mem.px, y: mem.py, s: science, t: now });
    if (mem.sigPts.length > 110) mem.sigPts.shift();
  }

  const carried = Math.max(0, Math.floor(num(obs.carried, 0)));

  function noteSample() {
    const sx = num(mem.drillX, num(mem.siteX, mem.px));
    const sy = num(mem.drillY, num(mem.siteY, mem.py));
    const sv = Math.max(0, num(mem.drillValue, num(mem.siteValue, 0)));
    mem.sampled.push({ x: sx, y: sy, v: sv, t: now });
    if (mem.sampled.length > 80) mem.sampled.shift();

    let closest = -1;
    let closestD = 30;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.s !== 0) continue;
      const d = dist(sx, sy, h.x, h.y);
      if (d < closestD) {
        closestD = d;
        closest = i;
      }
    }
    if (closest >= 0) mem.hints[closest].s = 1;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h && h.s === 0 && dist(sx, sy, h.x, h.y) < 5) h.s = 1;
    }
    const dh = Math.floor(num(mem.drillHint, -1));
    if (dh >= 0 && mem.hints[dh] &&
        dist(sx, sy, mem.hints[dh].x, mem.hints[dh].y) < 30) {
      mem.hints[dh].s = 1;
    }
    if (mem.activeHint >= 0 && mem.hints[mem.activeHint] &&
        mem.hints[mem.activeHint].s !== 0) {
      mem.activeHint = -1;
      mem.search = null;
    }
    mem.drillX = NaN;
    mem.drillY = NaN;
    mem.drillValue = 0;
    mem.drillHint = -1;
    mem.drillIssued = false;
  }

  let justSampled = false;
  if (!Number.isFinite(mem.lastCarried)) {
    mem.lastCarried = carried;
  } else if (carried > mem.lastCarried) {
    justSampled = true;
    noteSample();
  }
  mem.lastCarried = carried;

  const inProgress = !justSampled &&
    (drillProgress > 0.02 ||
      (!!mem.drillIssued && now - num(mem.drillAt, now - 1) < 0.4));

  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  for (let i = 0; i < 9; i++) {
    if (i >= rays.length || !Number.isFinite(Number(rays[i]))) continue;
    const r = Number(rays[i]);
    if (!Number.isFinite(mem.rayPrev[i])) {
      mem.rayPrev[i] = r;
      mem.rayOdo[i] = mem.odo;
      mem.rayTime[i] = now;
      mem.rayHead[i] = mem.poseH;
      continue;
    }
    if (Math.abs(r - mem.rayPrev[i]) > 0.045) {
      mem.rayPrev[i] = r;
      mem.rayOdo[i] = mem.odo;
      mem.rayTime[i] = now;
      mem.rayHead[i] = mem.poseH;
      mem.rayBad[i] = false;
    } else if (r < 14.8 &&
        mem.odo - num(mem.rayOdo[i], mem.odo) > 6 &&
        now - num(mem.rayTime[i], now) > 9 &&
        Math.abs(wrap(mem.poseH - num(mem.rayHead[i], mem.poseH))) > 25) {
      mem.rayBad[i] = true;
    }
  }

  const bumped = !!obs.bumped;
  function clearanceSide() {
    let leftClear = 0, rightClear = 0, nLeft = 0, nRight = 0;
    for (let i = 0; i < 9; i++) {
      const r = i < rays.length ? num(rays[i], 0) : 0;
      if (i > 4) {
        leftClear += r;
        nLeft++;
      } else if (i < 4) {
        rightClear += r;
        nRight++;
      }
    }
    leftClear /= Math.max(1, nLeft);
    rightClear /= Math.max(1, nRight);
    if (Math.abs(leftClear - rightClear) < 0.25) {
      return num(mem.recoverSide, 1) * -1;
    }
    return leftClear >= rightClear ? 1 : -1;
  }
  if (bumped && !mem.bumpPrev) {
    mem.recoverSide = clearanceSide();
    mem.recoverStart = now;
    mem.recoverUntil = now + 1.2;
  }
  mem.bumpPrev = bumped;

  function motorCommand(target, actual, side, slopeComp) {
    let gain = side === 0 ? num(mem.gL, 2.3) : num(mem.gR, 2.3);
    const prevOut = side === 0 ? num(mem.prevOutL, 0) : num(mem.prevOutR, 0);
    const prevTarget = side === 0 ? num(mem.prevTargetL, 0) :
      num(mem.prevTargetR, 0);
    const prevWheel = side === 0 ? num(mem.prevWheelL, actual) :
      num(mem.prevWheelR, actual);

    if (Math.abs(prevTarget) > 0.55 &&
        Math.abs(actual) > 0.25 &&
        Math.abs(actual - prevWheel) < 0.18 &&
        prevOut * prevTarget > 0 &&
        Math.abs(prevOut) < 0.95) {
      const eff = prevOut - num(mem.prevSlope, 0);
      if (Math.abs(eff) > 0.16) {
        const estimate = clamp(Math.abs(actual / eff), 0.65, 4.0);
        gain = clamp(0.985 * gain + 0.015 * estimate, 0.65, 4.0);
        if (side === 0) mem.gL = gain;
        else mem.gR = gain;
      }
    }

    const err = target - actual;
    let integ = side === 0 ? num(mem.iL, 0) : num(mem.iR, 0);
    const proposed = clamp(integ + 0.11 * err * dt, -0.42, 0.42);
    const trial = target / Math.max(0.65, gain) + 0.23 * err +
      proposed + slopeComp;
    if (trial < 1 && trial > -1) integ = proposed;
    else integ *= 0.995;
    if (Math.abs(target) < 0.06 && Math.abs(actual) < 0.06) integ *= 0.94;

    let u = target / Math.max(0.65, gain) + 0.23 * err +
      integ + slopeComp;
    if (Math.abs(target) > 0.16 && target * u > 0 &&
        Math.abs(u) < 0.13 && Math.abs(actual) < Math.abs(target) * 0.8) {
      u = Math.sign(target) * 0.13;
    }
    if (side === 0) mem.iL = integ;
    else mem.iR = integ;
    return clamp(u, -1, 1);
  }

  function drive(v, omega, drill) {
    v = clamp(v, -1.5, 1.5);
    omega = clamp(omega, -2.2, 2.2);
    const pitch = num(obs.pitch, 0);
    const slopeComp = clamp(Math.sin(pitch * rad) * 0.22, -0.20, 0.20);
    const targetL = clamp(v - omega * 0.3, -2.2, 2.2);
    const targetR = clamp(v + omega * 0.3, -2.2, 2.2);
    const left = motorCommand(targetL, wl, 0, slopeComp);
    const right = motorCommand(targetR, wr, 1, slopeComp);
    mem.prevOutL = left;
    mem.prevOutR = right;
    mem.prevTargetL = targetL;
    mem.prevTargetR = targetR;
    mem.prevWheelL = wl;
    mem.prevWheelR = wr;
    mem.prevSlope = slopeComp;
    mem.prevLinearTarget = v;
    mem.drillIssued = !!drill;
    if (drill) mem.drillAt = now;
    return { left: left, right: right, drill: !!drill };
  }

  function chooseSteering(goalRel) {
    const rayAngles = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
    const points = [];
    let validCount = 0;
    for (let i = 0; i < 9; i++) {
      if (i >= rays.length || mem.rayBad[i]) continue;
      const rv = Number(rays[i]);
      if (!Number.isFinite(rv)) continue;
      validCount++;
      if (rv > 0.05 && rv < 14.8) {
        points.push({ r: Math.max(0.12, rv), a: rayAngles[i] });
      }
    }

    let bestA = clamp(goalRel, -80, 80);
    let bestCost = Infinity;
    let bestRisk = Infinity;
    let bestClear = Infinity;

    for (let a = -80; a <= 80; a += 10) {
      const delta = wrap(a - goalRel);
      let cost = 0.0035 * delta * delta + 0.00022 * a * a;
      let risk = 0;
      let clear = Infinity;

      for (let j = 0; j < points.length; j++) {
        const p = points[j];
        const da = (p.a - a) * rad;
        const along = p.r * Math.cos(da);
        const lateral = Math.abs(p.r * Math.sin(da));
        if (along <= 0.1 || along > 8) continue;
        const corridor = 0.72 + 0.035 * along;
        const horizon = clamp((7 - along) / 6, 0, 1);
        if (lateral < corridor) {
          const penetration = (corridor - lateral) / corridor;
          const danger = (5 + 8 / (along + 0.4)) * horizon;
          risk += danger * Math.pow(0.45 + 0.55 * penetration, 2);
          clear = Math.min(clear, along - corridor);
        } else if (lateral < corridor + 0.48 && along < 4.5) {
          risk += (corridor + 0.48 - lateral) * 0.38 * horizon;
          clear = Math.min(clear, along - corridor);
        }
      }
      cost += risk;

      const wx = mem.px + 5 * Math.cos((mem.poseH + a) * rad);
      const wy = mem.py + 5 * Math.sin((mem.poseH + a) * rad);
      const edge = 2.0;
      if (wx < edge || wx > mem.mapSize - edge ||
          wy < edge || wy > mem.mapSize - edge) {
        cost += 18;
      } else {
        const nearestEdge = Math.min(wx, wy, mem.mapSize - wx,
          mem.mapSize - wy);
        if (nearestEdge < 5) cost += (5 - nearestEdge) * 1.5;
      }

      if (cost < bestCost) {
        bestCost = cost;
        bestA = a;
        bestRisk = risk;
        bestClear = clear;
      }
    }

    let safeV = 1.3;
    if (Number.isFinite(bestClear)) {
      safeV = Math.min(safeV,
        Math.sqrt(1.2 * Math.max(0, bestClear - 0.55)));
    }
    if (validCount < 4) safeV = Math.min(safeV, 0.78);
    if (bestRisk > 12) safeV = Math.min(safeV, 0.16);
    else if (bestRisk > 8) safeV = Math.min(safeV, 0.32);
    else if (bestRisk > 5) safeV = Math.min(safeV, 0.62);

    return { a: bestA, risk: bestRisk, clearV: safeV };
  }

  function recoveryCommand() {
    if (now >= num(mem.recoverUntil, 0)) return null;
    const age = now - num(mem.recoverStart, now);
    const side = num(mem.recoverSide, 1);
    if (age < 0.62) return drive(-0.28, side * 0.78, false);
    return drive(0, side * 1.05, false);
  }

  function navigateRel(goalRel, d, vmax, stopR, targetX, targetY) {
    const recovery = recoveryCommand();
    if (recovery) return recovery;

    d = Math.max(0, num(d, 0));
    stopR = Math.max(0, num(stopR, 1));
    if (d <= stopR) {
      mem.navTrack = false;
      return drive(0, 0, false);
    }

    const gr = wrap(goalRel);
    const gxGoal = Number.isFinite(targetX)
      ? targetX
      : mem.px + d * Math.cos((mem.poseH + gr) * rad);
    const gyGoal = Number.isFinite(targetY)
      ? targetY
      : mem.py + d * Math.sin((mem.poseH + gr) * rad);

    if (Math.abs(gr) > 76) {
      mem.navTrack = false;
      const turn = clamp(1.55 * gr * rad, -1.25, 1.25);
      return drive(0, turn, false);
    }

    const choice = chooseSteering(gr);
    const alpha = choice.a;
    const absA = Math.abs(alpha);

    if (d > stopR + 3 && absA < 38) {
      if (!mem.navTrack ||
          dist(gxGoal, gyGoal, num(mem.navGoalX, gxGoal),
            num(mem.navGoalY, gyGoal)) > 4) {
        mem.navTrack = true;
        mem.navGoalX = gxGoal;
        mem.navGoalY = gyGoal;
        mem.navStartX = mem.px;
        mem.navStartY = mem.py;
        mem.navStartT = now;
        mem.navBestD = d;
      } else {
        if (d < num(mem.navBestD, d) - 0.7 ||
            dist(mem.px, mem.py, num(mem.navStartX, mem.px),
              num(mem.navStartY, mem.py)) > 1.1) {
          mem.navStartX = mem.px;
          mem.navStartY = mem.py;
          mem.navStartT = now;
          mem.navBestD = d;
        }
        if (now - num(mem.navStartT, now) > 16 &&
            now > num(mem.recoverCooldown, 0)) {
          mem.recoverSide = clearanceSide();
          mem.recoverStart = now;
          mem.recoverUntil = now + 1.2;
          mem.recoverCooldown = now + 8;
          return recoveryCommand();
        }
      }
    } else {
      mem.navTrack = false;
    }

    const avail = Math.max(0, d - stopR);
    let v = Math.min(vmax, Math.sqrt(1.0 * avail), choice.clearV);
    if (absA > 42) v = Math.min(v, 0.12);
    else if (absA > 30) v = Math.min(v, 0.28);
    else if (absA > 18) v *= 0.72;
    if (choice.risk > 12) v = Math.min(v, 0.12);

    const omega = clamp(1.75 * alpha * rad, -1.3, 1.3);
    return drive(v, omega, false);
  }

  function navigateAbs(tx, ty, vmax, stopR) {
    tx = clamp(tx, 1.5, mem.mapSize - 1.5);
    ty = clamp(ty, 1.5, mem.mapSize - 1.5);
    const dx = tx - mem.px;
    const dy = ty - mem.py;
    const d = Math.hypot(dx, dy);
    const bearing = d > 0.001 ? Math.atan2(dy, dx) / rad : mem.poseH;
    return navigateRel(wrap(bearing - mem.poseH), d, vmax, stopR, tx, ty);
  }

  function pauseSearches() {
    if (mem.search) mem.search.lastOdo = mem.odo;
    if (mem.freeSearch) mem.freeSearch.lastOdo = mem.odo;
  }

  function baseAction() {
    pauseSearches();
    mem.departing = false;
    if (obs.beacon && Number.isFinite(Number(obs.beacon.distance))) {
      const bd = Math.max(0, Number(obs.beacon.distance));
      const bb = num(obs.beacon.bearing, 0);
      return navigateRel(bb, bd, 1.0, 1.15, mem.baseX, mem.baseY);
    }
    const dx = mem.baseX - mem.px;
    const dy = mem.baseY - mem.py;
    const d = Math.hypot(dx, dy);
    const bearing = d > 0.001 ? Math.atan2(dy, dx) / rad : mem.poseH;
    return navigateRel(wrap(bearing - mem.poseH), d, 1.0, 1.15,
      mem.baseX, mem.baseY);
  }

  function returnEnergy(d, load) {
    const n = Math.max(0, load);
    return 0.12 + Math.max(0, d) * mem.ePerM *
      1.9 * (1 + 0.13 * n) + 0.012 * n;
  }

  function returnSeconds(d, load) {
    return Math.max(0, d) * 1.85 + 24 + 5 * Math.max(0, load);
  }

  function hintBudget(h) {
    return clamp(130 + 10 * Math.sqrt(Math.max(0.1, h.v)), 140, 185);
  }

  function planHint(i, fromX, fromY, load) {
    const h = mem.hints[i];
    if (!h) return { need: Infinity, time: Infinity, dNow: Infinity,
      dBack: Infinity, total: Infinity };
    const dNow = dist(fromX, fromY, h.x, h.y);
    const dBack = dist(h.x, h.y, mem.baseX, mem.baseY);
    let remaining = hintBudget(h);
    if (mem.search && mem.activeHint === i) {
      remaining = Math.max(0, num(mem.search.budget, remaining) -
        num(mem.search.spent, 0));
    }
    const total = dNow + dBack + remaining + 12;
    const need = 0.115 + total * mem.ePerM * 1.42 *
      (1 + 0.13 * Math.max(0, load)) + 0.02;
    const time = total * 1.72 + 40;
    return { need: need, time: time, dNow: dNow, dBack: dBack,
      total: total };
  }

  function pickHint(atBase) {
    let best = -1;
    let bestScore = -Infinity;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.s !== 0) continue;
      const p = planHint(i, mem.px, mem.py, carried);
      if (p.time > timeLeft - 12) continue;
      if (atBase) {
        if (p.need > 1.045) continue;
      } else if (p.need > battery - 0.025) {
        continue;
      }

      let cluster = 0;
      for (let j = 0; j < mem.hints.length; j++) {
        if (j === i) continue;
        const q = mem.hints[j];
        if (!q || q.s !== 0) continue;
        const dd = dist(h.x, h.y, q.x, q.y);
        if (dd < 35) cluster += q.v * (1 - dd / 35);
      }
      const effective = h.v + Math.min(h.v * 0.8, cluster * 0.15);
      const denom = 45 + p.dNow + 0.75 * p.dBack + 0.35 * p.total;
      const score = effective / Math.pow(Math.max(1, denom), 0.88);
      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }
    return best;
  }

  function fitGradient(cx, cy) {
    const pts = [];
    for (let i = 0; i < mem.sigPts.length; i++) {
      const p = mem.sigPts[i];
      if (now - p.t > 90 || dist(p.x, p.y, cx, cy) > 38) continue;
      pts.push(p);
    }
    if (pts.length < 5) return null;

    let mx = 0, my = 0, ms = 0;
    for (let i = 0; i < pts.length; i++) {
      mx += pts[i].x;
      my += pts[i].y;
      ms += pts[i].s;
    }
    mx /= pts.length;
    my /= pts.length;
    ms /= pts.length;

    let cxx = 0, cyy = 0, cxy = 0, cxs = 0, cys = 0;
    let sst = 0;
    for (let i = 0; i < pts.length; i++) {
      const dx = pts[i].x - mx;
      const dy = pts[i].y - my;
      const ds = pts[i].s - ms;
      cxx += dx * dx;
      cyy += dy * dy;
      cxy += dx * dy;
      cxs += dx * ds;
      cys += dy * ds;
      sst += ds * ds;
    }
    const spread = cxx + cyy;
    if (spread < 12 || sst < 1e-8) return null;

    const lam = Math.max(0.2, spread * 0.025);
    const den = (cxx + lam) * (cyy + lam) - cxy * cxy;
    if (den <= 1e-9) return null;
    const gxg = (cxs * (cyy + lam) - cys * cxy) / den;
    const gyg = (cys * (cxx + lam) - cxs * cxy) / den;
    const mag = Math.hypot(gxg, gyg);
    const delta = mag * 9;
    if (!Number.isFinite(delta) ||
        delta < Math.max(0.0018, Math.abs(ms) * 0.022)) return null;
    return { x: gxg, y: gyg, mag: mag, delta: delta, mean: ms };
  }

  function beginSearch(cx, cy, free, budget) {
    return {
      cx: cx,
      cy: cy,
      free: !!free,
      index: 1,
      start: now,
      budget: budget,
      spent: 0,
      lastOdo: mem.odo,
      guideActive: false,
      guideX: 0,
      guideY: 0,
      guideStart: 0,
      guideCount: 0,
      guideCooldown: now + 8
    };
  }

  function searchDirective(s) {
    const odoNow = num(mem.odo, 0);
    if (Number.isFinite(s.lastOdo)) {
      s.spent = num(s.spent, 0) + Math.max(0, odoNow - s.lastOdo);
    }
    s.lastOdo = odoNow;

    if (s.spent > s.budget || s.index >= mem.spiral.length) {
      return { failed: true };
    }

    if (s.guideActive) {
      if (dist(mem.px, mem.py, s.guideX, s.guideY) < 2.6 ||
          now - s.guideStart > 24) {
        s.guideActive = false;
        s.guideCooldown = now + 9;
      } else {
        return {
          failed: false,
          x: s.guideX,
          y: s.guideY,
          vmax: 1.0,
          stop: 1.8
        };
      }
    }

    while (s.index < mem.spiral.length) {
      const p = mem.spiral[s.index];
      const tx = s.cx + p[0];
      const ty = s.cy + p[1];
      if (tx < 2 || tx > mem.mapSize - 2 ||
          ty < 2 || ty > mem.mapSize - 2) {
        s.index++;
        continue;
      }
      if (dist(mem.px, mem.py, tx, ty) < 2.5) {
        s.index++;
        continue;
      }
      break;
    }
    if (s.index >= mem.spiral.length) return { failed: true };

    if (s.guideCount < 3 && now >= num(s.guideCooldown, 0) &&
        s.index >= 3) {
      const g = fitGradient(s.cx, s.cy);
      if (g) {
        const tx = clamp(mem.px + 9 * g.x / g.mag, 2, mem.mapSize - 2);
        const ty = clamp(mem.py + 9 * g.y / g.mag, 2, mem.mapSize - 2);
        if (dist(tx, ty, s.cx, s.cy) < 31 &&
            dist(tx, ty, mem.px, mem.py) > 4) {
          s.guideActive = true;
          s.guideX = tx;
          s.guideY = ty;
          s.guideStart = now;
          s.guideCount++;
          return {
            failed: false,
            x: tx,
            y: ty,
            vmax: 1.0,
            stop: 1.8
          };
        }
      }
    }

    const p = mem.spiral[s.index];
    return {
      failed: false,
      x: s.cx + p[0],
      y: s.cy + p[1],
      vmax: 1.12,
      stop: 1.8
    };
  }

  function clearActiveHint() {
    mem.activeHint = -1;
    mem.search = null;
  }

  function hintAction() {
    const i = Math.floor(num(mem.activeHint, -1));
    const h = i >= 0 ? mem.hints[i] : null;
    if (!h || h.s !== 0) {
      clearActiveHint();
      return null;
    }

    if (!mem.search || mem.search.free ||
        dist(mem.search.cx, mem.search.cy, h.x, h.y) > 1.5) {
      const d = dist(mem.px, mem.py, h.x, h.y);
      if (d > 4.5) return navigateAbs(h.x, h.y, 1.18, 2.8);
      mem.search = beginSearch(h.x, h.y, false, hintBudget(h));
    }

    const q = searchDirective(mem.search);
    if (q.failed) {
      h.s = 2;
      clearActiveHint();
      return null;
    }
    return navigateAbs(q.x, q.y, q.vmax, q.stop);
  }

  function runCandidates(atBase) {
    for (let attempt = 0; attempt < 6; attempt++) {
      let i = Math.floor(num(mem.activeHint, -1));
      if (i < 0 || !mem.hints[i] || mem.hints[i].s !== 0) {
        i = pickHint(atBase);
        if (i < 0) return null;
        mem.activeHint = i;
        if (mem.search && mem.search.free) mem.search = null;
      }

      const h = mem.hints[i];
      if (!h || h.s !== 0) {
        clearActiveHint();
        continue;
      }
      const p = planHint(i, mem.px, mem.py, carried);
      if (p.time > timeLeft - 10) {
        h.s = 2;
        clearActiveHint();
        continue;
      }
      if (atBase && p.need > 1.045) {
        h.s = 2;
        clearActiveHint();
        continue;
      }
      if (!atBase && p.need > battery - 0.025) return null;

      if (atBase && battery + 0.005 < p.need) {
        pauseSearches();
        return drive(0, 0, false);
      }
      if (atBase) mem.departing = true;
      const out = hintAction();
      if (out) return out;
    }
    return null;
  }

  function startFreeSearch() {
    mem.freeSearch = beginSearch(mem.baseX, mem.baseY, true, 90);
  }

  function runFreeSearch(atBase) {
    if (!mem.freeSearch) {
      if (!atBase || mem.freeDone || now < num(mem.freeCooldownUntil, 0)) {
        return null;
      }
      startFreeSearch();
    }

    const s = mem.freeSearch;
    const remaining = Math.max(0, s.budget - s.spent);
    const dNow = dist(mem.px, mem.py, s.cx, s.cy);
    const dBack = dist(s.cx, s.cy, mem.baseX, mem.baseY);
    const total = dNow + dBack + remaining + 10;
    const need = 0.12 + total * mem.ePerM * 1.42 *
      (1 + 0.13 * carried) + 0.02;
    const timeNeed = total * 1.72 + 30;

    if (timeNeed > timeLeft - 8 || need > 1.045) {
      mem.freeSearch = null;
      mem.freeDone = true;
      return null;
    }
    if (atBase && battery + 0.005 < need) {
      pauseSearches();
      return drive(0, 0, false);
    }
    if (!atBase && battery < need - 0.025) return null;
    if (atBase) mem.departing = true;

    const q = searchDirective(s);
    if (q.failed) {
      mem.freeSearch = null;
      mem.freeDone = true;
      mem.freeCooldownUntil = now + 120;
      return null;
    }
    return navigateAbs(q.x, q.y, q.vmax, q.stop);
  }

  const baseD = dist(mem.px, mem.py, mem.baseX, mem.baseY);
  if (mem.departing && !obs.docked && baseD > 4.2) {
    mem.departing = false;
  }
  let atBaseZone = !!obs.docked ||
    (baseD < 2.7 && !mem.departing);

  if (atBaseZone && carried === 0) {
    mem.returning = false;
  }

  const remainingDrill = clamp(6 - drillProgress, 0, 6);
  const canFinishDrill = inProgress && carried < mem.capacity &&
    battery > returnEnergy(baseD, carried + 1) +
      remainingDrill * mem.eDrill + 0.04 &&
    timeLeft > returnSeconds(baseD, carried + 1) +
      remainingDrill + 8;

  let hardReturn = !atBaseZone &&
    (carried >= mem.capacity ||
      battery < returnEnergy(baseD, carried) + 0.035 ||
      battery < 0.055 ||
      timeLeft < returnSeconds(baseD, carried) + 6);
  if (mem.returning && !atBaseZone) hardReturn = true;
  if (canFinishDrill && !mem.returning) hardReturn = false;
  if (hardReturn) {
    mem.returning = true;
    mem.departing = false;
  }

  if (atBaseZone && carried > 0) {
    if (obs.docked) {
      mem.returning = false;
      mem.departing = false;
      return drive(0, 0, false);
    }
    return baseAction();
  }

  if (mem.returning && !atBaseZone) {
    return baseAction();
  }

  const siteObj = obs.site && typeof obs.site === "object"
    ? obs.site
    : null;

  function siteAction() {
    let sd = 0;
    let sb = 0;
    let sx = mem.siteX;
    let sy = mem.siteY;
    let sv = mem.siteValue;

    if (siteObj) {
      sd = Math.max(0, num(siteObj.distance, 99));
      sb = num(siteObj.bearing, 0);
      sv = Math.max(0.1, num(siteObj.value, 1));
      const abs = (mem.poseH + sb) * rad;
      const measuredX = mem.px + sd * Math.cos(abs);
      const measuredY = mem.py + sd * Math.sin(abs);
      if (!inProgress || !Number.isFinite(sx) ||
          dist(sx, sy, measuredX, measuredY) > 4) {
        sx = measuredX;
        sy = measuredY;
      } else {
        sx = 0.65 * sx + 0.35 * measuredX;
        sy = 0.65 * sy + 0.35 * measuredY;
      }
      mem.siteX = sx;
      mem.siteY = sy;
      mem.siteValue = sv;
      mem.siteLast = now;
    } else if (Number.isFinite(mem.drillX) &&
        Number.isFinite(mem.drillY)) {
      sx = mem.drillX;
      sy = mem.drillY;
      const dx = sx - mem.px;
      const dy = sy - mem.py;
      sd = Math.hypot(dx, dy);
      const bearing = sd > 0.001 ? Math.atan2(dy, dx) / rad : mem.poseH;
      sb = wrap(bearing - mem.poseH);
      sv = mem.drillValue;
    } else {
      return null;
    }

    const homeFromSite = dist(sx, sy, mem.baseX, mem.baseY);
    const travelToSite = Math.max(0, sd - 1.1);
    const projectedNeed = returnEnergy(homeFromSite, carried + 1) +
      0.025 + travelToSite * mem.ePerM * 1.35;
    const projectedTime = returnSeconds(homeFromSite, carried + 1) +
      travelToSite * 1.8 + remainingDrill + 10;

    const canFinishHere = inProgress && carried < mem.capacity &&
      battery > returnEnergy(homeFromSite, carried + 1) +
        remainingDrill * mem.eDrill + 0.045 &&
      timeLeft > returnSeconds(homeFromSite, carried + 1) +
        remainingDrill + 10;

    if (!canFinishHere &&
        (carried >= mem.capacity ||
          battery < projectedNeed ||
          timeLeft < projectedTime)) {
      if (atBaseZone && obs.docked) {
        pauseSearches();
        return drive(0, 0, false);
      }
      mem.returning = true;
      mem.departing = false;
      return baseAction();
    }

    if (atBaseZone && sd > 1.8) mem.departing = true;

    const still = Math.abs(vActual) < 0.12 &&
      Math.max(Math.abs(wl), Math.abs(wr)) < 0.19;
    if (sd <= 1.36 && still) {
      if (!inProgress || !Number.isFinite(mem.drillX)) {
        mem.drillX = sx;
        mem.drillY = sy;
        mem.drillValue = sv;
        mem.drillHint = mem.activeHint;
      }
      return drive(0, 0, true);
    }

    if (sd <= 1.36) return drive(0, 0, false);

    let vmax = 1.0;
    if (sd > 5) vmax = 1.0;
    else if (sd > 2.6) vmax = 0.58;
    else vmax = 0.30;
    return navigateRel(sb, sd, vmax, 0.82, sx, sy);
  }

  if (siteObj || inProgress) {
    const out = siteAction();
    if (out) return out;
  }

  if (atBaseZone) {
    if (!obs.docked && !mem.departing) return baseAction();
    const out = runCandidates(true);
    if (out) return out;
    const freeOut = runFreeSearch(true);
    if (freeOut) return freeOut;
    return drive(0, 0, false);
  }

  const candidateOut = runCandidates(false);
  if (candidateOut) return candidateOut;

  if (mem.freeSearch) {
    const freeOut = runFreeSearch(false);
    if (freeOut) return freeOut;
  }

  mem.returning = true;
  return baseAction();
}

function act(obs, mem) {
  if (!mem || typeof mem !== "object") mem = {};

  const rad = Math.PI / 180;
  const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
  const num = (v, d) => {
    const x = Number(v);
    return Number.isFinite(x) ? x : d;
  };
  const wrap = (a) => {
    a %= 360;
    if (a > 180) a -= 360;
    if (a < -180) a += 360;
    return a;
  };
  const dist = (x1, y1, x2, y2) => Math.hypot(x1 - x2, y1 - y2);

  function buildSpiral(step, maxR) {
    const pts = [[0, 0]];
    let x = 0, y = 0, dir = 0, len = 1, stop = false;
    for (let k = 0; k < 100 && !stop; k++) {
      for (let rep = 0; rep < 2 && !stop; rep++) {
        for (let j = 0; j < len; j++) {
          if (dir === 0) x += step;
          else if (dir === 1) y += step;
          else if (dir === 2) x -= step;
          else y -= step;
          if (Math.hypot(x, y) > maxR) {
            stop = true;
            break;
          }
          pts.push([x, y]);
        }
        dir = (dir + 1) % 4;
      }
      len++;
    }
    return pts;
  }

  const mission = obs && obs.mission ? obs.mission : {};
  if (!mem._init) {
    const b = mission.base || {};
    mem.baseX = num(b.x, num(obs && obs.x, 0));
    mem.baseY = num(b.y, num(obs && obs.y, 0));
    mem.mapSize = Math.max(40, num(mission.size, 400));
    mem.totalSeconds = Math.max(1, num(mission.seconds, 1200));
    mem.capacity = Math.max(1, Math.floor(num(mission.capacity, 5)));

    mem.hints = [];
    const hs = Array.isArray(mission.hints) ? mission.hints : [];
    for (let i = 0; i < hs.length; i++) {
      const h = hs[i] || {};
      const x = Number(h.x), y = Number(h.y);
      if (Number.isFinite(x) && Number.isFinite(y)) {
        mem.hints.push({
          x: clamp(x, 2, mem.mapSize - 2),
          y: clamp(y, 2, mem.mapSize - 2),
          v: Math.max(0.1, num(h.estimate, 1)),
          s: 0
        });
      }
    }

    mem.spiral = buildSpiral(7, 29);
    mem.activeHint = -1;
    mem.search = null;
    mem.freeSearch = null;
    mem.freeIndex = 0;
    mem.freeWaitStart = -1;
    mem.energyWaitStart = -1;
    mem.energyWaitKey = "";
    mem.returning = false;

    mem.sampled = [];
    mem.sigPts = [];
    mem.siteValid = false;
    mem.siteX = NaN;
    mem.siteY = NaN;
    mem.siteValue = 0;
    mem.siteLast = -100;
    mem.drillX = NaN;
    mem.drillY = NaN;
    mem.drillValue = 0;
    mem.drillHint = -1;
    mem.drillIssued = false;

    mem.ePerM = 0.00075;
    mem.eDrill = 0.002;
    mem.energyReady = false;
    mem.energyDist = 0;
    mem.energyDrop = 0;
    mem.drillEnergy = 0;
    mem.drillSeconds = 0;

    mem.gL = 2.3;
    mem.gR = 2.3;
    mem.minCmdL = 0.09;
    mem.minCmdR = 0.09;
    mem.stallL = 0;
    mem.stallR = 0;
    mem.prevOutL = 0;
    mem.prevOutR = 0;
    mem.prevTargetL = 0;
    mem.prevTargetR = 0;
    mem.prevWheelL = 0;
    mem.prevWheelR = 0;
    mem.prevSlope = 0;

    mem.poseReady = false;
    mem.hEst = 0;
    mem.hOff = 0;
    mem.odo = 0;
    mem.gpsFrozen = false;
    mem.gpsRepeat = 0;
    mem.gpsStillOdo = 0;
    mem.calX = NaN;
    mem.calY = NaN;
    mem.calN = 0;
    mem.calSin = 0;
    mem.calCos = 0;

    mem.rayPrev = new Array(9);
    mem.rayBad = new Array(9).fill(false);
    mem.rayOdo = new Array(9).fill(0);
    mem.rayTime = new Array(9).fill(0);
    mem.rayHead = new Array(9).fill(0);

    mem.bumpPrev = false;
    mem.recoverStart = -1000;
    mem.recoverUntil = -1000;
    mem.recoverSide = 1;
    mem.recoverCooldown = 0;
    mem.navTrack = false;
    mem.lastCarried = NaN;
    mem._init = true;
  }

  if (!Array.isArray(mem.hints)) mem.hints = [];
  if (!Array.isArray(mem.spiral) || mem.spiral.length < 2) {
    mem.spiral = buildSpiral(7, 29);
  }
  if (!Array.isArray(mem.sigPts)) mem.sigPts = [];
  if (!Array.isArray(mem.sampled)) mem.sampled = [];
  if (!Array.isArray(mem.rayPrev)) mem.rayPrev = new Array(9);
  if (!Array.isArray(mem.rayBad)) mem.rayBad = new Array(9).fill(false);
  if (!Array.isArray(mem.rayOdo)) mem.rayOdo = new Array(9).fill(0);
  if (!Array.isArray(mem.rayTime)) mem.rayTime = new Array(9).fill(0);
  if (!Array.isArray(mem.rayHead)) mem.rayHead = new Array(9).fill(0);
  if (!Number.isFinite(mem.ePerM)) mem.ePerM = 0.00075;
  if (!Number.isFinite(mem.eDrill)) mem.eDrill = 0.002;
  if (!Number.isFinite(mem.activeHint)) mem.activeHint = -1;
  if (!Number.isFinite(mem.freeIndex)) mem.freeIndex = 0;

  const hasTimeLeft = obs && obs.timeLeft !== undefined &&
    obs.timeLeft !== null && Number.isFinite(Number(obs.timeLeft));
  const now = obs && Number.isFinite(Number(obs.t))
    ? Math.max(0, Number(obs.t))
    : Math.max(0, mem.totalSeconds - num(obs && obs.timeLeft, mem.totalSeconds));
  const timeLeft = hasTimeLeft
    ? Math.max(0, Number(obs.timeLeft))
    : Math.max(0, mem.totalSeconds - now);

  let dt = 0.1;
  if (Number.isFinite(mem.prevNow)) {
    const d = now - mem.prevNow;
    if (d > 0.015 && d < 0.8) dt = d;
  }
  dt = clamp(dt, 0.03, 0.3);
  mem.prevNow = now;

  const rawH = wrap(num(obs.heading, 0));
  const wl = num(obs.wheelLeft, 0);
  const wr = num(obs.wheelRight, 0);
  const vActual = clamp((wl + wr) * 0.5, -3.2, 3.2);
  const yawActual = clamp((wr - wl) / 0.6, -8, 8);
  const gpsValid = Number.isFinite(Number(obs.x)) &&
    Number.isFinite(Number(obs.y));
  const gx = gpsValid ? Number(obs.x) : NaN;
  const gy = gpsValid ? Number(obs.y) : NaN;

  if (!mem.poseReady) {
    mem.px = gpsValid ? gx : mem.baseX;
    mem.py = gpsValid ? gy : mem.baseY;
    mem.hEst = rawH;
    mem.hOff = 0;
    mem.gpsPrevX = gpsValid ? gx : NaN;
    mem.gpsPrevY = gpsValid ? gy : NaN;
    mem.gpsFrozen = false;
    mem.gpsRepeat = 0;
    mem.gpsStillOdo = 0;
    mem.odo = 0;
    mem.stepDistance = 0;
    mem.prevRawH = rawH;
    mem.poseReady = true;
  } else {
    const oldX = mem.px;
    const oldY = mem.py;
    const oldH = mem.hEst;
    const yawDeg = yawActual * dt / rad;
    let predH = wrap(oldH + yawDeg);
    const compass = wrap(rawH + num(mem.hOff, 0));
    const compassErr = wrap(compass - predH);

    // Reject abrupt compass faults; wheel yaw and GPS course correct them.
    if (Math.abs(compassErr) < 48) {
      const gain = Math.abs(yawActual) > 0.5 ? 0.24 : 0.16;
      predH = wrap(predH + gain * compassErr);
    }
    mem.hEst = predH;

    const step = clamp(vActual * dt, -0.5, 0.5);
    const midH = wrap(oldH + yawDeg * 0.5) * rad;
    let px = oldX + step * Math.cos(midH);
    let py = oldY + step * Math.sin(midH);

    let rawGpsStep = Infinity;
    if (gpsValid && Number.isFinite(mem.gpsPrevX) &&
        Number.isFinite(mem.gpsPrevY)) {
      rawGpsStep = dist(gx, gy, mem.gpsPrevX, mem.gpsPrevY);
      if (rawGpsStep < 0.025 && Math.abs(vActual) > 0.25) {
        mem.gpsRepeat = num(mem.gpsRepeat, 0) + 1;
        mem.gpsStillOdo = num(mem.gpsStillOdo, 0) + Math.abs(step);
        if (mem.gpsRepeat > 18 && mem.gpsStillOdo > 1.1) {
          mem.gpsFrozen = true;
        }
      } else if (rawGpsStep > 0.055) {
        mem.gpsRepeat = 0;
        mem.gpsStillOdo = 0;
        mem.gpsFrozen = false;
      }
    }

    const recoveredGps = !!mem.gpsFrozen && rawGpsStep > 0.35;
    if (recoveredGps) mem.gpsFrozen = false;

    let gpsAccepted = false;
    if (gpsValid && !mem.gpsFrozen) {
      const maxJump = Math.max(5, Math.abs(vActual) * dt * 8 + 2);
      if (rawGpsStep <= maxJump || !Number.isFinite(rawGpsStep) ||
          recoveredGps) {
        const err = dist(gx, gy, px, py);
        if (err < 15 || recoveredGps) {
          let alpha = Math.abs(vActual) > 0.2 ? 0.70 : 0.38;
          if (err > 4) alpha = 0.82;
          if (err > 11 && !recoveredGps) alpha = 0.18;
          if (recoveredGps) alpha = 0.75;
          px += (gx - px) * alpha;
          py += (gy - py) * alpha;
          gpsAccepted = true;
        }
      }
    }

    mem.px = px;
    mem.py = py;
    mem.stepDistance = dist(oldX, oldY, px, py);
    mem.odo = num(mem.odo, 0) + Math.abs(step);

    // A straight GPS track is a direct heading measurement, including after
    // a compass jump or a newly acquired compass bias.
    if (gpsAccepted && !mem.gpsFrozen && vActual > 0.28 &&
        Math.abs(yawActual) < 0.20) {
      if (!Number.isFinite(mem.calX) || !Number.isFinite(mem.calY)) {
        mem.calX = gx;
        mem.calY = gy;
        mem.calN = 0;
        mem.calSin = 0;
        mem.calCos = 0;
      }
      mem.calN = num(mem.calN, 0) + 1;
      mem.calSin = num(mem.calSin, 0) + Math.sin(rawH * rad);
      mem.calCos = num(mem.calCos, 0) + Math.cos(rawH * rad);
      const cd = dist(gx, gy, mem.calX, mem.calY);
      if (cd >= 2.8 && mem.calN >= 10) {
        const coherence = Math.hypot(mem.calSin, mem.calCos) /
          Math.max(1, mem.calN);
        const course = Math.atan2(gy - mem.calY, gx - mem.calX) / rad;
        if (coherence > 0.60) {
          const meanRaw = Math.atan2(mem.calSin, mem.calCos) / rad;
          const targetOff = wrap(course - meanRaw);
          const offErr = wrap(targetOff - num(mem.hOff, 0));
          mem.hOff = wrap(num(mem.hOff, 0) +
            clamp(offErr * 0.55, -35, 35));
        }
        const headingErr = wrap(course - mem.hEst);
        if (Math.abs(headingErr) > 55) {
          mem.hEst = wrap(course);
        } else {
          mem.hEst = wrap(mem.hEst +
            clamp(headingErr * 0.75, -22, 22));
        }
        mem.calX = gx;
        mem.calY = gy;
        mem.calN = 0;
        mem.calSin = 0;
        mem.calCos = 0;
      }
    } else {
      mem.calX = NaN;
      mem.calY = NaN;
      mem.calN = 0;
      mem.calSin = 0;
      mem.calCos = 0;
    }

    if (gpsValid) {
      mem.gpsPrevX = gx;
      mem.gpsPrevY = gy;
    }
    mem.prevRawH = rawH;
  }

  const battery = Math.max(0, num(obs.battery, 1));
  const solar = Math.max(0, num(obs.solar, 0));
  const drillProgress = Math.max(0, num(obs.drilling, 0));
  const dockedNow = !!obs.docked;

  if (!mem.energyReady) {
    mem.prevBattery = battery;
    mem.energyDist = 0;
    mem.energyDrop = 0;
    mem.drillEnergy = 0;
    mem.drillSeconds = 0;
    mem.energyReady = true;
  } else {
    const drop = num(mem.prevBattery, battery) - battery;
    const drillingForEnergy =
      (drillProgress > 0.01 || !!mem.drillIssued) && !dockedNow;

    if (!dockedNow && !drillingForEnergy && Math.abs(vActual) > 0.16) {
      const dd = Math.max(Math.abs(vActual) * dt * 0.30,
        Math.min(0.45, num(mem.stepDistance, 0)));
      mem.energyDist = num(mem.energyDist, 0) + dd;
      mem.energyDrop = num(mem.energyDrop, 0) + Math.max(0, drop);
      if (mem.energyDist >= 9) {
        const measured = mem.energyDrop / Math.max(1, mem.energyDist);
        if (measured > 0.00012 && Number.isFinite(measured)) {
          const target = clamp(measured * 1.8, 0.00035, 0.025);
          mem.ePerM = clamp(0.84 * mem.ePerM + 0.16 * target,
            0.0004, 0.03);
        }
        mem.energyDist = 0;
        mem.energyDrop = 0;
      }
    }

    if (drillingForEnergy) {
      mem.drillSeconds = num(mem.drillSeconds, 0) + dt;
      mem.drillEnergy = num(mem.drillEnergy, 0) + Math.max(0, drop);
    } else if (num(mem.drillSeconds, 0) >= 3) {
      const measured = num(mem.drillEnergy, 0) /
        Math.max(1, num(mem.drillSeconds, 0));
      if (measured > 0.00002 && Number.isFinite(measured)) {
        const target = clamp(measured * 1.4, 0.0001, 0.03);
        mem.eDrill = clamp(0.75 * mem.eDrill + 0.25 * target,
          0.0001, 0.04);
      }
      mem.drillSeconds = 0;
      mem.drillEnergy = 0;
    }

    mem.prevBattery = battery;
  }

  const science = Math.max(0, num(obs.science, 0));
  const lastSig = mem.sigPts.length
    ? mem.sigPts[mem.sigPts.length - 1]
    : null;
  if (!lastSig ||
      dist(mem.px, mem.py, lastSig.x, lastSig.y) > 1.5 ||
      now - lastSig.t > 3) {
    mem.sigPts.push({ x: mem.px, y: mem.py, s: science, t: now });
    if (mem.sigPts.length > 100) mem.sigPts.shift();
  }

  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  for (let i = 0; i < 9; i++) {
    if (i >= rays.length || !Number.isFinite(Number(rays[i]))) continue;
    const r = Number(rays[i]);
    if (!Number.isFinite(mem.rayPrev[i])) {
      mem.rayPrev[i] = r;
      mem.rayOdo[i] = num(mem.odo, 0);
      mem.rayTime[i] = now;
      mem.rayHead[i] = mem.hEst;
    } else if (Math.abs(r - mem.rayPrev[i]) > 0.045) {
      mem.rayPrev[i] = r;
      mem.rayOdo[i] = num(mem.odo, 0);
      mem.rayTime[i] = now;
      mem.rayHead[i] = mem.hEst;
      mem.rayBad[i] = false;
    } else if (r < 14.8 &&
        num(mem.odo, 0) - num(mem.rayOdo[i], 0) > 5.5 &&
        now - num(mem.rayTime[i], now) > 8 &&
        Math.abs(wrap(mem.hEst - num(mem.rayHead[i], mem.hEst))) > 25) {
      mem.rayBad[i] = true;
    }
  }

  function clearanceSide() {
    let left = 0, right = 0, nl = 0, nr = 0;
    for (let i = 0; i < 9; i++) {
      if (i >= rays.length || !Number.isFinite(Number(rays[i]))) continue;
      const r = Number(rays[i]);
      if (i > 4) {
        left += r;
        nl++;
      } else if (i < 4) {
        right += r;
        nr++;
      }
    }
    const l = left / Math.max(1, nl);
    const r = right / Math.max(1, nr);
    if (Math.abs(l - r) < 0.25) return -num(mem.recoverSide, 1);
    return l >= r ? 1 : -1;
  }

  function startRecovery(side) {
    mem.recoverSide = side >= 0 ? 1 : -1;
    mem.recoverStart = now;
    mem.recoverUntil = now + 1.15;
    mem.recoverCooldown = now + 10;
    mem.navTrack = false;
  }

  const bumped = !!obs.bumped;
  if (bumped && !mem.bumpPrev) startRecovery(clearanceSide());
  mem.bumpPrev = bumped;

  const carried = Math.max(0, Math.floor(num(obs.carried, 0)));

  function noteSample() {
    const sx = num(mem.drillX, num(mem.siteX, mem.px));
    const sy = num(mem.drillY, num(mem.siteY, mem.py));
    const sv = Math.max(0, num(mem.drillValue, num(mem.siteValue, 0)));
    mem.sampled.push({ x: sx, y: sy, v: sv, t: now });
    if (mem.sampled.length > 80) mem.sampled.shift();

    let closest = -1;
    let closestD = 14;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.s !== 0) continue;
      const d = dist(sx, sy, h.x, h.y);
      if (d < closestD) {
        closestD = d;
        closest = i;
      }
    }
    if (closest >= 0) mem.hints[closest].s = 2;

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h && h.s === 0 && dist(sx, sy, h.x, h.y) < 6) h.s = 2;
    }

    const hi = Math.floor(num(mem.drillHint, -1));
    if (hi >= 0 && mem.hints[hi] &&
        dist(sx, sy, mem.hints[hi].x, mem.hints[hi].y) < 35) {
      mem.hints[hi].s = 2;
    }

    if (mem.activeHint >= 0 && mem.hints[mem.activeHint] &&
        mem.hints[mem.activeHint].s !== 0) {
      mem.activeHint = -1;
      mem.search = null;
    }

    mem.drillX = NaN;
    mem.drillY = NaN;
    mem.drillValue = 0;
    mem.drillHint = -1;
    mem.drillIssued = false;
    mem.siteValid = false;
  }

  let justSampled = false;
  if (!Number.isFinite(mem.lastCarried)) {
    mem.lastCarried = carried;
  } else if (carried > mem.lastCarried) {
    justSampled = true;
    noteSample();
  }
  mem.lastCarried = carried;

  const siteObj = obs.site && typeof obs.site === "object"
    ? obs.site
    : null;

  const priorDrillCommand = !!mem.drillIssued;
  const inProgress = !justSampled &&
    (drillProgress > 0.01 ||
      (priorDrillCommand && now - num(mem.drillAt, now - 1) < 0.5));

  if (siteObj) {
    const sd = Math.max(0, num(siteObj.distance, 99));
    const sb = num(siteObj.bearing, 0);
    if (!inProgress) {
      const a = (mem.hEst + sb) * rad;
      mem.siteX = mem.px + sd * Math.cos(a);
      mem.siteY = mem.py + sd * Math.sin(a);
      mem.siteValue = Math.max(0.1, num(siteObj.value, 1));
    }
    mem.siteValid = true;
    mem.siteLast = now;
  } else if (inProgress) {
    mem.siteValid = true;
  }

  function motorCommand(target, actual, side, slopeComp) {
    let gain = side === 0 ? num(mem.gL, 2.3) : num(mem.gR, 2.3);
    const prevOut = side === 0 ? num(mem.prevOutL, 0) : num(mem.prevOutR, 0);
    const prevTarget = side === 0
      ? num(mem.prevTargetL, 0)
      : num(mem.prevTargetR, 0);
    const prevWheel = side === 0
      ? num(mem.prevWheelL, actual)
      : num(mem.prevWheelR, actual);
    const prevSlope = num(mem.prevSlope, 0);

    if (Math.abs(prevTarget) > 0.45 &&
        Math.abs(actual) > 0.22 &&
        Math.abs(actual - prevWheel) < 0.16 &&
        Math.abs(prevOut) > 0.16 && Math.abs(prevOut) < 0.94 &&
        prevOut * prevTarget > 0) {
      const eff = prevOut - prevSlope;
      if (Math.abs(eff) > 0.14) {
        const estimate = clamp(Math.abs(actual / eff), 0.65, 4.0);
        gain = clamp(0.98 * gain + 0.02 * estimate, 0.65, 4.0);
        if (side === 0) mem.gL = gain;
        else mem.gR = gain;
      }
    }

    let minCmd = side === 0
      ? num(mem.minCmdL, 0.09)
      : num(mem.minCmdR, 0.09);
    let stall = side === 0
      ? num(mem.stallL, 0)
      : num(mem.stallR, 0);

    if (Math.abs(target) > 0.28 && Math.abs(actual) < 0.08 &&
        Math.abs(prevOut) > 0.09 && prevOut * target > 0) {
      stall += dt;
      if (stall > 0.7) {
        minCmd = Math.min(0.34, minCmd + 0.025);
        stall = 0;
      }
    } else if (Math.abs(actual) > 0.12) {
      stall = Math.max(0, stall - dt * 0.6);
      minCmd = Math.max(0.08, minCmd - dt * 0.001);
    } else {
      stall = Math.max(0, stall - dt * 0.2);
    }

    let u = target / Math.max(0.65, gain) +
      0.34 * (target - actual) + slopeComp;
    if (Math.abs(target) > 0.13 && target * u > 0 &&
        Math.abs(u) < minCmd &&
        Math.abs(actual) < Math.abs(target) * 0.8) {
      u = Math.sign(target) * minCmd;
    }

    if (side === 0) {
      mem.minCmdL = minCmd;
      mem.stallL = stall;
    } else {
      mem.minCmdR = minCmd;
      mem.stallR = stall;
    }
    return clamp(u, -1, 1);
  }

  function drive(v, omega, drill) {
    v = clamp(v, -1.0, 1.0);
    omega = clamp(omega, -2.0, 2.0);
    const pitch = num(obs.pitch, 0);
    const slopeComp = clamp(Math.sin(pitch * rad) * 0.16, -0.19, 0.19);
    const targetL = clamp(v - omega * 0.3, -1.8, 1.8);
    const targetR = clamp(v + omega * 0.3, -1.8, 1.8);
    const left = motorCommand(targetL, wl, 0, slopeComp);
    const right = motorCommand(targetR, wr, 1, slopeComp);

    mem.prevOutL = left;
    mem.prevOutR = right;
    mem.prevTargetL = targetL;
    mem.prevTargetR = targetR;
    mem.prevWheelL = wl;
    mem.prevWheelR = wr;
    mem.prevSlope = slopeComp;
    mem.drillIssued = !!drill;
    if (drill) mem.drillAt = now;
    return { left: left, right: right, drill: !!drill };
  }

  function recoveryCommand() {
    if (now >= num(mem.recoverUntil, -1000)) return null;
    const age = now - num(mem.recoverStart, now);
    const side = num(mem.recoverSide, 1);
    if (age < 0.48) return drive(-0.32, side * 0.42, false);
    return drive(0, side * 0.9, false);
  }

  function chooseSteering(goalRel) {
    const rayAngles = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
    const points = [];
    let validCount = 0;
    for (let i = 0; i < 9; i++) {
      if (i >= rays.length || mem.rayBad[i]) continue;
      const rv = Number(rays[i]);
      if (!Number.isFinite(rv)) continue;
      validCount++;
      if (rv > 0.05 && rv < 14.8) {
        points.push({ r: rv, a: rayAngles[i] });
      }
    }

    const candidates = [];
    for (let a = -80; a <= 80; a += 10) candidates.push(a);
    candidates.push(clamp(goalRel, -80, 80));

    let bestA = clamp(goalRel, -80, 80);
    let bestCost = Infinity;
    let bestRisk = Infinity;
    let bestClear = Infinity;

    for (let ci = 0; ci < candidates.length; ci++) {
      const a = candidates[ci];
      const delta = Math.abs(wrap(a - goalRel));
      let risk = 0;
      let minClear = Infinity;

      for (let j = 0; j < points.length; j++) {
        const p = points[j];
        const da = (p.a - a) * rad;
        const along = p.r * Math.cos(da);
        if (along <= 0.1 || along > 8) continue;
        const lateral = Math.abs(p.r * Math.sin(da));
        const corridor = 0.92 + 0.035 * along;

        if (lateral < corridor) {
          const penetration = (corridor - lateral) / corridor;
          risk += penetration * (3.0 + 5.0 / (along + 0.4));
          if (along < 1.3) risk += 9;
          minClear = Math.min(minClear, along - corridor);
        } else if (lateral < corridor + 0.45 && along < 4.5) {
          risk += (corridor + 0.45 - lateral) * 0.38;
          minClear = Math.min(minClear, along - corridor);
        }
      }

      let cost = 0.0022 * delta * delta + 0.00045 * a * a + risk;
      const wx = mem.px + 6 * Math.cos((mem.hEst + a) * rad);
      const wy = mem.py + 6 * Math.sin((mem.hEst + a) * rad);
      if (wx < 2 || wx > mem.mapSize - 2 ||
          wy < 2 || wy > mem.mapSize - 2) {
        cost += 80;
      } else {
        const edge = Math.min(wx, wy, mem.mapSize - wx, mem.mapSize - wy);
        if (edge < 5) cost += (5 - edge) * 1.2;
      }

      if (cost < bestCost) {
        bestCost = cost;
        bestA = a;
        bestRisk = risk;
        bestClear = minClear;
      }
    }

    let clearV = 0.82;
    if (Number.isFinite(bestClear)) {
      if (bestClear < 0.4) clearV = 0.16;
      else clearV = Math.min(clearV,
        Math.sqrt(0.85 * Math.max(0, bestClear - 0.25)));
    }
    if (validCount < 4) clearV = Math.min(clearV, 0.55);
    if (bestRisk > 16) clearV = Math.min(clearV, 0.15);
    else if (bestRisk > 10) clearV = Math.min(clearV, 0.28);

    return { a: bestA, risk: bestRisk, clearV: clearV };
  }

  function navigateRel(goalRel, d, vmax, stopR) {
    const recovery = recoveryCommand();
    if (recovery) return recovery;

    d = Math.max(0, num(d, 0));
    stopR = Math.max(0, num(stopR, 1));
    if (d <= stopR) {
      mem.navTrack = false;
      return drive(0, 0, false);
    }

    const gr = wrap(goalRel);
    if (Math.abs(gr) > 68) {
      const turn = clamp(1.5 * gr * rad, -1.05, 1.05);
      return drive(0, turn, false);
    }

    const choice = chooseSteering(gr);
    const alpha = choice.a;
    const absA = Math.abs(alpha);
    const avail = Math.max(0, d - stopR);
    let v = Math.min(vmax, 0.78, Math.sqrt(1.15 * avail),
      choice.clearV);
    if (absA > 20) v *= Math.max(0.35, Math.cos(absA * rad));
    if (absA > 45) v = Math.min(v, 0.38);
    if (choice.risk > 16) v = Math.min(v, 0.14);

    const omega = clamp(1.35 * alpha * rad, -1.05, 1.05);
    return drive(v, omega, false);
  }

  function navigatePoint(tx, ty, vmax, stopR) {
    tx = clamp(tx, 2, mem.mapSize - 2);
    ty = clamp(ty, 2, mem.mapSize - 2);
    const dx = tx - mem.px;
    const dy = ty - mem.py;
    const d = Math.hypot(dx, dy);
    const bearing = d > 0.001 ? Math.atan2(dy, dx) / rad : mem.hEst;

    if (d > stopR + 3) {
      if (!mem.navTrack ||
          dist(tx, ty, num(mem.navGoalX, tx), num(mem.navGoalY, ty)) > 3) {
        mem.navTrack = true;
        mem.navGoalX = tx;
        mem.navGoalY = ty;
        mem.navBestD = d;
        mem.navLastProgress = now;
        mem.navStartOdo = num(mem.odo, 0);
      } else {
        if (d < num(mem.navBestD, d) - 0.65) {
          mem.navBestD = d;
          mem.navLastProgress = now;
        }
        if (now - num(mem.navLastProgress, now) > 24 &&
            now > num(mem.recoverCooldown, 0)) {
          startRecovery(clearanceSide());
          return recoveryCommand();
        }
      }
    } else {
      mem.navTrack = false;
    }

    return navigateRel(wrap(bearing - mem.hEst), d, vmax, stopR);
  }

  function baseAction() {
    mem.returning = true;
    if (obs.beacon &&
        Number.isFinite(Number(obs.beacon.distance))) {
      const d = Math.max(0, Number(obs.beacon.distance));
      const b = num(obs.beacon.bearing, 0);
      return navigateRel(b, d, 0.78, 1.05);
    }
    const dx = mem.baseX - mem.px;
    const dy = mem.baseY - mem.py;
    const d = Math.hypot(dx, dy);
    const bearing = d > 0.001
      ? Math.atan2(dy, dx) / rad
      : mem.hEst;
    return navigatePoint(mem.baseX, mem.baseY, 0.78, 1.05);
  }

  function holdAtBase(baseMetric) {
    if (!obs.docked && baseMetric > 1.15) return baseAction();
    return drive(0, 0, false);
  }

  function returnEnergy(d, load) {
    const n = Math.max(0, load);
    return 0.10 + Math.max(0, d) * mem.ePerM *
      2.0 * (1 + 0.14 * n) + 0.02 * n;
  }

  function returnSeconds(d, load) {
    return Math.max(0, d) * 1.9 + 36 + 6 * Math.max(0, load);
  }

  function hintBudget(h) {
    return clamp(88 + 10 * Math.sqrt(Math.max(0.1, h.v)), 95, 135);
  }

  function planHint(i, fromX, fromY, load) {
    const h = mem.hints[i];
    if (!h) return { need: Infinity, time: Infinity, total: Infinity };
    const dNow = dist(fromX, fromY, h.x, h.y);
    const dBack = dist(h.x, h.y, mem.baseX, mem.baseY);
    let remaining = hintBudget(h);
    if (mem.search && mem.search.hint === i) {
      remaining = Math.max(0,
        num(mem.search.budget, remaining) -
        num(mem.search.spent, 0));
    }
    const total = dNow + dBack + remaining + 12;
    const n = Math.max(0, load);
    const need = 0.09 + total * mem.ePerM * 1.65 *
      (1 + 0.13 * n) + 0.025 * (n + 1);
    const time = total * 1.85 + 55 + 12 * n;
    return { need: need, time: time, total: total,
      dNow: dNow, dBack: dBack };
  }

  function pickHint(atHome) {
    if (carried >= mem.capacity) return -1;
    let best = -1;
    let bestScore = -Infinity;

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.s !== 0) continue;
      const p = planHint(i, mem.px, mem.py, carried);
      if (p.time > timeLeft - 14) continue;
      if (atHome) {
        if (p.need > 1.04) continue;
      } else if (p.need > battery - 0.045) {
        continue;
      }

      let cluster = 0;
      for (let j = 0; j < mem.hints.length; j++) {
        if (j === i) continue;
        const q = mem.hints[j];
        if (!q || q.s !== 0) continue;
        const dd = dist(h.x, h.y, q.x, q.y);
        if (dd < 38) cluster += q.v * (1 - dd / 38);
      }
      const effective = h.v + Math.min(h.v, cluster * 0.12);
      const denom = 42 + p.dNow + 0.72 * p.dBack +
        0.45 * Math.max(0, p.total - p.dNow - p.dBack);
      const score = effective / Math.pow(Math.max(1, denom), 0.88);
      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }
    return best;
  }

  function beginSearch(cx, cy, budget, hintIndex) {
    return {
      cx: cx,
      cy: cy,
      hint: hintIndex,
      index: 1,
      start: now,
      budget: budget,
      spent: 0,
      lastOdo: num(mem.odo, 0),
      lastCall: NaN,
      guideActive: false,
      guideX: 0,
      guideY: 0,
      guideStart: 0,
      guideCount: 0,
      guideCooldown: now + 7,
      extended: false
    };
  }

  function fitGradient(s) {
    const pts = [];
    const since = num(s.start, now) - 22;
    for (let i = 0; i < mem.sigPts.length; i++) {
      const p = mem.sigPts[i];
      if (p.t < since || now - p.t > 100) continue;
      if (dist(p.x, p.y, s.cx, s.cy) > 42) continue;
      pts.push(p);
    }
    if (pts.length < 6) return null;

    let mx = 0, my = 0, ms = 0;
    for (let i = 0; i < pts.length; i++) {
      mx += pts[i].x;
      my += pts[i].y;
      ms += pts[i].s;
    }
    mx /= pts.length;
    my /= pts.length;
    ms /= pts.length;

    let cxx = 0, cyy = 0, cxy = 0, cxs = 0, cys = 0, sst = 0;
    for (let i = 0; i < pts.length; i++) {
      const dx = pts[i].x - mx;
      const dy = pts[i].y - my;
      const ds = pts[i].s - ms;
      cxx += dx * dx;
      cyy += dy * dy;
      cxy += dx * dy;
      cxs += dx * ds;
      cys += dy * ds;
      sst += ds * ds;
    }
    const spread = cxx + cyy;
    if (spread < 16 || sst < 1e-8) return null;

    const lam = Math.max(0.25, spread * 0.025);
    const den = (cxx + lam) * (cyy + lam) - cxy * cxy;
    if (den <= 1e-9) return null;
    const gx = (cxs * (cyy + lam) - cys * cxy) / den;
    const gy = (cys * (cxx + lam) - cxs * cxy) / den;
    const mag = Math.hypot(gx, gy);
    const explained = (gx * cxs + gy * cys) / sst;
    if (!Number.isFinite(mag) || mag < 0.00008 ||
        explained < 0.08) return null;
    return { x: gx, y: gy, mag: mag };
  }

  function searchDirective(s) {
    if (Number.isFinite(s.lastCall) && now - s.lastCall < 0.5) {
      s.spent = num(s.spent, 0) +
        Math.max(0, num(mem.odo, 0) - num(s.lastOdo, mem.odo));
    }
    s.lastOdo = num(mem.odo, 0);
    s.lastCall = now;

    if (science > 0.004 && !s.extended) {
      s.budget = Math.min(170, num(s.budget, 90) + 35);
      s.extended = true;
    }
    if (s.spent > s.budget || now - s.start > 700 ||
        s.index >= mem.spiral.length) {
      return { failed: true };
    }

    if (s.guideActive) {
      if (dist(mem.px, mem.py, s.guideX, s.guideY) < 2.5 ||
          now - s.guideStart > 22) {
        s.guideActive = false;
        s.guideCooldown = now + 8;
      } else {
        return {
          failed: false,
          x: s.guideX,
          y: s.guideY,
          vmax: 0.72,
          stop: 2.0
        };
      }
    }

    while (s.index < mem.spiral.length) {
      const p = mem.spiral[s.index];
      const tx = clamp(s.cx + p[0], 2, mem.mapSize - 2);
      const ty = clamp(s.cy + p[1], 2, mem.mapSize - 2);
      if (dist(mem.px, mem.py, tx, ty) < 2.6) s.index++;
      else break;
    }
    if (s.index >= mem.spiral.length) return { failed: true };

    if (s.guideCount < 4 && now >= num(s.guideCooldown, 0) &&
        science > 0.004) {
      const g = fitGradient(s);
      if (g) {
        const tx = clamp(mem.px + 8 * g.x / g.mag, 2, mem.mapSize - 2);
        const ty = clamp(mem.py + 8 * g.y / g.mag, 2, mem.mapSize - 2);
        if (dist(tx, ty, s.cx, s.cy) < 31 &&
            dist(tx, ty, mem.px, mem.py) > 3.5) {
          s.guideActive = true;
          s.guideX = tx;
          s.guideY = ty;
          s.guideStart = now;
          s.guideCount++;
          return {
            failed: false,
            x: tx,
            y: ty,
            vmax: 0.72,
            stop: 2.0
          };
        }
      }
    }

    const p = mem.spiral[s.index];
    return {
      failed: false,
      x: clamp(s.cx + p[0], 2, mem.mapSize - 2),
      y: clamp(s.cy + p[1], 2, mem.mapSize - 2),
      vmax: 0.76,
      stop: 2.1
    };
  }

  function clearActiveHint() {
    mem.activeHint = -1;
    mem.search = null;
    mem.energyWaitStart = -1;
    mem.energyWaitKey = "";
  }

  function hintAction(atHome, baseMetric) {
    for (let attempt = 0; attempt < 5; attempt++) {
      let i = Math.floor(num(mem.activeHint, -1));
      if (i < 0 || !mem.hints[i] || mem.hints[i].s !== 0) {
        i = pickHint(atHome);
        if (i < 0) return null;
        mem.activeHint = i;
        mem.search = null;
      }

      const h = mem.hints[i];
      if (!h || h.s !== 0) {
        clearActiveHint();
        continue;
      }

      const p = planHint(i, mem.px, mem.py, carried);
      if (p.time > timeLeft - 12) {
        h.s = 3;
        clearActiveHint();
        continue;
      }
      if (atHome && p.need > 1.04) {
        h.s = 3;
        clearActiveHint();
        continue;
      }
      if (!atHome && p.need > battery - 0.04) {
        return null;
      }

      if (atHome && battery < p.need + 0.015) {
        if (mem.energyWaitKey !== "h" + i) {
          mem.energyWaitKey = "h" + i;
          mem.energyWaitStart = now;
        }
        const waited = now - num(mem.energyWaitStart, now);
        if (waited < 45 || battery >= p.need - 0.08) {
          return holdAtBase(baseMetric);
        }
        h.s = 3;
        clearActiveHint();
        continue;
      }
      mem.energyWaitStart = -1;
      mem.energyWaitKey = "";

      const d = dist(mem.px, mem.py, h.x, h.y);
      if (d > 8) {
        return navigatePoint(h.x, h.y, 0.78, 7.4);
      }

      if (!mem.search || mem.search.hint !== i ||
          dist(mem.search.cx, mem.search.cy, h.x, h.y) > 1) {
        mem.search = beginSearch(h.x, h.y, hintBudget(h), i);
      }

      const q = searchDirective(mem.search);
      if (q.failed) {
        h.s = 3;
        clearActiveHint();
        continue;
      }
      return navigatePoint(q.x, q.y, q.vmax, q.stop);
    }
    return null;
  }

  const freeOffsets = [
    [0, 0], [36, 0], [36, 36], [0, 36], [-36, 36],
    [-36, 0], [-36, -36], [0, -36], [36, -36], [72, 0]
  ];

  function freeAction(atHome, baseMetric) {
    if (!mem.freeSearch) {
      const k = Math.floor(num(mem.freeIndex, 0));
      if (k >= freeOffsets.length) return null;
      const off = freeOffsets[k];
      const cx = clamp(mem.baseX + off[0], 3, mem.mapSize - 3);
      const cy = clamp(mem.baseY + off[1], 3, mem.mapSize - 3);
      const budget = science > 0.004 ? 100 : 75;
      mem.freeSearch = beginSearch(cx, cy, budget, -1);
      mem.freeWaitStart = -1;
    }

    const s = mem.freeSearch;
    const remaining = Math.max(0, s.budget - s.spent);
    const dNow = dist(mem.px, mem.py, s.cx, s.cy);
    const dBack = dist(s.cx, s.cy, mem.baseX, mem.baseY);
    const total = dNow + dBack + remaining + 10;
    const need = 0.09 + total * mem.ePerM * 1.65 *
      (1 + 0.13 * carried) + 0.025 * (carried + 1);
    const timeNeed = total * 1.85 + 42 + 12 * carried;

    if (timeNeed > timeLeft - 12 || (atHome && need > 1.04)) {
      mem.freeSearch = null;
      mem.freeIndex++;
      return null;
    }
    if (!atHome && need > battery - 0.04) return null;

    if (atHome && battery < need + 0.015) {
      if (mem.freeWaitStart < 0) mem.freeWaitStart = now;
      const waited = now - mem.freeWaitStart;
      if (waited < 45 || battery >= need - 0.08) {
        return holdAtBase(baseMetric);
      }
      mem.freeSearch = null;
      mem.freeIndex++;
      mem.freeWaitStart = -1;
      return null;
    }
    mem.freeWaitStart = -1;

    if (dNow > 8) return navigatePoint(s.cx, s.cy, 0.78, 7.4);

    const q = searchDirective(s);
    if (q.failed) {
      mem.freeSearch = null;
      mem.freeIndex++;
      return null;
    }
    return navigatePoint(q.x, q.y, q.vmax, q.stop);
  }

  function siteAction() {
    let d = 0;
    let rel = 0;
    let haveSite = false;

    if (siteObj) {
      d = Math.max(0, num(siteObj.distance, 99));
      rel = num(siteObj.bearing, 0);
      haveSite = true;
    } else if (mem.siteValid && now - num(mem.siteLast, -100) < 2.5 &&
        Number.isFinite(mem.siteX) && Number.isFinite(mem.siteY)) {
      const dx = mem.siteX - mem.px;
      const dy = mem.siteY - mem.py;
      d = Math.hypot(dx, dy);
      const bearing = d > 0.001 ? Math.atan2(dy, dx) / rad : mem.hEst;
      rel = wrap(bearing - mem.hEst);
      haveSite = true;
    }

    if (!haveSite) {
      mem.siteValid = false;
      return null;
    }

    const value = Math.max(0.1,
      num(siteObj ? siteObj.value : mem.siteValue, 1));
    const homeD = obs.beacon &&
      Number.isFinite(Number(obs.beacon.distance))
      ? Math.max(0, Number(obs.beacon.distance))
      : dist(mem.px, mem.py, mem.baseX, mem.baseY);

    if (!inProgress) {
      if (carried >= mem.capacity ||
          battery < returnEnergy(homeD, carried + 1) +
            6 * mem.eDrill + 0.075 ||
          timeLeft < returnSeconds(homeD, carried + 1) + 22) {
        mem.returning = true;
        mem.siteValid = false;
        return baseAction();
      }
    }

    if (d <= 1.08) {
      const still = Math.abs(vActual) < 0.13 &&
        Math.max(Math.abs(wl), Math.abs(wr)) < 0.20;
      if (!still) return drive(0, 0, false);

      if (!mem.drillIssued && drillProgress <= 0.01) {
        if (siteObj) {
          const a = (mem.hEst + rel) * rad;
          mem.drillX = mem.px + d * Math.cos(a);
          mem.drillY = mem.py + d * Math.sin(a);
        } else {
          mem.drillX = mem.siteX;
          mem.drillY = mem.siteY;
        }
        mem.drillValue = value;
        mem.drillHint = mem.activeHint;
      }
      return drive(0, 0, true);
    }

    if (siteObj) return navigateRel(rel, d, 0.72, 0.94);
    return navigatePoint(mem.siteX, mem.siteY, 0.70, 0.95);
  }

  const baseDgps = dist(mem.px, mem.py, mem.baseX, mem.baseY);
  const baseMetric = obs.beacon &&
    Number.isFinite(Number(obs.beacon.distance))
    ? Math.max(0, Number(obs.beacon.distance))
    : baseDgps;
  const baseClose = !!obs.docked || baseMetric <= 2.8;
  const homeD = baseMetric;

  if (inProgress) return drive(0, 0, true);

  if (mem.returning && baseClose) {
    if (carried > 0) {
      if (baseMetric > 1.35 && !obs.docked) return baseAction();
      return drive(0, 0, false);
    }
    mem.returning = false;
    mem.energyWaitStart = -1;
    mem.energyWaitKey = "";
  }

  if (carried > 0 && baseClose) {
    mem.returning = true;
    if (baseMetric > 1.35 && !obs.docked) return baseAction();
    return drive(0, 0, false);
  }

  const urgentReturn = !baseClose &&
    (carried >= mem.capacity ||
      carried >= 2 ||
      battery < returnEnergy(homeD, carried) + 0.055 ||
      timeLeft < returnSeconds(homeD, carried) + 18);

  if (urgentReturn) {
    mem.returning = true;
    return baseAction();
  }
  if (mem.returning) return baseAction();

  const sampledSiteAction = siteAction();
  if (sampledSiteAction) return sampledSiteAction;
  if (mem.returning) return baseAction();

  const hintOut = hintAction(baseClose, baseMetric);
  if (hintOut) return hintOut;

  const freeOut = freeAction(baseClose, baseMetric);
  if (freeOut) return freeOut;

  if (!baseClose) {
    mem.returning = true;
    return baseAction();
  }

  return holdAtBase(baseMetric);
}

function act(obs, mem) {
  if (!mem || typeof mem !== "object") mem = {};

  const rad = Math.PI / 180;
  const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
  const num = (v, d) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : d;
  };
  const wrap = (a) => {
    a %= 360;
    if (a > 180) a -= 360;
    if (a < -180) a += 360;
    return a;
  };
  const dist = (x1, y1, x2, y2) => Math.hypot(x1 - x2, y1 - y2);

  function buildSpiral(step, maxR) {
    const pts = [[0, 0]];
    let x = 0, y = 0, dir = 0, len = 1, stopped = false;
    for (let k = 0; k < 100 && !stopped; k++) {
      for (let rep = 0; rep < 2 && !stopped; rep++) {
        for (let j = 0; j < len; j++) {
          if (dir === 0) x += step;
          else if (dir === 1) y += step;
          else if (dir === 2) x -= step;
          else y -= step;
          if (Math.hypot(x, y) > maxR) {
            stopped = true;
            break;
          }
          pts.push([x, y]);
        }
        dir = (dir + 1) % 4;
      }
      len++;
    }
    return pts;
  }

  const mission = obs && obs.mission ? obs.mission : {};
  if (!mem._init) {
    const b = mission.base || {};
    mem.baseX = num(b.x, num(obs && obs.x, 200));
    mem.baseY = num(b.y, num(obs && obs.y, 200));
    mem.mapSize = Math.max(40, num(mission.size, 400));
    mem.totalSeconds = Math.max(1, num(mission.seconds, 1200));
    mem.capacity = Math.max(1, Math.floor(num(mission.capacity, 5)));

    mem.hints = [];
    const hs = Array.isArray(mission.hints) ? mission.hints : [];
    for (let i = 0; i < hs.length; i++) {
      const h = hs[i] || {};
      const x = Number(h.x), y = Number(h.y);
      if (Number.isFinite(x) && Number.isFinite(y)) {
        mem.hints.push({
          x: clamp(x, 2, mem.mapSize - 2),
          y: clamp(y, 2, mem.mapSize - 2),
          v: Math.max(0.1, num(h.estimate, 1)),
          status: 0
        });
      }
    }

    mem.spiral = buildSpiral(6.5, 30);
    mem.activeHint = -1;
    mem.search = null;
    mem.freeSearch = null;
    mem.freeIndex = 0;
    mem.freeWaitStart = -1;
    mem.chargeWaitStart = -1;
    mem.chargeWaitKey = "";
    mem.returning = false;

    mem.siteValid = false;
    mem.siteX = NaN;
    mem.siteY = NaN;
    mem.siteValue = 0;
    mem.siteLast = -100;
    mem.drillActive = false;
    mem.drillStart = -100;
    mem.drillX = NaN;
    mem.drillY = NaN;
    mem.drillValue = 0;
    mem.drillHint = -1;
    mem.lastCarried = NaN;

    mem.ePerM = 0.0008;
    mem.eDrill = 0.003;
    mem.energyReady = false;
    mem.energyDist = 0;
    mem.energyDraw = 0;
    mem.drillEnergy = 0;
    mem.drillSeconds = 0;

    mem.poseReady = false;
    mem.hEst = 0;
    mem.px = num(obs && obs.x, mem.baseX);
    mem.py = num(obs && obs.y, mem.baseY);
    mem.odo = 0;
    mem.gpsFrozen = false;
    mem.gpsRepeat = 0;
    mem.gpsStillOdo = 0;
    mem.calX = NaN;
    mem.calY = NaN;

    mem.gL = 2.1;
    mem.gR = 2.1;
    mem.iL = 0;
    mem.iR = 0;
    mem.prevOutL = 0;
    mem.prevOutR = 0;
    mem.prevTargetL = 0;
    mem.prevTargetR = 0;
    mem.prevWheelL = 0;
    mem.prevWheelR = 0;
    mem.prevSlope = 0;
    mem.prevDrillCommand = false;

    mem.rayPrev = new Array(9);
    mem.rayBad = new Array(9).fill(false);
    mem.rayOdo = new Array(9).fill(0);
    mem.rayTime = new Array(9).fill(0);
    mem.rayHead = new Array(9).fill(0);

    mem.sigPts = [];
    mem.bumpPrev = false;
    mem.recoverStart = -1000;
    mem.recoverUntil = -1000;
    mem.recoverSide = 1;
    mem.recoverCooldown = 0;
    mem.navGoalX = NaN;
    mem.navGoalY = NaN;
    mem.navLastProgress = 0;
    mem.navBestD = Infinity;
    mem.navLastX = NaN;
    mem.navLastY = NaN;
    mem.prevNow = NaN;
    mem._init = true;
  }

  if (!Array.isArray(mem.hints)) mem.hints = [];
  if (!Array.isArray(mem.spiral) || mem.spiral.length < 2) {
    mem.spiral = buildSpiral(6.5, 30);
  }
  if (!Array.isArray(mem.sigPts)) mem.sigPts = [];
  if (!Array.isArray(mem.rayPrev)) mem.rayPrev = new Array(9);
  if (!Array.isArray(mem.rayBad)) mem.rayBad = new Array(9).fill(false);
  if (!Array.isArray(mem.rayOdo)) mem.rayOdo = new Array(9).fill(0);
  if (!Array.isArray(mem.rayTime)) mem.rayTime = new Array(9).fill(0);
  if (!Array.isArray(mem.rayHead)) mem.rayHead = new Array(9).fill(0);
  if (!Number.isFinite(mem.ePerM)) mem.ePerM = 0.0008;
  if (!Number.isFinite(mem.activeHint)) mem.activeHint = -1;

  const hasTimeLeft = obs && obs.timeLeft !== undefined &&
    obs.timeLeft !== null && Number.isFinite(Number(obs.timeLeft));
  const now = obs && Number.isFinite(Number(obs.t))
    ? Math.max(0, Number(obs.t))
    : Math.max(0, mem.totalSeconds - num(obs && obs.timeLeft, mem.totalSeconds));
  let dt = 0.1;
  if (Number.isFinite(mem.prevNow)) {
    const deltaT = now - mem.prevNow;
    if (deltaT > 0.015 && deltaT < 0.8) dt = deltaT;
  }
  dt = clamp(dt, 0.03, 0.3);
  mem.prevNow = now;
  const timeLeft = hasTimeLeft
    ? Math.max(0, Number(obs.timeLeft))
    : Math.max(0, mem.totalSeconds - now);

  const rawH = wrap(num(obs.heading, 0));
  const wl = num(obs.wheelLeft, 0);
  const wr = num(obs.wheelRight, 0);
  const vActual = clamp((wl + wr) * 0.5, -3.2, 3.2);
  const yawActual = clamp((wr - wl) / 0.6, -10, 10);
  const gpsValid = Number.isFinite(Number(obs.x)) &&
    Number.isFinite(Number(obs.y));
  const gx = gpsValid ? Number(obs.x) : NaN;
  const gy = gpsValid ? Number(obs.y) : NaN;

  if (!mem.poseReady) {
    mem.px = gpsValid ? gx : mem.baseX;
    mem.py = gpsValid ? gy : mem.baseY;
    mem.hEst = rawH;
    mem.prevRawH = rawH;
    mem.gpsPrevX = gpsValid ? gx : NaN;
    mem.gpsPrevY = gpsValid ? gy : NaN;
    mem.gpsFrozen = false;
    mem.gpsRepeat = 0;
    mem.gpsStillOdo = 0;
    mem.odo = 0;
    mem.poseReady = true;
  } else {
    const oldX = num(mem.px, mem.baseX);
    const oldY = num(mem.py, mem.baseY);
    const oldH = num(mem.hEst, rawH);
    const yawDeg = yawActual * dt / rad;
    const predH = wrap(oldH + yawDeg);
    const rawDelta = wrap(rawH - num(mem.prevRawH, rawH));
    const compassErr = wrap(rawH - predH);

    // Wheel yaw bridges sudden compass jumps; ordinary compass readings
    // slowly correct accumulated wheel-heading error.
    if (Math.abs(compassErr) < 55 &&
        Math.abs(wrap(rawDelta - yawDeg)) < 48) {
      const k = Math.abs(yawActual) > 0.5 ? 0.28 : 0.20;
      mem.hEst = wrap(predH + k * compassErr);
    } else {
      mem.hEst = predH;
    }

    const step = clamp(vActual * dt, -0.6, 0.6);
    const midH = wrap(oldH + yawDeg * 0.5) * rad;
    let px = oldX + step * Math.cos(midH);
    let py = oldY + step * Math.sin(midH);
    mem.odo = num(mem.odo, 0) + Math.abs(step);

    let rawGpsStep = Infinity;
    if (gpsValid && Number.isFinite(mem.gpsPrevX) &&
        Number.isFinite(mem.gpsPrevY)) {
      rawGpsStep = dist(gx, gy, mem.gpsPrevX, mem.gpsPrevY);
      if (rawGpsStep < 0.025 && Math.abs(vActual) > 0.22) {
        mem.gpsRepeat = num(mem.gpsRepeat, 0) + 1;
        mem.gpsStillOdo = num(mem.gpsStillOdo, 0) + Math.abs(step);
        if (mem.gpsRepeat > 18 && mem.gpsStillOdo > 1.3) {
          mem.gpsFrozen = true;
        }
      } else if (rawGpsStep > 0.06) {
        mem.gpsRepeat = 0;
        mem.gpsStillOdo = 0;
        if (rawGpsStep > 0.12) mem.gpsFrozen = false;
      }
    }

    const wasFrozen = !!mem.gpsFrozen;
    const recovered = wasFrozen && rawGpsStep > 0.12;
    if (gpsValid && (!mem.gpsFrozen || recovered)) {
      const err = dist(gx, gy, px, py);
      const maxJump = Math.max(6, Math.abs(vActual) * dt * 12 + 2);
      if ((rawGpsStep <= maxJump || recovered ||
          !Number.isFinite(rawGpsStep)) && (err < 25 || recovered)) {
        let alpha = Math.abs(vActual) > 0.18 ? 0.42 : 0.22;
        if (err > 6) alpha = 0.55;
        if (recovered) alpha = 0.72;
        px += (gx - px) * alpha;
        py += (gy - py) * alpha;
      }
    }

    mem.px = px;
    mem.py = py;

    // A straight GPS track is a direct correction to compass bias and drift.
    if (gpsValid && !mem.gpsFrozen && vActual > 0.25 &&
        Math.abs(yawActual) < 0.18) {
      if (!Number.isFinite(mem.calX) || !Number.isFinite(mem.calY)) {
        mem.calX = gx;
        mem.calY = gy;
      } else if (dist(gx, gy, mem.calX, mem.calY) > 2.5) {
        const course = Math.atan2(gy - mem.calY, gx - mem.calX) / rad;
        const err = wrap(course - mem.hEst);
        mem.hEst = wrap(mem.hEst + clamp(err * 0.55, -35, 35));
        mem.calX = gx;
        mem.calY = gy;
      }
    } else {
      mem.calX = NaN;
      mem.calY = NaN;
    }

    if (gpsValid) {
      mem.gpsPrevX = gx;
      mem.gpsPrevY = gy;
    }
    mem.prevRawH = rawH;
  }

  const battery = Math.max(0, num(obs.battery, 0));
  const solar = Math.max(0, num(obs.solar, 0));
  const drillProgress = clamp(num(obs.drilling, 0), 0, 6);
  const dockedNow = !!obs.docked;

  if (!mem.energyReady) {
    mem.prevBattery = battery;
    mem.prevSolar = solar;
    mem.energyDist = 0;
    mem.energyDraw = 0;
    mem.drillEnergy = 0;
    mem.drillSeconds = 0;
    mem.energyReady = true;
  } else {
    const netDraw = num(mem.prevBattery, battery) - battery +
      0.5 * (num(mem.prevSolar, solar) + solar) * dt;
    const wasDrilling = drillProgress > 0.01 ||
      !!mem.prevDrillCommand;
    if (!dockedNow && !wasDrilling) {
      const equivDist = Math.max(0, Math.abs(vActual) +
        0.15 * Math.abs(yawActual)) * dt;
      if (equivDist > 0.015) {
        mem.energyDist = num(mem.energyDist, 0) + equivDist;
        mem.energyDraw = num(mem.energyDraw, 0) + Math.max(0, netDraw);
        if (mem.energyDist >= 10) {
          const measured = mem.energyDraw / Math.max(1, mem.energyDist);
          if (Number.isFinite(measured) && measured > 0.00008) {
            const target = clamp(measured * 1.35, 0.0005, 0.025);
            const alpha = target > mem.ePerM ? 0.30 : 0.10;
            mem.ePerM = clamp((1 - alpha) * mem.ePerM +
              alpha * target, 0.0005, 0.03);
          }
          mem.energyDist = 0;
          mem.energyDraw = 0;
        }
      }
    }

    if (!dockedNow && wasDrilling) {
      mem.drillSeconds = num(mem.drillSeconds, 0) + dt;
      mem.drillEnergy = num(mem.drillEnergy, 0) + Math.max(0, netDraw);
    } else if (num(mem.drillSeconds, 0) >= 3) {
      const measured = num(mem.drillEnergy, 0) /
        Math.max(1, num(mem.drillSeconds, 0));
      if (Number.isFinite(measured) && measured > 0.00002) {
        const target = clamp(measured * 1.25, 0.0002, 0.04);
        mem.eDrill = clamp(0.75 * mem.eDrill + 0.25 * target,
          0.0002, 0.05);
      }
      mem.drillSeconds = 0;
      mem.drillEnergy = 0;
    }
    mem.prevBattery = battery;
    mem.prevSolar = solar;
  }

  const science = Math.max(0, num(obs.science, 0));
  const lastSig = mem.sigPts.length
    ? mem.sigPts[mem.sigPts.length - 1]
    : null;
  if (!lastSig || dist(mem.px, mem.py, lastSig.x, lastSig.y) > 2.2 ||
      now - lastSig.t > 4) {
    const tag = mem.activeHint >= 0 ? mem.activeHint :
      (mem.freeSearch ? -2 : -9);
    mem.sigPts.push({ x: mem.px, y: mem.py, s: science, t: now, h: tag });
    if (mem.sigPts.length > 140) mem.sigPts.shift();
  }

  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  for (let i = 0; i < 9; i++) {
    if (i >= rays.length || !Number.isFinite(Number(rays[i]))) continue;
    const r = Number(rays[i]);
    if (!Number.isFinite(mem.rayPrev[i])) {
      mem.rayPrev[i] = r;
      mem.rayOdo[i] = mem.odo;
      mem.rayTime[i] = now;
      mem.rayHead[i] = mem.hEst;
    } else if (Math.abs(r - mem.rayPrev[i]) > 0.06) {
      mem.rayPrev[i] = r;
      mem.rayOdo[i] = mem.odo;
      mem.rayTime[i] = now;
      mem.rayHead[i] = mem.hEst;
      mem.rayBad[i] = false;
    } else if (r < 14.8 &&
        mem.odo - num(mem.rayOdo[i], mem.odo) > 8 &&
        now - num(mem.rayTime[i], now) > 10 &&
        Math.abs(wrap(mem.hEst - num(mem.rayHead[i], mem.hEst))) > 32) {
      mem.rayBad[i] = true;
    }
  }

  const carried = Math.max(0, Math.floor(num(obs.carried, 0)));

  function markSampled() {
    const sx = num(mem.drillX, num(mem.siteX, mem.px));
    const sy = num(mem.drillY, num(mem.siteY, mem.py));
    const hint = Math.floor(num(mem.drillHint, -1));
    if (hint >= 0 && mem.hints[hint]) mem.hints[hint].status = 1;

    let best = -1, bestD = 15;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status !== 0) continue;
      const d = dist(sx, sy, h.x, h.y);
      if (d < bestD) {
        bestD = d;
        best = i;
      }
    }
    if (best >= 0) mem.hints[best].status = 1;

    if (mem.activeHint >= 0 && mem.hints[mem.activeHint]) {
      mem.hints[mem.activeHint].status = 1;
    }
    mem.activeHint = -1;
    mem.search = null;
    mem.drillActive = false;
    mem.drillX = NaN;
    mem.drillY = NaN;
    mem.drillValue = 0;
    mem.drillHint = -1;
    mem.siteValid = false;

    if (mem.freeSearch) {
      mem.freeSearch.index = Math.max(1,
        Math.floor(num(mem.freeSearch.index, 0)) + 1);
      mem.freeSearch.lastOdo = mem.odo;
    }
  }

  let justSampled = false;
  if (!Number.isFinite(mem.lastCarried)) {
    mem.lastCarried = carried;
  } else if (carried > mem.lastCarried) {
    justSampled = true;
    markSampled();
  }
  mem.lastCarried = carried;

  if (drillProgress > 0.01) mem.drillActive = true;
  if (mem.drillActive && drillProgress <= 0.01 &&
      now - num(mem.drillStart, now) > 10 && !justSampled) {
    mem.drillActive = false;
  }
  const inProgress = !justSampled &&
    (drillProgress > 0.01 || !!mem.drillActive);

  function clearanceSide() {
    let left = 0, right = 0, nl = 0, nr = 0;
    for (let i = 0; i < 9; i++) {
      if (i >= rays.length || !Number.isFinite(Number(rays[i]))) continue;
      const r = Number(rays[i]);
      if (i > 4) {
        left += r;
        nl++;
      } else if (i < 4) {
        right += r;
        nr++;
      }
    }
    const l = left / Math.max(1, nl);
    const r = right / Math.max(1, nr);
    if (Math.abs(l - r) < 0.3) return -num(mem.recoverSide, 1);
    return l >= r ? 1 : -1;
  }

  function drive(v, omega, drill) {
    v = clamp(v, -1.15, 1.15);
    omega = clamp(omega, -2.2, 2.2);
    const pitch = num(obs.pitch, 0);
    const slope = clamp(Math.sin(pitch * rad) * 0.22, -0.22, 0.22);
    const targetL = clamp(v - omega * 0.3, -2.0, 2.0);
    const targetR = clamp(v + omega * 0.3, -2.0, 2.0);

    function motor(target, actual, side) {
      let gain = side === 0 ? num(mem.gL, 2.1) : num(mem.gR, 2.1);
      const prevOut = side === 0 ? num(mem.prevOutL, 0) :
        num(mem.prevOutR, 0);
      const prevTarget = side === 0 ? num(mem.prevTargetL, 0) :
        num(mem.prevTargetR, 0);
      const prevSlope = num(mem.prevSlope, 0);

      if (Math.abs(prevTarget) > 0.35 && Math.abs(actual) > 0.18 &&
          prevOut * prevTarget > 0 && Math.abs(prevOut) > 0.13 &&
          Math.abs(prevOut) < 0.95 && actual * prevTarget > 0) {
        const eff = prevOut - prevSlope;
        if (Math.abs(eff) > 0.12) {
          const est = clamp(Math.abs(actual / eff), 0.65, 4.0);
          gain = clamp(0.985 * gain + 0.015 * est, 0.65, 4.0);
          if (side === 0) mem.gL = gain;
          else mem.gR = gain;
        }
      }

      let integ = side === 0 ? num(mem.iL, 0) : num(mem.iR, 0);
      const err = target - actual;
      if (Math.abs(target) < 0.04) {
        integ *= 0.92;
        if (side === 0) mem.iL = integ;
        else mem.iR = integ;
        return clamp(-0.68 * actual + slope, -1, 1);
      }

      integ = clamp(integ + 0.10 * err * dt, -0.28, 0.28);
      let u = target / Math.max(0.65, gain) + 0.38 * err +
        integ + slope;
      if (Math.abs(target) > 0.10 && target * u > 0 &&
          Math.abs(u) < 0.115 && Math.abs(actual) < Math.abs(target) * 0.8) {
        u = Math.sign(target) * 0.115;
      }
      if (side === 0) mem.iL = integ;
      else mem.iR = integ;
      return clamp(u, -1, 1);
    }

    const left = motor(targetL, wl, 0);
    const right = motor(targetR, wr, 1);
    mem.prevOutL = left;
    mem.prevOutR = right;
    mem.prevTargetL = targetL;
    mem.prevTargetR = targetR;
    mem.prevWheelL = wl;
    mem.prevWheelR = wr;
    mem.prevSlope = slope;
    mem.prevDrillCommand = !!drill;
    return { left: left, right: right, drill: !!drill };
  }

  function startRecovery(side) {
    mem.recoverSide = side >= 0 ? 1 : -1;
    mem.recoverStart = now;
    mem.recoverUntil = now + 1.25;
    mem.recoverCooldown = now + 9;
    mem.navGoalX = NaN;
    mem.navGoalY = NaN;
  }

  function recoveryCommand() {
    if (now >= num(mem.recoverUntil, -1000)) return null;
    const age = now - num(mem.recoverStart, now);
    const side = num(mem.recoverSide, 1);
    if (age < 0.55) return drive(-0.32, side * 0.72, false);
    return drive(0, side * 0.98, false);
  }

  const bumped = !!obs.bumped;
  if (bumped && !mem.bumpPrev) startRecovery(clearanceSide());
  mem.bumpPrev = bumped;

  function chooseSteering(goalRel) {
    const angles = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
    const points = [];
    for (let i = 0; i < 9; i++) {
      if (i >= rays.length || mem.rayBad[i]) continue;
      const r = Number(rays[i]);
      if (Number.isFinite(r) && r > 0.05 && r < 14.8) {
        points.push({ r: r, a: angles[i] });
      }
    }

    const candidates = [];
    for (let a = -80; a <= 80; a += 10) candidates.push(a);
    candidates.push(clamp(goalRel, -80, 80));

    let bestA = clamp(goalRel, -80, 80);
    let bestCost = Infinity;
    let bestRisk = 0;
    let bestClear = Infinity;

    for (let ci = 0; ci < candidates.length; ci++) {
      const a = candidates[ci];
      let risk = 0;
      let clear = Infinity;

      for (let j = 0; j < points.length; j++) {
        const p = points[j];
        const da = (p.a - a) * rad;
        const along = p.r * Math.cos(da);
        if (along <= 0.15 || along > 7) continue;
        const lateral = Math.abs(p.r * Math.sin(da));
        const corridor = 0.78 + 0.045 * along;
        if (lateral < corridor) {
          const penetration = (corridor - lateral) / corridor;
          risk += penetration * (2.4 + 5 / (along + 0.35));
          if (along < 1.4) risk += 6;
          clear = Math.min(clear, along - corridor);
        } else if (lateral < corridor + 0.35 && along < 4) {
          risk += (corridor + 0.35 - lateral) * 0.35;
          clear = Math.min(clear, along - corridor);
        }
      }

      let cost = 0.032 * Math.abs(wrap(a - goalRel)) +
        0.00035 * a * a + risk;
      const wx = mem.px + 5 * Math.cos((mem.hEst + a) * rad);
      const wy = mem.py + 5 * Math.sin((mem.hEst + a) * rad);
      if (wx < 2 || wx > mem.mapSize - 2 ||
          wy < 2 || wy > mem.mapSize - 2) {
        cost += 30;
      } else {
        const edge = Math.min(wx, wy, mem.mapSize - wx, mem.mapSize - wy);
        if (edge < 5) cost += (5 - edge) * 1.3;
      }

      if (cost < bestCost) {
        bestCost = cost;
        bestA = a;
        bestRisk = risk;
        bestClear = clear;
      }
    }

    let safeV = 0.85;
    if (Number.isFinite(bestClear)) {
      if (bestClear < 0.15) safeV = 0.12;
      else safeV = Math.min(safeV,
        Math.sqrt(0.9 * Math.max(0, bestClear - 0.1)));
    }
    if (bestRisk > 12) safeV = Math.min(safeV, 0.14);
    else if (bestRisk > 8) safeV = Math.min(safeV, 0.28);
    return { a: bestA, risk: bestRisk, clearV: safeV };
  }

  function navigateRel(goalRel, d, vmax, stopR) {
    const recovery = recoveryCommand();
    if (recovery) return recovery;

    d = Math.max(0, num(d, 0));
    stopR = Math.max(0, num(stopR, 1));
    if (d <= stopR) return drive(0, 0, false);

    const gr = wrap(goalRel);
    if (Math.abs(gr) > 105) {
      return drive(0, clamp(1.8 * gr * rad, -1.35, 1.35), false);
    }

    const choice = chooseSteering(gr);
    const a = choice.a;
    const absA = Math.abs(a);
    const avail = Math.max(0, d - stopR);
    let v = Math.min(vmax, 0.82, Math.sqrt(0.9 * avail),
      choice.clearV);
    if (absA > 25) v *= Math.max(0.32, Math.cos(absA * rad));
    if (absA > 58) v = Math.min(v, 0.12);
    else if (absA > 43) v = Math.min(v, 0.30);
    if (choice.risk > 12) v = Math.min(v, 0.12);

    const omega = clamp(1.9 * a * rad, -1.35, 1.35);
    return drive(v, omega, false);
  }

  function navigatePoint(tx, ty, vmax, stopR) {
    tx = clamp(tx, 2, mem.mapSize - 2);
    ty = clamp(ty, 2, mem.mapSize - 2);
    const dx = tx - mem.px;
    const dy = ty - mem.py;
    const d = Math.hypot(dx, dy);
    const bearing = d > 0.001 ? Math.atan2(dy, dx) / rad : mem.hEst;

    if (d > stopR + 2) {
      const newGoal = !Number.isFinite(mem.navGoalX) ||
        !Number.isFinite(mem.navGoalY) ||
        dist(tx, ty, mem.navGoalX, mem.navGoalY) > 3;
      if (newGoal) {
        mem.navGoalX = tx;
        mem.navGoalY = ty;
        mem.navLastProgress = now;
        mem.navBestD = d;
        mem.navLastX = mem.px;
        mem.navLastY = mem.py;
      } else {
        const moved = dist(mem.px, mem.py,
          num(mem.navLastX, mem.px), num(mem.navLastY, mem.py));
        if (d < num(mem.navBestD, d) - 0.55 || moved > 2.0) {
          mem.navBestD = d;
          mem.navLastProgress = now;
          mem.navLastX = mem.px;
          mem.navLastY = mem.py;
        }
        if (now - num(mem.navLastProgress, now) > 24 &&
            now > num(mem.recoverCooldown, 0)) {
          startRecovery(clearanceSide());
          return recoveryCommand();
        }
      }
    } else {
      mem.navGoalX = NaN;
      mem.navGoalY = NaN;
    }

    return navigateRel(wrap(bearing - mem.hEst), d, vmax, stopR);
  }

  function pauseSearches() {
    if (mem.search) mem.search.lastOdo = mem.odo;
    if (mem.freeSearch) mem.freeSearch.lastOdo = mem.odo;
  }

  const beacon = obs.beacon &&
    Number.isFinite(Number(obs.beacon.distance))
    ? obs.beacon
    : null;
  const gpsBaseD = dist(mem.px, mem.py, mem.baseX, mem.baseY);
  const baseMetric = beacon
    ? Math.max(0, Number(beacon.distance))
    : gpsBaseD;

  function baseAction() {
    pauseSearches();
    mem.returning = true;
    if (beacon) {
      return navigateRel(num(beacon.bearing, 0),
        Math.max(0, Number(beacon.distance)), 0.72, 0.72);
    }
    return navigatePoint(mem.baseX, mem.baseY, 0.72, 0.72);
  }

  function holdAtBase() {
    pauseSearches();
    if (obs.docked) return drive(0, 0, false);
    if (baseMetric > 0.75) return baseAction();
    return drive(0, 0, false);
  }

  function returnEnergy(d, load) {
    const n = Math.max(0, load);
    return 0.085 + Math.max(0, d) * mem.ePerM *
      2.55 * (1 + 0.16 * n) + 0.016 * n;
  }

  function returnSeconds(d, load) {
    const n = Math.max(0, load);
    return Math.max(0, d) * 2.05 + 30 + 7 * n;
  }

  function hintBudget(h) {
    return clamp(100 + 8 * Math.sqrt(Math.max(0.1, h.v)), 105, 155);
  }

  function hintPlan(i) {
    const h = mem.hints[i];
    if (!h) return { need: Infinity, time: Infinity };
    const toHint = dist(mem.px, mem.py, h.x, h.y);
    const back = dist(h.x, h.y, mem.baseX, mem.baseY) + 18;
    let remaining = hintBudget(h);
    if (mem.search && mem.activeHint === i) {
      remaining = Math.max(0, num(mem.search.budget, remaining) -
        num(mem.search.spent, 0));
    }
    const total = toHint + back + remaining;
    const need = 0.10 + total * mem.ePerM * 1.65 *
      (1 + 0.14 * carried) + 0.025 * (carried + 1);
    const time = total * 1.95 + 50 + 7 * carried;
    return { need: need, time: time, total: total, toHint: toHint };
  }

  function pickHint() {
    let best = -1;
    let bestScore = -Infinity;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status !== 0) continue;
      const p = hintPlan(i);
      if (p.time > timeLeft - 12 || p.need > 1.04) continue;

      let cluster = 0;
      for (let j = 0; j < mem.hints.length; j++) {
        if (j === i) continue;
        const q = mem.hints[j];
        if (!q || q.status !== 0) continue;
        const dd = dist(h.x, h.y, q.x, q.y);
        if (dd < 34) cluster += q.v * (1 - dd / 34);
      }
      const value = h.v + Math.min(h.v * 0.8, cluster * 0.12);
      const dHome = dist(h.x, h.y, mem.baseX, mem.baseY);
      const score = value / Math.pow(
        Math.max(1, 35 + p.toHint + 0.62 * dHome +
          0.35 * hintBudget(h)), 0.9);
      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }
    return best;
  }

  function beginSearch(cx, cy, hint, budget) {
    return {
      cx: cx,
      cy: cy,
      hint: hint,
      index: 0,
      start: now,
      budget: budget,
      spent: 0,
      lastOdo: mem.odo,
      guideActive: false,
      guideX: 0,
      guideY: 0,
      guideStart: 0,
      guideCount: 0,
      guideCooldown: now + 9
    };
  }

  function fitGradient(s) {
    const pts = [];
    for (let i = 0; i < mem.sigPts.length; i++) {
      const p = mem.sigPts[i];
      if (p.h !== s.hint || now - p.t > 75 ||
          dist(p.x, p.y, s.cx, s.cy) > 38) continue;
      pts.push(p);
    }
    if (pts.length < 6) return null;

    let mx = 0, my = 0, ms = 0, smin = Infinity, smax = -Infinity;
    for (let i = 0; i < pts.length; i++) {
      mx += pts[i].x;
      my += pts[i].y;
      ms += pts[i].s;
      smin = Math.min(smin, pts[i].s);
      smax = Math.max(smax, pts[i].s);
    }
    mx /= pts.length;
    my /= pts.length;
    ms /= pts.length;
    if (smax - smin < Math.max(0.004, Math.abs(ms) * 0.05)) return null;

    let cxx = 0, cyy = 0, cxy = 0, cxs = 0, cys = 0, sst = 0;
    for (let i = 0; i < pts.length; i++) {
      const dx = pts[i].x - mx;
      const dy = pts[i].y - my;
      const ds = pts[i].s - ms;
      cxx += dx * dx;
      cyy += dy * dy;
      cxy += dx * dy;
      cxs += dx * ds;
      cys += dy * ds;
      sst += ds * ds;
    }
    const spread = cxx + cyy;
    if (spread < 14 || sst < 1e-8) return null;
    const lam = Math.max(0.25, spread * 0.025);
    const den = (cxx + lam) * (cyy + lam) - cxy * cxy;
    if (den <= 1e-9) return null;
    const gx = (cxs * (cyy + lam) - cys * cxy) / den;
    const gy = (cys * (cxx + lam) - cxs * cxy) / den;
    const mag = Math.hypot(gx, gy);
    const explained = (gx * cxs + gy * cys) / sst;
    if (!Number.isFinite(mag) || mag < 0.00008 || explained < 0.08) {
      return null;
    }
    return { x: gx, y: gy, mag: mag };
  }

  function searchDirective(s) {
    s.spent = num(s.spent, 0) +
      Math.max(0, num(mem.odo, 0) - num(s.lastOdo, mem.odo));
    s.lastOdo = num(mem.odo, 0);

    if (s.spent > s.budget || now - s.start > 650 ||
        s.index >= mem.spiral.length) {
      return { failed: true };
    }

    if (s.guideActive) {
      if (dist(mem.px, mem.py, s.guideX, s.guideY) < 2.8 ||
          now - s.guideStart > 25) {
        s.guideActive = false;
        s.guideCooldown = now + 10;
      } else {
        return { failed: false, x: s.guideX, y: s.guideY,
          vmax: 0.72, stop: 1.8 };
      }
    }

    while (s.index < mem.spiral.length) {
      const p = mem.spiral[s.index];
      const tx = s.cx + p[0];
      const ty = s.cy + p[1];
      if (tx < 2 || tx > mem.mapSize - 2 ||
          ty < 2 || ty > mem.mapSize - 2 ||
          dist(mem.px, mem.py, tx, ty) < 2.7) {
        s.index++;
      } else {
        break;
      }
    }
    if (s.index >= mem.spiral.length) return { failed: true };

    if (s.guideCount < 2 && now >= s.guideCooldown &&
        s.spent < s.budget * 0.8) {
      const g = fitGradient(s);
      if (g) {
        const tx = clamp(mem.px + 8 * g.x / g.mag, 2, mem.mapSize - 2);
        const ty = clamp(mem.py + 8 * g.y / g.mag, 2, mem.mapSize - 2);
        if (dist(tx, ty, s.cx, s.cy) < 30 &&
            dist(tx, ty, mem.px, mem.py) > 3.5) {
          s.guideActive = true;
          s.guideX = tx;
          s.guideY = ty;
          s.guideStart = now;
          s.guideCount++;
          return { failed: false, x: tx, y: ty,
            vmax: 0.72, stop: 1.8 };
        }
      }
    }

    const p = mem.spiral[s.index];
    return {
      failed: false,
      x: s.cx + p[0],
      y: s.cy + p[1],
      vmax: 0.78,
      stop: 1.9
    };
  }

  function clearActiveHint() {
    mem.activeHint = -1;
    mem.search = null;
    mem.chargeWaitStart = -1;
    mem.chargeWaitKey = "";
  }

  function baseDistanceForEnergy() {
    return beacon ? Math.max(0, Number(beacon.distance)) : gpsBaseD;
  }

  function siteAction(siteObj) {
    let d, bearing, value;
    if (siteObj) {
      d = Math.max(0, num(siteObj.distance, 99));
      bearing = num(siteObj.bearing, 0);
      value = Math.max(0.1, num(siteObj.value, 1));
      const abs = (mem.hEst + bearing) * rad;
      mem.siteX = mem.px + d * Math.cos(abs);
      mem.siteY = mem.py + d * Math.sin(abs);
      mem.siteValue = value;
      mem.siteLast = now;
      mem.siteValid = true;
    } else if (mem.siteValid && now - num(mem.siteLast, -100) < 2.2 &&
        Number.isFinite(mem.siteX) && Number.isFinite(mem.siteY)) {
      const dx = mem.siteX - mem.px;
      const dy = mem.siteY - mem.py;
      d = Math.hypot(dx, dy);
      const abs = d > 0.001 ? Math.atan2(dy, dx) / rad : mem.hEst;
      bearing = wrap(abs - mem.hEst);
      value = Math.max(0.1, num(mem.siteValue, 1));
    } else {
      mem.siteValid = false;
      return null;
    }

    const homeD = baseDistanceForEnergy();
    const loadAfter = carried + 1;
    const remaining = clamp(6 - drillProgress, 0, 6);
    const safeEnergy = returnEnergy(homeD, loadAfter) +
      remaining * mem.eDrill + 0.055;
    const safeTime = returnSeconds(homeD, loadAfter) +
      remaining + 14;

    if (carried >= mem.capacity || battery < safeEnergy ||
        timeLeft < safeTime) {
      mem.returning = true;
      mem.siteValid = false;
      return baseAction();
    }

    if (d <= 1.18) {
      pauseSearches();
      const still = Math.abs(vActual) < 0.12 &&
        Math.max(Math.abs(wl), Math.abs(wr)) < 0.18;
      if (!still) return drive(0, 0, false);

      if (!mem.drillActive && drillProgress <= 0.01) {
        mem.drillActive = true;
        mem.drillStart = now;
        mem.drillX = mem.siteX;
        mem.drillY = mem.siteY;
        mem.drillValue = value;
        mem.drillHint = mem.activeHint;
      }
      return drive(0, 0, true);
    }

    return navigateRel(bearing, d, d > 4 ? 0.65 : 0.42, 0.88);
  }

  const siteObj = obs.site && typeof obs.site === "object"
    ? obs.site
    : null;

  if (inProgress) {
    pauseSearches();
    const remaining = clamp(6 - drillProgress, 0, 6);
    const homeD = baseDistanceForEnergy();
    const canFinish = carried < mem.capacity &&
      battery > returnEnergy(homeD, carried + 1) +
        remaining * mem.eDrill + 0.045 &&
      timeLeft > returnSeconds(homeD, carried + 1) + remaining + 10;
    if (canFinish) return drive(0, 0, true);
    mem.drillActive = false;
    mem.returning = true;
    return baseAction();
  }

  const baseClose = !!obs.docked || baseMetric <= 2.45;
  if (baseClose && carried === 0) mem.returning = false;

  if (baseClose && carried > 0) {
    mem.returning = true;
    pauseSearches();
    if (baseMetric > 0.75 && !obs.docked) return baseAction();
    return drive(0, 0, false);
  }

  const homeD = baseDistanceForEnergy();
  if (!baseClose && (mem.returning ||
      carried >= mem.capacity ||
      battery < returnEnergy(homeD, carried) + 0.055 ||
      timeLeft < returnSeconds(homeD, carried) + 14)) {
    mem.returning = true;
    return baseAction();
  }

  if (bumped && now < num(mem.recoverUntil, -1000)) {
    const recovery = recoveryCommand();
    if (recovery) return recovery;
  }

  if (siteObj || (mem.siteValid && now - num(mem.siteLast, -100) < 2.2)) {
    const out = siteAction(siteObj);
    if (out) return out;
  }

  function hintAction(atBase) {
    for (let tries = 0; tries < 6; tries++) {
      let i = Math.floor(num(mem.activeHint, -1));
      if (i < 0 || !mem.hints[i] || mem.hints[i].status !== 0) {
        i = pickHint();
        if (i < 0) return null;
        mem.activeHint = i;
        mem.search = null;
      }

      const h = mem.hints[i];
      if (!h || h.status !== 0) {
        clearActiveHint();
        continue;
      }

      const p = hintPlan(i);
      if (p.time > timeLeft - 10 || p.need > 1.04) {
        h.status = 3;
        clearActiveHint();
        continue;
      }

      if (atBase && battery < p.need + 0.012) {
        const key = "h" + i;
        if (mem.chargeWaitKey !== key) {
          mem.chargeWaitKey = key;
          mem.chargeWaitStart = now;
        }
        if (now - num(mem.chargeWaitStart, now) < 85) {
          return holdAtBase();
        }
        h.status = 3;
        clearActiveHint();
        continue;
      }
      if (!atBase && battery < p.need + 0.035) {
        mem.returning = true;
        return baseAction();
      }
      mem.chargeWaitStart = -1;
      mem.chargeWaitKey = "";

      const d = dist(mem.px, mem.py, h.x, h.y);
      if (!mem.search || mem.search.hint !== i) {
        if (d > 6) return navigatePoint(h.x, h.y, 0.80, 4.5);
        mem.search = beginSearch(h.x, h.y, i, hintBudget(h));
      } else if (d > 8 && mem.search.spent < 1) {
        return navigatePoint(h.x, h.y, 0.80, 4.5);
      }

      if (d > 6 && !mem.search) {
        return navigatePoint(h.x, h.y, 0.80, 4.5);
      }
      if (!mem.search) {
        mem.search = beginSearch(h.x, h.y, i, hintBudget(h));
      }

      const q = searchDirective(mem.search);
      if (q.failed) {
        h.status = 2;
        clearActiveHint();
        continue;
      }
      return navigatePoint(q.x, q.y, q.vmax, q.stop);
    }
    return null;
  }

  function freeAction(atBase) {
    const offsets = [
      [0, 0], [12, 0], [0, 12], [-12, 0], [0, -12],
      [12, 12], [-12, 12], [-12, -12], [12, -12]
    ];
    if (!mem.freeSearch) {
      if (!atBase) return null;
      if (mem.freeIndex >= offsets.length) return null;
      const off = offsets[Math.floor(mem.freeIndex)];
      const cx = clamp(mem.baseX + off[0], 3, mem.mapSize - 3);
      const cy = clamp(mem.baseY + off[1], 3, mem.mapSize - 3);
      mem.freeSearch = beginSearch(cx, cy, -2, 55);
      mem.freeWaitStart = -1;
    }

    const s = mem.freeSearch;
    const dCenter = dist(mem.px, mem.py, s.cx, s.cy);
    const remaining = Math.max(0, s.budget - num(s.spent, 0));
    const dBack = dist(s.cx, s.cy, mem.baseX, mem.baseY) + 12;
    const total = dCenter + remaining + dBack;
    const need = 0.10 + total * mem.ePerM * 1.55 *
      (1 + 0.14 * carried) + 0.02 * (carried + 1);
    const timeNeed = total * 1.9 + 45 + 7 * carried;

    if (timeNeed > timeLeft - 10 || need > 1.04) {
      mem.freeSearch = null;
      mem.freeIndex++;
      return null;
    }
    if (atBase && battery < need + 0.01) {
      if (mem.freeWaitStart < 0) mem.freeWaitStart = now;
      if (now - mem.freeWaitStart < 65) return holdAtBase();
      mem.freeSearch = null;
      mem.freeIndex++;
      mem.freeWaitStart = -1;
      return null;
    }
    if (!atBase && battery < need + 0.035) {
      mem.returning = true;
      return baseAction();
    }

    if (dCenter > 6) return navigatePoint(s.cx, s.cy, 0.75, 4.5);

    const q = searchDirective(s);
    if (q.failed) {
      mem.freeSearch = null;
      mem.freeIndex++;
      return null;
    }
    return navigatePoint(q.x, q.y, q.vmax, q.stop);
  }

  const candidateOut = hintAction(baseClose);
  if (candidateOut) return candidateOut;

  if (baseClose) {
    const freeOut = freeAction(true);
    if (freeOut) return freeOut;
    return holdAtBase();
  }

  if (carried > 0 || battery < returnEnergy(homeD, carried) + 0.08 ||
      timeLeft < returnSeconds(homeD, carried) + 18) {
    mem.returning = true;
    return baseAction();
  }

  const freeOut = freeAction(false);
  if (freeOut) return freeOut;

  mem.returning = true;
  return baseAction();
