function act(obs, mem) {
  if (!mem || typeof mem !== "object") mem = {};

  const rad = Math.PI / 180;
  const clamp = (x, lo, hi) => Math.max(lo, Math.min(hi, x));
  const num = (v, d) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : d;
  };
  const wrap = (a) => {
    a %= 360;
    if (a > 180) a -= 360;
    if (a < -180) a += 360;
    return a;
  };
  const dist = (x1, y1, x2, y2) => Math.hypot(x1 - x2, y1 - y2);

  function makeSpiral(step, maxR) {
    const pts = [[0, 0]];
    let x = 0, y = 0, dir = 0, len = 1, stop = false;
    for (let k = 0; k < 100 && !stop; k++) {
      for (let rep = 0; rep < 2 && !stop; rep++) {
        for (let j = 0; j < len; j++) {
          if (dir === 0) x += step;
          else if (dir === 1) y += step;
          else if (dir === 2) x -= step;
          else y -= step;
          if (Math.hypot(x, y) > maxR) {
            stop = true;
            break;
          }
          pts.push([x, y]);
        }
        dir = (dir + 1) % 4;
      }
      len++;
    }
    return pts;
  }

  const mission = obs && obs.mission ? obs.mission : {};
  if (!mem._init) {
    const b = mission.base || {};
    mem.baseX = num(b.x, num(obs && obs.x, 200));
    mem.baseY = num(b.y, num(obs && obs.y, 200));
    mem.mapSize = Math.max(40, num(mission.size, 400));
    mem.totalSeconds = Math.max(1, num(mission.seconds, 1200));
    mem.capacity = Math.max(1, Math.floor(num(mission.capacity, 5)));

    mem.hints = [];
    const hs = Array.isArray(mission.hints) ? mission.hints : [];
    for (let i = 0; i < hs.length; i++) {
      const h = hs[i] || {};
      const x = Number(h.x), y = Number(h.y);
      if (Number.isFinite(x) && Number.isFinite(y)) {
        mem.hints.push({
          x: clamp(x, 2, mem.mapSize - 2),
          y: clamp(y, 2, mem.mapSize - 2),
          v: Math.max(0.1, num(h.estimate, 1)),
          status: 0
        });
      }
    }

    mem.spiral = makeSpiral(7, 29);
    mem.activeHint = -1;
    mem.search = null;
    mem.freeSearch = null;
    mem.freeIndex = 0;
    mem.returning = false;

    mem.siteValid = false;
    mem.siteX = NaN;
    mem.siteY = NaN;
    mem.siteValue = 0;
    mem.siteLast = -100;

    mem.drillActive = false;
    mem.drillStart = -100;
    mem.drillX = NaN;
    mem.drillY = NaN;
    mem.drillValue = 0;
    mem.drillHint = -1;
    mem.lastCarried = NaN;

    mem.ePerM = 0.001;
    mem.eDrill = 0.0035;
    mem.energyReady = false;
    mem.energyDist = 0;
    mem.energyDraw = 0;
    mem.drillSeconds = 0;
    mem.drillEnergy = 0;

    mem.poseReady = false;
    mem.px = num(obs && obs.x, mem.baseX);
    mem.py = num(obs && obs.y, mem.baseY);
    mem.hEst = 0;
    mem.odo = 0;
    mem.gpsFrozen = false;
    mem.gpsRepeat = 0;
    mem.gpsStillOdo = 0;
    mem.calX = NaN;
    mem.calY = NaN;

    mem.gL = 2.0;
    mem.gR = 2.0;
    mem.minCmdL = 0.10;
    mem.minCmdR = 0.10;
    mem.stallL = 0;
    mem.stallR = 0;
    mem.prevOutL = 0;
    mem.prevOutR = 0;
    mem.prevTargetL = 0;
    mem.prevTargetR = 0;
    mem.prevSlope = 0;
    mem.prevDrillCommand = false;

    mem.rayPrev = new Array(9);
    mem.rayBad = new Array(9).fill(false);
    mem.rayOdo = new Array(9).fill(0);
    mem.rayTime = new Array(9).fill(0);
    mem.rayHead = new Array(9).fill(0);

    mem.sigPts = [];
    mem.bestScience = 0;
    mem.bestScienceX = mem.baseX;
    mem.bestScienceY = mem.baseY;

    mem.bumpPrev = false;
    mem.recoverStart = -1000;
    mem.recoverUntil = -1000;
    mem.recoverSide = 1;
    mem.recoverCooldown = 0;

    mem.navGoalX = NaN;
    mem.navGoalY = NaN;
    mem.navBestD = Infinity;
    mem.navLastProgress = 0;
    mem.navStuck = 0;
    mem.navFailed = false;
    mem.prevNow = NaN;
    mem._init = true;
  }

  if (!Array.isArray(mem.hints)) mem.hints = [];
  if (!Array.isArray(mem.spiral) || mem.spiral.length < 2) {
    mem.spiral = makeSpiral(7, 29);
  }
  if (!Array.isArray(mem.sigPts)) mem.sigPts = [];
  if (!Array.isArray(mem.rayPrev)) mem.rayPrev = new Array(9);
  if (!Array.isArray(mem.rayBad)) mem.rayBad = new Array(9).fill(false);
  if (!Array.isArray(mem.rayOdo)) mem.rayOdo = new Array(9).fill(0);
  if (!Array.isArray(mem.rayTime)) mem.rayTime = new Array(9).fill(0);
  if (!Array.isArray(mem.rayHead)) mem.rayHead = new Array(9).fill(0);
  if (!Number.isFinite(mem.ePerM)) mem.ePerM = 0.001;
  if (!Number.isFinite(mem.eDrill)) mem.eDrill = 0.0035;
  if (!Number.isFinite(mem.activeHint)) mem.activeHint = -1;

  const hasTimeLeft = obs && obs.timeLeft !== undefined &&
    obs.timeLeft !== null && Number.isFinite(Number(obs.timeLeft));
  const now = obs && Number.isFinite(Number(obs.t))
    ? Math.max(0, Number(obs.t))
    : Math.max(0, mem.totalSeconds - num(obs && obs.timeLeft, mem.totalSeconds));
  let dt = 0.1;
  if (Number.isFinite(mem.prevNow)) {
    const dtt = now - mem.prevNow;
    if (dtt > 0.015 && dtt < 0.8) dt = dtt;
  }
  dt = clamp(dt, 0.03, 0.3);
  mem.prevNow = now;
  const timeLeft = hasTimeLeft
    ? Math.max(0, Number(obs.timeLeft))
    : Math.max(0, mem.totalSeconds - now);

  const rawH = wrap(num(obs.heading, 0));
  const wl = num(obs.wheelLeft, 0);
  const wr = num(obs.wheelRight, 0);
  const vActual = clamp((wl + wr) * 0.5, -3.2, 3.2);
  const yawActual = clamp((wr - wl) / 0.6, -8, 8);
  const gpsValid = Number.isFinite(Number(obs.x)) &&
    Number.isFinite(Number(obs.y));
  const gx = gpsValid ? Number(obs.x) : NaN;
  const gy = gpsValid ? Number(obs.y) : NaN;

  if (!mem.poseReady) {
    mem.px = gpsValid ? gx : mem.baseX;
    mem.py = gpsValid ? gy : mem.baseY;
    mem.hEst = rawH;
    mem.gpsPrevX = gpsValid ? gx : NaN;
    mem.gpsPrevY = gpsValid ? gy : NaN;
    mem.prevRawH = rawH;
    mem.odo = 0;
    mem.gpsFrozen = false;
    mem.gpsRepeat = 0;
    mem.gpsStillOdo = 0;
    mem.poseReady = true;
  } else {
    const oldX = num(mem.px, mem.baseX);
    const oldY = num(mem.py, mem.baseY);
    const oldH = num(mem.hEst, rawH);
    const yawDeg = yawActual * dt / rad;
    const predH = wrap(oldH + yawDeg);
    const cErr = wrap(rawH - predH);
    let hNew = predH;
    if (Math.abs(cErr) < 55) {
      const gain = Math.abs(yawActual) > 0.45 ? 0.08 : 0.14;
      hNew = wrap(predH + gain * cErr);
    }
    mem.hEst = hNew;

    const step = clamp(vActual * dt, -0.5, 0.5);
    const midH = wrap(oldH + yawDeg * 0.5) * rad;
    let px = oldX + step * Math.cos(midH);
    let py = oldY + step * Math.sin(midH);
    mem.odo = num(mem.odo, 0) + Math.abs(step);

    let rawGpsStep = Infinity;
    if (gpsValid && Number.isFinite(mem.gpsPrevX) &&
        Number.isFinite(mem.gpsPrevY)) {
      rawGpsStep = dist(gx, gy, mem.gpsPrevX, mem.gpsPrevY);
      if (rawGpsStep < 0.025 && Math.abs(vActual) > 0.25) {
        mem.gpsRepeat = num(mem.gpsRepeat, 0) + 1;
        mem.gpsStillOdo = num(mem.gpsStillOdo, 0) + Math.abs(step);
        if (mem.gpsRepeat > 16 && mem.gpsStillOdo > 1.2) {
          mem.gpsFrozen = true;
        }
      } else if (rawGpsStep > 0.06) {
        mem.gpsRepeat = 0;
        mem.gpsStillOdo = 0;
        if (rawGpsStep > 0.25) mem.gpsFrozen = false;
      }
    }

    const recovered = !!mem.gpsFrozen && rawGpsStep > 0.3;
    if (recovered) mem.gpsFrozen = false;
    if (gpsValid && !mem.gpsFrozen) {
