        mem.calX = gx;
        mem.calY = gy;
      }
    } else {
      mem.calX = NaN;
      mem.calY = NaN;
    }

    if (gpsValid) {
      mem.gpsPrevX = gx;
      mem.gpsPrevY = gy;
    }
    mem.prevRawH = rawH;
  }

  const battery = Math.max(0, num(obs.battery, 1));
  const solar = Math.max(0, num(obs.solar, 0));
  const drillProgress = clamp(num(obs.drilling, 0), 0, 6);
  const dockedNow = !!obs.docked;

  if (!mem.energyReady) {
    mem.prevBattery = battery;
    mem.prevSolar = solar;
    mem.energyDist = 0;
    mem.energyDraw = 0;
    mem.drillSeconds = 0;
    mem.drillEnergy = 0;
    mem.energyReady = true;
  } else {
    const net = num(mem.prevBattery, battery) - battery +
      0.5 * (num(mem.prevSolar, solar) + solar) * dt;
    const draw = Math.max(0, net);
    const wasDrilling = drillProgress > 0.01 ||
      !!mem.prevDrillCommand;
    if (!dockedNow && wasDrilling) {
      mem.drillSeconds = num(mem.drillSeconds, 0) + dt;
      mem.drillEnergy = num(mem.drillEnergy, 0) + draw;
    } else if (!dockedNow) {
      const equivalent = (Math.abs(vActual) +
        0.15 * Math.abs(yawActual)) * dt;
      if (equivalent > 0.01) {
        mem.energyDist = num(mem.energyDist, 0) + equivalent;
        mem.energyDraw = num(mem.energyDraw, 0) + draw;
        if (mem.energyDist >= 8) {
          const measured = mem.energyDraw / Math.max(1, mem.energyDist);
          if (Number.isFinite(measured) && measured > 0.00005) {
            const target = clamp(measured * 1.35, 0.00055, 0.012);
            const alpha = target > mem.ePerM ? 0.25 : 0.10;
            mem.ePerM = clamp((1 - alpha) * mem.ePerM +
              alpha * target, 0.0005, 0.015);
          }
          mem.energyDist = 0;
          mem.energyDraw = 0;
        }
      }
    }

    if (!wasDrilling && num(mem.drillSeconds, 0) >= 3) {
      const measured = num(mem.drillEnergy, 0) /
        Math.max(1, num(mem.drillSeconds, 0));
      if (Number.isFinite(measured) && measured > 0.00002) {
        const target = clamp(measured * 1.3, 0.0002, 0.04);
        mem.eDrill = clamp(0.75 * mem.eDrill + 0.25 * target,
          0.0002, 0.05);
      }
      mem.drillSeconds = 0;
      mem.drillEnergy = 0;
    }
    mem.prevBattery = battery;
    mem.prevSolar = solar;
  }

  const science = Math.max(0, num(obs.science, 0));
  const lastSig = mem.sigPts.length
    ? mem.sigPts[mem.sigPts.length - 1]
    : null;
  if (!lastSig || dist(mem.px, mem.py, lastSig.x, lastSig.y) > 2 ||
