  for (let i = 0; i < 9; i++) {
    if (i >= rays.length || !Number.isFinite(Number(rays[i]))) continue;
    const r = Number(rays[i]);
    if (!Number.isFinite(mem.rayPrev[i])) {
      mem.rayPrev[i] = r;
      mem.rayOdo[i] = num(mem.odo, 0);
      mem.rayTime[i] = now;
      mem.rayHead[i] = mem.hEst;
    } else if (Math.abs(r - mem.rayPrev[i]) > 0.08) {
      mem.rayPrev[i] = r;
      mem.rayOdo[i] = num(mem.odo, 0);
      mem.rayTime[i] = now;
      mem.rayHead[i] = mem.hEst;
      mem.rayBad[i] = false;
    } else if (r < 14.8 &&
        num(mem.odo, 0) - num(mem.rayOdo[i], 0) > 7 &&
        now - num(mem.rayTime[i], now) > 9 &&
        Math.abs(wrap(mem.hEst - num(mem.rayHead[i], mem.hEst))) > 35) {
      mem.rayBad[i] = true;
    }
  }

  function clearanceSide() {
    let left = 0, right = 0, nl = 0, nr = 0;
    for (let i = 0; i < 9; i++) {
      if (i >= rays.length || !Number.isFinite(Number(rays[i]))) continue;
      const r = Number(rays[i]);
      if (i > 4) {
        left += r;
        nl++;
      } else if (i < 4) {
        right += r;
        nr++;
      }
    }
    const l = left / Math.max(1, nl);
    const r = right / Math.max(1, nr);
    if (Math.abs(l - r) < 0.3) return -num(mem.recoverSide, 1);
    return l >= r ? 1 : -1;
  }

  function startRecovery(side) {
    mem.recoverSide = side >= 0 ? 1 : -1;
    mem.recoverStart = now;
    mem.recoverUntil = now + 1.15;
    mem.recoverCooldown = now + 8;
  }

  const carried = Math.max(0, Math.floor(num(obs.carried, 0)));

  function markSampled() {
    const sx = num(mem.drillX, num(mem.siteX, mem.px));
    const sy = num(mem.drillY, num(mem.siteY, mem.py));
    const hintIndex = Math.floor(num(mem.drillHint, -1));

    if (hintIndex >= 0 && mem.hints[hintIndex]) {
      mem.hints[hintIndex].status = 1;
    }
    let closest = -1;
    let closestD = 20;
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status !== 0) continue;
      const d = dist(sx, sy, h.x, h.y);
      if (d < closestD) {
        closestD = d;
        closest = i;
      }
    }
    if (closest >= 0) mem.hints[closest].status = 1;

    if (mem.activeHint >= 0 && mem.hints[mem.activeHint] &&
        dist(sx, sy, mem.hints[mem.activeHint].x,
          mem.hints[mem.activeHint].y) < 42) {
      mem.hints[mem.activeHint].status = 1;
    }

    mem.activeHint = -1;
    mem.search = null;
    mem.drillActive = false;
    mem.drillX = NaN;
    mem.drillY = NaN;
    mem.drillValue = 0;
    mem.drillHint = -1;
    mem.siteValid = false;
  }

  let justSampled = false;
  if (!Number.isFinite(mem.lastCarried)) {
    mem.lastCarried = carried;
  } else if (carried > mem.lastCarried) {
    justSampled = true;
    markSampled();
  }
  mem.lastCarried = carried;

  if (drillProgress > 0.01 && !mem.drillActive) {
    mem.drillActive = true;
    mem.drillStart = now;
  }

  const siteObj = obs.site && typeof obs.site === "object"
    ? obs.site
    : null;
  if (siteObj && !mem.drillActive) {
    const sd = Math.max(0, num(siteObj.distance, 99));
    const sb = num(siteObj.bearing, 0);
    const a = (mem.hEst + sb) * rad;
    mem.siteX = mem.px + sd * Math.cos(a);
    mem.siteY = mem.py + sd * Math.sin(a);
    mem.siteValue = Math.max(0.1, num(siteObj.value, 1));
    mem.siteValid = true;
    mem.siteLast = now;
  }

  function drive(v, omega, drill) {
    v = clamp(v, -0.85, 0.85);
    omega = clamp(omega, -1.8, 1.8);
    const pitch = num(obs.pitch, 0);
    const slope = clamp(Math.sin(pitch * rad) * 0.12, -0.18, 0.18);
    const targetL = clamp(v - omega * 0.3, -0.95, 0.95);
    const targetR = clamp(v + omega * 0.3, -0.95, 0.95);

    function motor(target, actual, side) {
      let gain = side === 0 ? num(mem.gL, 2.0) : num(mem.gR, 2.0);
      const prevOut = side === 0
        ? num(mem.prevOutL, 0)
        : num(mem.prevOutR, 0);
      const prevTarget = side === 0
        ? num(mem.prevTargetL, 0)
        : num(mem.prevTargetR, 0);
      const prevSlope = num(mem.prevSlope, 0);

      if (Math.abs(prevTarget) > 0.22 &&
          Math.abs(actual) > 0.08 &&
          prevTarget * actual > 0 &&
          prevOut * prevTarget > 0 &&
          Math.abs(prevOut) > 0.12 &&
          Math.abs(prevOut) < 0.92) {
        const eff = prevOut - prevSlope;
        if (Math.abs(eff) > 0.12) {
          const estimate = clamp(Math.abs(actual / eff), 0.55, 4.5);
          gain = clamp(0.98 * gain + 0.02 * estimate, 0.55, 4.5);
          if (side === 0) mem.gL = gain;
          else mem.gR = gain;
        }
      }

      let minCmd = side === 0
        ? num(mem.minCmdL, 0.10)
        : num(mem.minCmdR, 0.10);
      let stall = side === 0
        ? num(mem.stallL, 0)
        : num(mem.stallR, 0);

      if (Math.abs(target) < 0.035) {
        stall = Math.max(0, stall - dt * 0.5);
        if (side === 0) mem.stallL = stall;
        else mem.stallR = stall;
        return clamp(-0.58 * actual + slope, -1, 1);
      }

      if (Math.abs(target) > 0.23 && Math.abs(actual) < 0.07 &&
          Math.abs(prevOut) > 0.12 && prevOut * target > 0 &&
          prevTarget * target > 0) {
        stall += dt;
        if (stall > 0.8) {
          minCmd = Math.min(0.30, minCmd + 0.02);
          stall = 0;
        }
      } else if (Math.abs(actual) > 0.12) {
        stall = Math.max(0, stall - dt * 0.7);
        minCmd = Math.max(0.08, minCmd - dt * 0.001);
      } else {
        stall = Math.max(0, stall - dt * 0.2);
      }

      const error = target - actual;
      let u = target / Math.max(0.55, gain) + 0.16 * error + slope;
      if (Math.abs(target) > 0.12 && target * u > 0 &&
          Math.abs(u) < minCmd &&
          Math.abs(actual) < Math.abs(target) * 0.75) {
        u = Math.sign(target) * minCmd;
      }

      if (side === 0) {
        mem.minCmdL = minCmd;
        mem.stallL = stall;
      } else {
        mem.minCmdR = minCmd;
        mem.stallR = stall;
      }
      return clamp(u, -1, 1);
    }

    const left = motor(targetL, wl, 0);
    const right = motor(targetR, wr, 1);
    mem.prevOutL = left;
    mem.prevOutR = right;
    mem.prevTargetL = targetL;
    mem.prevTargetR = targetR;
    mem.prevSlope = slope;
    mem.prevDrillCommand = !!drill;
    return { left: left, right: right, drill: !!drill };
  }

  function recoveryCommand() {
    if (now >= num(mem.recoverUntil, -1000)) return null;
    const age = now - num(mem.recoverStart, now);
    const side = num(mem.recoverSide, 1);
    if (age < 0.48) return drive(-0.28, side * 0.42, false);
    return drive(0, side * 0.68, false);
  }

  function chooseSteering(goalRel) {
    const angles = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
    const points = [];
    let valid = 0;
    for (let i = 0; i < 9; i++) {
      if (i >= rays.length || mem.rayBad[i]) continue;
      const r = Number(rays[i]);
      if (!Number.isFinite(r)) continue;
      valid++;
      if (r > 0.05 && r < 14.8) points.push({ r: r, a: angles[i] });
    }

    const candidates = [];
    for (let a = -80; a <= 80; a += 10) candidates.push(a);
    candidates.push(clamp(goalRel, -80, 80));

    let bestA = clamp(goalRel, -80, 80);
    let bestCost = Infinity;
    let bestRisk = 0;
    let bestClear = Infinity;

    for (let ci = 0; ci < candidates.length; ci++) {
      const a = candidates[ci];
      let risk = 0;
      let minClear = Infinity;

      for (let j = 0; j < points.length; j++) {
        const p = points[j];
        const da = (p.a - a) * rad;
        const along = p.r * Math.cos(da);
        if (along <= 0.1 || along > 7) continue;
        const lateral = Math.abs(p.r * Math.sin(da));
        const corridor = 0.78 + 0.065 * along;
        if (lateral < corridor) {
          const penetration = (corridor - lateral) / corridor;
          risk += penetration * (4 + 8 / (along + 0.35));
          if (along < 1.35) risk += 12;
          minClear = Math.min(minClear, along - corridor);
        } else if (lateral < corridor + 0.45 && along < 4.5) {
          risk += (corridor + 0.45 - lateral) * 0.35;
          minClear = Math.min(minClear, along - corridor);
        }
      }

      const wx = mem.px + 4 * Math.cos((mem.hEst + a) * rad);
      const wy = mem.py + 4 * Math.sin((mem.hEst + a) * rad);
      let edgeCost = 0;
      if (wx < 2 || wx > mem.mapSize - 2 ||
          wy < 2 || wy > mem.mapSize - 2) {
        edgeCost = 40;
      } else {
        const edge = Math.min(wx, wy, mem.mapSize - wx, mem.mapSize - wy);
        if (edge < 5) edgeCost = (5 - edge) * 1.2;
      }

      const cost = 0.035 * Math.abs(wrap(a - goalRel)) +
        0.00008 * a * a + risk + edgeCost;
      if (cost < bestCost) {
        bestCost = cost;
        bestA = a;
        bestRisk = risk;
        bestClear = minClear;
      }
    }

    let clearV = 0.82;
    if (Number.isFinite(bestClear)) {
      if (bestClear < 0.1) clearV = 0.13;
      else clearV = Math.min(clearV,
        Math.sqrt(0.42 * Math.max(0, bestClear - 0.1)));
    }
    if (valid < 3) clearV = Math.min(clearV, 0.50);
    if (bestRisk > 18) clearV = Math.min(clearV, 0.13);
    else if (bestRisk > 12) clearV = Math.min(clearV, 0.26);

    return { a: bestA, risk: bestRisk, clearV: clearV };
  }

  function navigateRel(goalRel, d, vmax, stopR) {
    const recovery = recoveryCommand();
    if (recovery) return recovery;

    d = Math.max(0, num(d, 0));
    stopR = Math.max(0, num(stopR, 1));
    if (d <= stopR) return drive(0, 0, false);

    const gr = wrap(goalRel);
    if (Math.abs(gr) > 105) {
      return drive(0, clamp(Math.sign(gr) * 0.58, -0.58, 0.58), false);
    }

    const choice = chooseSteering(gr);
    const a = choice.a;
    const absA = Math.abs(a);
    const avail = Math.max(0, d - stopR);
    let v = Math.min(vmax, 0.78, Math.sqrt(0.65 * avail),
      choice.clearV);
    if (absA > 58) v = Math.min(v, 0.14);
    else if (absA > 38) v = Math.min(v, 0.36);
    if (d < 4) v = Math.min(v, 0.38);
    if (choice.risk > 18) v = Math.min(v, 0.12);

    const omega = clamp(1.15 * a * rad, -0.64, 0.64);
    return drive(v, omega, false);
  }

  function navigatePoint(tx, ty, vmax, stopR) {
    tx = clamp(tx, 2, mem.mapSize - 2);
    ty = clamp(ty, 2, mem.mapSize - 2);

    const recovery = recoveryCommand();
    if (recovery) return recovery;

    const dx = tx - mem.px;
    const dy = ty - mem.py;
    const d = Math.hypot(dx, dy);
    const bearing = d > 0.001 ? Math.atan2(dy, dx) / rad : mem.hEst;

    if (d > stopR + 2) {
      const newGoal = !Number.isFinite(mem.navGoalX) ||
        !Number.isFinite(mem.navGoalY) ||
        dist(tx, ty, mem.navGoalX, mem.navGoalY) > 3;
      if (newGoal) {
        mem.navGoalX = tx;
        mem.navGoalY = ty;
        mem.navBestD = d;
        mem.navLastProgress = now;
        mem.navStuck = 0;
        mem.navFailed = false;
      } else {
        if (d < num(mem.navBestD, d) - 0.65) {
          mem.navBestD = d;
          mem.navLastProgress = now;
          mem.navStuck = 0;
        }
        if (now - num(mem.navLastProgress, now) > 22 &&
            now > num(mem.recoverCooldown, 0)) {
          mem.navLastProgress = now;
          mem.navStuck = num(mem.navStuck, 0) + 1;
          if (mem.navStuck >= 3) {
            mem.navFailed = true;
            mem.navStuck = 0;
          }
          startRecovery(clearanceSide());
          return recoveryCommand();
        }
      }
    } else {
      mem.navGoalX = NaN;
      mem.navGoalY = NaN;
      mem.navStuck = 0;
    }

    return navigateRel(wrap(bearing - mem.hEst), d, vmax, stopR);
  }

  function fitGradient(tag, cx, cy, radius) {
    const pts = [];
    for (let i = 0; i < mem.sigPts.length; i++) {
      const p = mem.sigPts[i];
      if (now - p.t > 100) continue;
      if (tag !== null && p.h !== tag) continue;
      if (dist(p.x, p.y, cx, cy) > radius) continue;
      pts.push(p);
    }
    if (pts.length < 6) return null;

    let mx = 0, my = 0, ms = 0, smin = Infinity, smax = -Infinity;
    for (let i = 0; i < pts.length; i++) {
      mx += pts[i].x;
      my += pts[i].y;
      ms += pts[i].s;
      smin = Math.min(smin, pts[i].s);
      smax = Math.max(smax, pts[i].s);
    }
    mx /= pts.length;
    my /= pts.length;
    ms /= pts.length;
    if (smax - smin < Math.max(0.002, Math.abs(ms) * 0.04)) return null;

    let cxx = 0, cyy = 0, cxy = 0, cxs = 0, cys = 0, sst = 0;
    for (let i = 0; i < pts.length; i++) {
      const dx = pts[i].x - mx;
      const dy = pts[i].y - my;
      const ds = pts[i].s - ms;
      cxx += dx * dx;
      cyy += dy * dy;
      cxy += dx * dy;
      cxs += dx * ds;
      cys += dy * ds;
      sst += ds * ds;
    }
    const spread = cxx + cyy;
    if (spread < 18 || sst < 1e-8) return null;
    const lam = Math.max(0.25, spread * 0.025);
    const den = (cxx + lam) * (cyy + lam) - cxy * cxy;
    if (den <= 1e-9) return null;
    const gx = (cxs * (cyy + lam) - cys * cxy) / den;
    const gy = (cys * (cxx + lam) - cxs * cxy) / den;
    const mag = Math.hypot(gx, gy);
    const explained = (gx * cxs + gy * cys) / sst;
    if (!Number.isFinite(mag) || mag < 0.00008 || explained < 0.10) {
      return null;
    }
    return { x: gx, y: gy, mag: mag };
  }

  const beacon = obs.beacon &&
    Number.isFinite(Number(obs.beacon.distance))
    ? obs.beacon
    : null;
  const gpsBaseD = dist(mem.px, mem.py, mem.baseX, mem.baseY);
  const baseMetric = beacon
    ? Math.max(0, Number(beacon.distance))
    : gpsBaseD;
  const atBase = !!obs.docked || baseMetric <= 2.7;

  function pauseSearches() {
    if (mem.search) mem.search.lastOdo = num(mem.odo, 0);
    if (mem.freeSearch) mem.freeSearch.lastOdo = num(mem.odo, 0);
  }

  function baseAction() {
    mem.returning = true;
    pauseSearches();
    if (beacon) {
      return navigateRel(num(beacon.bearing, 0),
        Math.max(0, Number(beacon.distance)), 0.68, 0.85);
    }
    return navigatePoint(mem.baseX, mem.baseY, 0.68, 0.85);
  }

  function holdAtBase() {
    pauseSearches();
    if (obs.docked) return drive(0, 0, false);
    if (baseMetric > 1.05) return baseAction();
    return drive(0, 0, false);
  }

  function returnEnergy(d, load) {
    const n = Math.max(0, load);
    return 0.10 + Math.max(0, d) * mem.ePerM *
      2.0 * (1 + 0.20 * n) + 0.025 * n;
  }

  function returnSeconds(d, load) {
    return Math.max(0, d) / 0.48 + 27 + 9 * Math.max(0, load);
  }

  function hintPlan(i) {
    const h = mem.hints[i];
    if (!h) return { need: Infinity, time: Infinity, toHint: Infinity };
    const toHint = dist(mem.px, mem.py, h.x, h.y);
    const home = dist(h.x, h.y, mem.baseX, mem.baseY) * 1.20 + 8;
    let remaining = 75;
    if (mem.search && mem.activeHint === i) {
      remaining = Math.max(0,
        num(mem.search.budget, 75) - num(mem.search.spent, 0));
    }
    const total = toHint + home + remaining;
    const afterLoad = carried + 1;
    const need = 0.14 + total * mem.ePerM * 1.75 *
      (1 + 0.18 * afterLoad) + 6 * mem.eDrill +
      0.025 * afterLoad;
    const time = total / 0.55 + 35 + 9 * afterLoad;
    return { need: need, time: time, toHint: toHint, total: total };
  }

  function pickHint(atHome) {
    let best = -1;
    let bestScore = -Infinity;
    let fallback = -1;
    let fallbackNeed = Infinity;

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status !== 0) continue;
      const p = hintPlan(i);
      if (p.time > timeLeft - 18) continue;
      if (p.need < fallbackNeed) {
        fallbackNeed = p.need;
        fallback = i;
      }

      const affordable = atHome
        ? p.need <= Math.max(battery - 0.045, 0.65)
        : p.need <= battery - 0.05;
      if (!affordable) continue;

      let cluster = 0;
      for (let j = 0; j < mem.hints.length; j++) {
        if (j === i) continue;
        const q = mem.hints[j];
        if (!q || q.status !== 0) continue;
        const dd = dist(h.x, h.y, q.x, q.y);
        if (dd < 36) cluster += q.v * (1 - dd / 36);
      }
      const effective = h.v + Math.min(h.v * 0.7, cluster * 0.12);
      const homeD = dist(h.x, h.y, mem.baseX, mem.baseY);
      const score = effective / Math.pow(
        Math.max(1, 36 + p.toHint + 0.65 * homeD + 0.45 * 75), 0.9);
      if (score > bestScore) {
        bestScore = score;
        best = i;
      }
    }

    if (best >= 0) return best;
    if (atHome && fallback >= 0 && fallbackNeed <= 1.06) return fallback;
    return -1;
  }

  function beginSearch(cx, cy, hint, budget) {
    return {
      cx: cx,
      cy: cy,
      hint: hint,
      index: 0,
      start: now,
      budget: budget,
      spent: 0,
      lastOdo: num(mem.odo, 0),
      guideActive: false,
      guideX: 0,
      guideY: 0,
      guideStart: 0,
      guideCount: 0,
      guideCooldown: now + 8
    };
  }

  function searchDirective(s) {
    s.spent = num(s.spent, 0) +
      Math.max(0, num(mem.odo, 0) - num(s.lastOdo, mem.odo));
    s.lastOdo = num(mem.odo, 0);

    if (science > 0.004 && s.budget < 105) s.budget = 105;
    if (s.spent > s.budget || now - s.start > 360 ||
        s.index >= mem.spiral.length) {
      return { failed: true };
    }

    if (mem.navFailed) {
      mem.navFailed = false;
      mem.navGoalX = NaN;
      mem.navGoalY = NaN;
      if (s.guideActive) s.guideActive = false;
      else s.index++;
    }

    if (s.guideActive) {
      if (dist(mem.px, mem.py, s.guideX, s.guideY) < 2.8 ||
          now - s.guideStart > 22) {
        s.guideActive = false;
        s.guideCooldown = now + 9;
      } else {
        return { failed: false, x: s.guideX, y: s.guideY,
          vmax: 0.68, stop: 2.0 };
      }
    }

    while (s.index < mem.spiral.length) {
      const p = mem.spiral[s.index];
      const tx = s.cx + p[0];
      const ty = s.cy + p[1];
      if (tx < 2 || tx > mem.mapSize - 2 ||
          ty < 2 || ty > mem.mapSize - 2 ||
          dist(mem.px, mem.py, tx, ty) < 2.5) {
        s.index++;
      } else {
        break;
      }
    }
    if (s.index >= mem.spiral.length) return { failed: true };

    if (s.guideCount < 3 && now >= s.guideCooldown &&
        science > 0.002) {
      const g = fitGradient(s.hint, s.cx, s.cy, 42);
      if (g) {
        const tx = clamp(mem.px + 9 * g.x / g.mag, 2, mem.mapSize - 2);
        const ty = clamp(mem.py + 9 * g.y / g.mag, 2, mem.mapSize - 2);
        if (dist(tx, ty, s.cx, s.cy) < 27 &&
            dist(tx, ty, mem.px, mem.py) > 4) {
          s.guideActive = true;
          s.guideX = tx;
          s.guideY = ty;
          s.guideStart = now;
          s.guideCount++;
          return { failed: false, x: tx, y: ty,
            vmax: 0.68, stop: 2.0 };
        }
      }
    }

    const p = mem.spiral[s.index];
    return {
      failed: false,
      x: s.cx + p[0],
      y: s.cy + p[1],
      vmax: 0.70,
      stop: 2.1
    };
  }

  function clearActiveHint() {
    mem.activeHint = -1;
    mem.search = null;
  }

  function siteAction() {
    let d, bearing, value;
    if (siteObj) {
      d = Math.max(0, num(siteObj.distance, 99));
      bearing = num(siteObj.bearing, 0);
      value = Math.max(0.1, num(siteObj.value, 1));
    } else if (mem.siteValid && now - num(mem.siteLast, -100) < 1.8 &&
        Number.isFinite(mem.siteX) && Number.isFinite(mem.siteY)) {
      const dx = mem.siteX - mem.px;
      const dy = mem.siteY - mem.py;
      d = Math.hypot(dx, dy);
      const abs = d > 0.001 ? Math.atan2(dy, dx) / rad : mem.hEst;
      bearing = wrap(abs - mem.hEst);
      value = Math.max(0.1, num(mem.siteValue, 1));
    } else {
      mem.siteValid = false;
      return null;
    }

    const homeD = baseMetric;
    const needed = returnEnergy(homeD, carried + 1) +
      6 * mem.eDrill + 0.055;
    if (carried >= mem.capacity || battery < needed ||
        timeLeft < returnSeconds(homeD, carried + 1) + 24) {
      mem.returning = true;
      mem.siteValid = false;
      return baseAction();
    }

    if (d <= 1.15) {
      const still = Math.abs(vActual) < 0.13 &&
        Math.max(Math.abs(wl), Math.abs(wr)) < 0.20;
      if (!still) return drive(0, 0, false);

      if (!mem.drillActive) {
        mem.drillActive = true;
        mem.drillStart = now;
        mem.drillX = num(mem.siteX, mem.px);
        mem.drillY = num(mem.siteY, mem.py);
        mem.drillValue = value;
        mem.drillHint = mem.activeHint;
      }
      return drive(0, 0, true);
    }

    let speed = d > 4 ? 0.54 : (d > 2 ? 0.34 : 0.20);
    return navigateRel(bearing, d, speed, 0.88);
  }

  function hintAction(atHome) {
    for (let attempt = 0; attempt < 6; attempt++) {
      let i = Math.floor(num(mem.activeHint, -1));
      if (i < 0 || !mem.hints[i] || mem.hints[i].status !== 0) {
        i = pickHint(atHome);
        if (i < 0) return null;
        mem.activeHint = i;
        mem.search = null;
      }

      const h = mem.hints[i];
      if (!h || h.status !== 0) {
        clearActiveHint();
        continue;
      }

      const p = hintPlan(i);
      if (p.time > timeLeft - 14) {
        h.status = 3;
        clearActiveHint();
        continue;
      }
      if (p.need > 1.08) {
        h.status = 3;
        clearActiveHint();
        continue;
      }
      if (atHome && battery < p.need + 0.025) {
        return holdAtBase();
      }
      if (!atHome && p.need > battery - 0.035) {
        mem.returning = true;
        return baseAction();
      }

      const d = dist(mem.px, mem.py, h.x, h.y);
      if (d > 7) {
        if (mem.navFailed) {
          mem.navFailed = false;
          h.status = 2;
          clearActiveHint();
          continue;
        }
        return navigatePoint(h.x, h.y, 0.72, 4.2);
      }

      if (!mem.search || mem.search.hint !== i) {
        mem.search = beginSearch(h.x, h.y, i, 78);
      }

      const q = searchDirective(mem.search);
      if (q.failed) {
        h.status = 2;
        clearActiveHint();
        continue;
      }
      return navigatePoint(q.x, q.y, q.vmax, q.stop);
    }
    return null;
  }

  const freeOffsets = [
    [0, 0], [24, 0], [0, 24], [-24, 0], [0, -24],
    [24, 24], [-24, 24], [-24, -24], [24, -24],
    [42, 0], [0, 42], [-42, 0], [0, -42]
  ];

  function freeAction(atHome) {
    if (!mem.freeSearch) {
      if (!atHome) return null;
      const k = Math.floor(num(mem.freeIndex, 0));
      if (k >= freeOffsets.length) return null;
      const off = freeOffsets[k];
      let cx = clamp(mem.baseX + off[0], 3, mem.mapSize - 3);
      let cy = clamp(mem.baseY + off[1], 3, mem.mapSize - 3);
      if (num(mem.bestScience, 0) > 0.003 && k === 0) {
        cx = clamp(num(mem.bestScienceX, cx), 3, mem.mapSize - 3);
        cy = clamp(num(mem.bestScienceY, cy), 3, mem.mapSize - 3);
      }
      mem.freeSearch = beginSearch(cx, cy, -2, 46);
    }

    const s = mem.freeSearch;
    const remaining = Math.max(0, s.budget - num(s.spent, 0));
    const dCenter = dist(mem.px, mem.py, s.cx, s.cy);
    const dBack = dist(s.cx, s.cy, mem.baseX, mem.baseY) * 1.2 + 8;
    const total = dCenter + dBack + remaining;
    const need = 0.14 + total * mem.ePerM * 1.7 *
      (1 + 0.18 * carried) + 6 * mem.eDrill +
      0.025 * (carried + 1);
    const timeNeed = total / 0.55 + 34 + 9 * (carried + 1);

    if (timeNeed > timeLeft - 14 || need > 1.08) {
      mem.freeSearch = null;
      mem.freeIndex++;
      return null;
    }
    if (atHome && battery < need + 0.02) return holdAtBase();
    if (!atHome && battery < need + 0.035) {
      mem.returning = true;
      return baseAction();
    }

    if (dCenter > 7) {
      if (mem.navFailed) {
        mem.navFailed = false;
        mem.freeSearch = null;
        mem.freeIndex++;
        return null;
      }
      return navigatePoint(s.cx, s.cy, 0.70, 4.2);
    }

    const q = searchDirective(s);
    if (q.failed) {
      mem.freeSearch = null;
      mem.freeIndex++;
      return null;
    }
    return navigatePoint(q.x, q.y, q.vmax, q.stop);
  }

  if (drillProgress > 0.01 && !mem.drillActive) {
    mem.drillActive = true;
    mem.drillStart = now;
  }
  if (!justSampled && mem.drillActive) {
    if (now - num(mem.drillStart, now) <= 9) {
      return drive(0, 0, true);
    }
    mem.drillActive = false;
    mem.siteValid = false;
  }

