      const wx = mem.px + 4 * Math.cos((mem.hEst + a) * rad);
      const wy = mem.py + 4 * Math.sin((mem.hEst + a) * rad);
      let edgeCost = 0;
      if (wx < 2 || wx > mem.mapSize - 2 ||
          wy < 2 || wy > mem.mapSize - 2) {
