      } else {
        const edge = Math.min(wx, wy, mem.mapSize - wx, mem.mapSize - wy);
        if (edge < 5) edgeCost = (5 - edge) * 1.1;
      }

      const cost = 0.026 * Math.abs(wrap(a - goalRel)) +
        0.00008 * a * a + risk + edgeCost;
      if (cost < bestCost) {
        bestCost = cost;
        bestA = a;
        bestRisk = risk;
        bestClear = clear;
      }
    }

    let safeV = 0.95;
    if (Number.isFinite(bestClear)) {
      if (bestClear < 0.1) safeV = 0.08;
      else safeV = Math.min(safeV,
        Math.sqrt(0.72 * Math.max(0, bestClear - 0.08)));
    }
    if (bestRisk > 22) safeV = Math.min(safeV, 0.08);
    else if (bestRisk > 15) safeV = Math.min(safeV, 0.16);
    else if (bestRisk > 10) safeV = Math.min(safeV, 0.30);

    return { a: bestA, risk: bestRisk, safeV: safeV };
  }

  function navigateRel(goalRel, d, vmax, stopR) {
    const recovery = recoveryCommand();
    if (recovery) return recovery;

    d = Math.max(0, num(d, 0));
    stopR = Math.max(0, num(stopR, 0.8));
    if (d <= stopR) return drive(0, 0, false);

    const gr = wrap(goalRel);
    if (Math.abs(gr) > 112) {
      const omega = Math.sign(gr) *
        clamp(Math.abs(gr) * rad * 1.15, 0.42, 0.9);
      return drive(0, omega, false);
    }

    const choice = chooseSteering(gr);
    const a = choice.a;
    const absA = Math.abs(a);

    if (absA > 32) {
      const omega = Math.sign(a) *
        clamp(absA * rad * 1.25, 0.38, 0.9);
      return drive(0, omega, false);
    }

    const avail = Math.max(0, d - stopR);
    let v = Math.min(vmax, 0.92,
      Math.sqrt(0.72 * avail), choice.safeV);
    v *= Math.max(0.55, Math.cos(a * rad));
    if (d < 3.5) v = Math.min(v, 0.48);
    if (choice.risk > 22) v = Math.min(v, 0.08);

    const omega = clamp(1.30 * a * rad, -0.72, 0.72);
    return drive(v, omega, false);
  }

  function resetNav() {
    mem.navGoalX = NaN;
    mem.navGoalY = NaN;
    mem.navBestD = Infinity;
    mem.navLastProgress = now;
    mem.navRetry = 0;
  }

  function navigatePoint(tx, ty, vmax, stopR) {
    tx = clamp(tx, 2, mem.mapSize - 2);
    ty = clamp(ty, 2, mem.mapSize - 2);

    const dx = tx - mem.px;
    const dy = ty - mem.py;
    const d = Math.hypot(dx, dy);
    const bearing = d > 0.001
      ? Math.atan2(dy, dx) / rad
      : mem.hEst;

    if (d <= stopR) {
      resetNav();
      return drive(0, 0, false);
    }

    const newGoal = !Number.isFinite(mem.navGoalX) ||
      !Number.isFinite(mem.navGoalY) ||
      dist(tx, ty, mem.navGoalX, mem.navGoalY) > 2.2;

    if (newGoal) {
      mem.navGoalX = tx;
      mem.navGoalY = ty;
      mem.navBestD = d;
      mem.navLastProgress = now;
      mem.navRetry = 0;
    } else {
      if (d < num(mem.navBestD, d) - 0.75) {
        mem.navBestD = d;
        mem.navLastProgress = now;
        mem.navRetry = 0;
      }
      if (now - num(mem.navLastProgress, now) > 22 &&
          now > num(mem.recoverCooldown, 0)) {
        mem.navLastProgress = now;
        mem.navRetry = num(mem.navRetry, 0) + 1;
        if (mem.navRetry >= 3) {
          mem.navFailed = true;
          return drive(0, 0, false);
        }
        startRecovery(clearanceSide());
        return recoveryCommand();
      }
    }

    return navigateRel(wrap(bearing - mem.hEst), d, vmax, stopR);
  }

  function returnEnergy(d, load) {
    const n = Math.max(0, load);
    return 0.09 + Math.max(0, d) * mem.ePerM *
      1.85 * (1 + 0.18 * n) + 0.02 * n;
  }

  function returnSeconds(d, load) {
    return Math.max(0, d) / 0.45 + 35 + 8 * Math.max(0, load);
  }

  function baseAction() {
    mem.mode = "return";
    mem.returning = true;
    pauseSearch();

    if (obs.docked) return drive(0, 0, false);
    if (beacon) {
      return navigateRel(
        num(beacon.bearing, 0),
        Math.max(0, Number(beacon.distance)),
        0.62,
        0.62
      );
    }
    return navigatePoint(mem.baseX, mem.baseY, 0.62, 0.62);
  }

  function holdAtBase() {
    pauseSearch();
    if (obs.docked) return drive(0, 0, false);
    if (baseMetric > 0.72) return baseAction();
    return drive(0, 0, false);
  }

  function siteAction() {
    let d, bearing, value;

    if (siteObj) {
      d = Math.max(0, num(siteObj.distance, 99));
      bearing = num(siteObj.bearing, 0);
      value = Math.max(0.1, num(siteObj.value, 1));
      const abs = (mem.hEst + bearing) * rad;
      mem.siteX = mem.px + d * Math.cos(abs);
      mem.siteY = mem.py + d * Math.sin(abs);
      mem.siteValue = value;
      mem.siteLast = now;
      mem.siteValid = true;
    } else if (mem.siteValid && now - num(mem.siteLast, -100) < 1.6 &&
        Number.isFinite(mem.siteX) && Number.isFinite(mem.siteY)) {
      const dx = mem.siteX - mem.px;
      const dy = mem.siteY - mem.py;
      d = Math.hypot(dx, dy);
      bearing = d > 0.001
        ? wrap(Math.atan2(dy, dx) / rad - mem.hEst)
        : 0;
      value = Math.max(0.1, num(mem.siteValue, 1));
    } else {
      mem.siteValid = false;
      return null;
    }

    pauseSearch();

    const homeD = beacon
      ? Math.max(0, Number(beacon.distance))
      : gpsBaseD;
    const remaining = clamp(6 - drillProgress, 0, 6);
    const need = returnEnergy(homeD, carried + 1) +
      remaining * mem.eDrill + 0.045;
    const safeTime = returnSeconds(homeD, carried + 1) +
      remaining + 15;

    if (carried >= mem.capacity || battery < need ||
        timeLeft < safeTime) {
      mem.siteValid = false;
      if (atBaseStable) return holdAtBase();
      return baseAction();
    }

    if (d <= 1.32) {
      const still = Math.abs(vActual) < 0.13 &&
        Math.max(Math.abs(wl), Math.abs(wr)) < 0.19;
      if (!still) return drive(0, 0, false);

      if (!mem.drillActive) {
        mem.drillActive = true;
        mem.drillStart = now;
        mem.drillX = num(mem.siteX, mem.px);
        mem.drillY = num(mem.siteY, mem.py);
      }
      return drive(0, 0, true);
    }

    const speed = d > 4 ? 0.66 : (d > 2 ? 0.40 : 0.22);
    return navigateRel(bearing, d, speed, 1.02);
  }

  function beginSearch(kind, cx, cy, hint) {
    return {
      kind: kind,
      hint: hint,
      cx: cx,
      cy: cy,
      index: 0,
      count: 18,
      radius: 14.5,
      start: now,
      activeTime: 0,
      budget: 145,
      spent: 0,
      lastOdo: num(mem.odo, 0)
    };
  }

  function searchDirective(s) {
    s.spent = num(s.spent, 0) +
      Math.max(0, num(mem.odo, 0) - num(s.lastOdo, mem.odo));
    s.lastOdo = num(mem.odo, 0);
    s.activeTime = num(s.activeTime, 0) + dt;

    if (s.spent > s.budget || s.activeTime > 430 ||
        s.index >= s.count) {
      return { failed: true };
    }

    let tries = 0;
    while (s.index < s.count && tries++ < s.count) {
      const angle = 360 * s.index / s.count;
      const tx = s.cx + s.radius * Math.cos(angle * rad);
      const ty = s.cy + s.radius * Math.sin(angle * rad);

      if (tx < 2 || tx > mem.mapSize - 2 ||
          ty < 2 || ty > mem.mapSize - 2 ||
          dist(mem.px, mem.py, tx, ty) < 2.65) {
        s.index++;
      } else {
        return { failed: false, x: tx, y: ty };
      }
    }

    return { failed: true };
  }

  function finishSearch() {
    if (!mem.search) return;
    const kind = mem.search.kind;
    if (kind === "hint") {
      const i = Math.floor(num(mem.search.hint, mem.activeHint));
      if (i >= 0 && mem.hints[i] && mem.hints[i].status === 0) {
        mem.hints[i].status = 2;
      }
      mem.activeHint = -1;
    } else {
      mem.freeIndex = num(mem.freeIndex, 0) + 1;
    }
    mem.search = null;
    mem.mode = "plan";
    resetNav();
  }

  function hintPlan(i) {
    const h = mem.hints[i];
    if (!h) return { need: Infinity, time: Infinity, score: -Infinity };

    const outD = dist(mem.px, mem.py, h.x, h.y);
    const homeD = dist(h.x, h.y, mem.baseX, mem.baseY);
    let searchRemain = 90;
    if (mem.search && mem.search.kind === "hint" &&
        Math.floor(num(mem.search.hint, -1)) === i) {
      searchRemain = Math.max(0,
        (mem.search.count - mem.search.index) * 5.1);
    }

    const need = returnEnergy(homeD, 1) +
      (outD + 0.75 * searchRemain) * mem.ePerM * 1.55 +
      6 * mem.eDrill + 0.035;
    const time = (outD + homeD + searchRemain) / 0.65 + 50;

    let cluster = 0;
    for (let j = 0; j < mem.hints.length; j++) {
      if (j === i) continue;
      const q = mem.hints[j];
      if (!q || q.status !== 0) continue;
      const dd = dist(h.x, h.y, q.x, q.y);
      if (dd < 34) cluster += q.v * (1 - dd / 34);
    }
    const effectiveValue = h.v + Math.min(h.v * 0.7, cluster * 0.14);
    const score = effectiveValue /
      Math.pow(Math.max(1, 42 + outD + 0.55 * homeD + 20), 0.9);

    return { need: need, time: time, score: score };
  }

  function pickHint(atHome) {
    let bestAffordable = -1, bestAffordableScore = -Infinity;
    let bestWait = -1, bestWaitScore = -Infinity;

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (!h || h.status !== 0 || now < num(h.skipUntil, 0)) continue;

      const p = hintPlan(i);
      if (p.time > timeLeft - 15 || p.need > 1.04) continue;

      if (p.need <= battery + 0.005) {
        if (p.score > bestAffordableScore) {
          bestAffordableScore = p.score;
          bestAffordable = i;
        }
      } else if (atHome && p.need <= battery + 0.12) {
        if (p.score > bestWaitScore) {
          bestWaitScore = p.score;
          bestWait = i;
        }
      }
    }

    if (bestAffordable >= 0) return bestAffordable;
    return bestWait;
  }

  function runHint(i) {
    const h = mem.hints[i];
    if (!h || h.status !== 0) {
      mem.activeHint = -1;
      mem.search = null;
      return null;
    }

    const p = hintPlan(i);
    if (p.time > timeLeft - 10) {
      h.status = 2;
      mem.activeHint = -1;
      mem.search = null;
      return null;
    }

    if (atBaseStable && p.need > battery + 0.005) {
      if (mem.chargeHint !== i) {
        mem.chargeHint = i;
        mem.chargeStart = now;
      }
      if (p.need <= battery + 0.12 &&
          now - num(mem.chargeStart, now) < 65) {
        return holdAtBase();
      }
      h.skipUntil = now + 100;
      mem.chargeStart = -1;
      mem.chargeHint = -1;
      mem.activeHint = -1;
      return null;
    }
    mem.chargeStart = -1;
    mem.chargeHint = -1;

    const d = dist(mem.px, mem.py, h.x, h.y);
    if (d > 5.2) {
      mem.mode = "hintTravel";
      return navigatePoint(h.x, h.y, 0.88, 4.0);
    }

    if (!mem.search || mem.search.kind !== "hint" ||
        Math.floor(num(mem.search.hint, -1)) !== i) {
      mem.search = beginSearch("hint", h.x, h.y, i);
    }

    mem.mode = "search";
    const q = searchDirective(mem.search);
    if (q.failed) {
      finishSearch();
      return null;
    }
    return navigatePoint(q.x, q.y, 0.78, 1.8);
  }

  const freeOffsets = [
    [0, 0], [25, 0], [0, 25], [-25, 0], [0, -25],
    [25, 25], [-25, 25], [-25, -25], [25, -25],
    [48, 0], [0, 48], [-48, 0], [0, -48]
  ];

  function runFree() {
    for (let tries = 0; tries < 5; tries++) {
      if (!mem.search || mem.search.kind !== "free") {
        const k = Math.floor(num(mem.freeIndex, 0));
        if (k >= freeOffsets.length) return null;

        let cx, cy;
        if (k === 0 &&
            num(mem.bestScience, 0) > num(mem.baseScience, 0) + 0.012 &&
            dist(mem.bestScienceX, mem.bestScienceY,
              mem.baseX, mem.baseY) < 45) {
          cx = num(mem.bestScienceX, mem.baseX);
          cy = num(mem.bestScienceY, mem.baseY);
        } else {
          const off = freeOffsets[k];
          cx = mem.baseX + off[0];
          cy = mem.baseY + off[1];
        }
        cx = clamp(cx, 3, mem.mapSize - 3);
        cy = clamp(cy, 3, mem.mapSize - 3);

        const outD = dist(mem.px, mem.py, cx, cy);
        const homeD = dist(cx, cy, mem.baseX, mem.baseY);
        const need = returnEnergy(homeD, 1) +
          (outD + 65) * mem.ePerM * 1.5 + 6 * mem.eDrill + 0.035;
        const timeNeed = (outD + homeD + 95) / 0.65 + 45;

        if (timeNeed > timeLeft - 12 || need > 1.03) {
          mem.freeIndex = k + 1;
          continue;
        }

        if (atBaseStable && need > battery + 0.01) {
          if (need <= battery + 0.12 &&
              now - num(mem.chargeStart, now) < 40) {
            if (mem.chargeStart < 0) mem.chargeStart = now;
            return holdAtBase();
          }
          mem.freeIndex = k + 1;
          continue;
        }

        if (!atBaseStable && need > battery + 0.02) {
          return baseAction();
        }

        mem.search = beginSearch("free", cx, cy, -1);
      }

      const s = mem.search;
      const dCenter = dist(mem.px, mem.py, s.cx, s.cy);
      if (dCenter > 5.2) {
        mem.mode = "freeTravel";
        return navigatePoint(s.cx, s.cy, 0.80, 4.0);
      }

      mem.mode = "search";
      const q = searchDirective(s);
      if (q.failed) {
        finishSearch();
        continue;
      }
      return navigatePoint(q.x, q.y, 0.76, 1.8);
    }

    return null;
  }

  if (mem.drillActive && !justSampled) {
    if (now - num(mem.drillStart, now) < 12 ||
        drillProgress >= 5.9) {
      return drive(0, 0, true);
    }
    mem.drillActive = false;
    mem.siteValid = false;
  }

  if (carried > 0) {
    return baseAction();
  }

  if (mem.mode === "return") {
    if (atBaseStable) {
      mem.mode = "plan";
      mem.returning = false;
      resetNav();
    } else {
      return baseAction();
    }
  }

  if (!atBaseStable &&
      (battery < returnEnergy(baseMetric, 0) + 0.075 ||
       timeLeft < returnSeconds(baseMetric, 0) + 18)) {
    return baseAction();
  }

  if (siteObj || (mem.siteValid &&
      now - num(mem.siteLast, -100) < 1.6)) {
    const out = siteAction();
    if (out) return out;
  }

  if (mem.navFailed) {
    mem.navFailed = false;
    resetNav();

    if (mem.mode === "return") {
      startRecovery(clearanceSide());
    } else if (mem.mode === "search" && mem.search) {
      mem.search.index = num(mem.search.index, 0) + 2;
      mem.search.lastOdo = num(mem.odo, 0);
      if (mem.search.index >= mem.search.count) finishSearch();
    } else if (mem.mode === "hintTravel" && mem.activeHint >= 0) {
      const h = mem.hints[mem.activeHint];
      if (h) h.status = 2;
      mem.activeHint = -1;
      mem.search = null;
    } else if (mem.mode === "freeTravel") {
      mem.freeIndex = num(mem.freeIndex, 0) + 1;
      mem.search = null;
    }
  }

  for (let attempt = 0; attempt < 7; attempt++) {
    let i = Math.floor(num(mem.activeHint, -1));
    if (i < 0 || !mem.hints[i] || mem.hints[i].status !== 0) {
      i = pickHint(atBaseStable);
      if (i >= 0) {
        mem.activeHint = i;
        mem.search = null;
      }
    }

    if (i >= 0 && mem.hints[i] && mem.hints[i].status === 0) {
      const out = runHint(i);
      if (out) return out;
      continue;
    }

    const freeOut = runFree();
    if (freeOut) return freeOut;
    break;
  }

  return holdAtBase();
}

function act(obs, mem) {
