    mem.routeMode = "";
    mem.mode = "plan";
    mem.chargeStart = -1;
    mem.chargeLast = num(obs && obs.battery, 0.8);
    mem.chargeLastTime = 0;

    mem.siteValid = false;
    mem.siteX = NaN;
    mem.siteY = NaN;
    mem.siteValue = 0;
    mem.siteLast = -100;

