  if (!Array.isArray(mem.rayTime)) mem.rayTime = new Array(9).fill(0);
  if (!Array.isArray(mem.rayHead)) mem.rayHead = new Array(9).fill(0);
  if (!Number.isFinite(mem.activeHint)) mem.activeHint = -1;
  if (!Number.isFinite(mem.ePerM)) mem.ePerM = 0.00085;
  if (!Number.isFinite(mem.eDrill)) mem.eDrill = 0.0032;

  const hasTimeLeft = obs && obs.timeLeft !== undefined &&
    obs.timeLeft !== null && Number.isFinite(Number(obs.timeLeft));
  const now = obs && Number.isFinite(Number(obs.t))
    ? Math.max(0, Number(obs.t))
    : Math.max(0, mem.totalSeconds - num(obs && obs.timeLeft, mem.totalSeconds));

  let dt = 0.1;
