    : Math.max(0, mem.totalSeconds - now);

  const rawH = wrap(num(obs.heading, 0));
  const wl = num(obs.wheelLeft, 0);
  const wr = num(obs.wheelRight, 0);
  const vActual = clamp((wl + wr) * 0.5, -3.2, 3.2);
  const yawActual = clamp((wr - wl) / 0.6, -8, 8);
  const gpsValid = Number.isFinite(Number(obs.x)) &&
    Number.isFinite(Number(obs.y));
