  let x = 0, y = 0, k = 0;
  do {
    x = 30 + Math.random() * 340;
    y = 30 + Math.random() * 340;
    k++;
  } while (hyp(x, y, px, py) < 40 && k < 40);
  return { x: x, y: y };
}

function act(obs, mem) {
  const out = { left: 0, right: 0, drill: false };
