    mem.base = { x: b.x, y: b.y };
    mem.cap = M.capacity || 5;
    mem.sites = (M.hints || []).map(h => ({ x: h.x, y: h.y, est: h.estimate || 0, done: false, fails: 0 }));
    mem.target = null;
    mem.mode = 'nav';
    mem.hoff = 0;
    mem.anchor = { x: obs.x, y: obs.y };
    mem.dirty = false;
    mem.sRef = { x: obs.x, y: obs.y, t: t };
