    mem.sRef = { x: px, y: py, t: t };
  } else if (t - mem.sRef.t > 6 && mem.lastV !== 0 && t > mem.backUntil && obs.battery !== 0) {
    // (lastV is from the previous tick)
  }
  if (mem.prevCmdV === undefined) mem.prevCmdV = 0;
  if (hyp(px, py, mem.sRef.x, mem.sRef.y) <= 1.0 && t - mem.sRef.t > 6 && mem.prevCmdV > 0.3 && t > mem.backUntil) {
    mem.backUntil = t + 2.0;
    mem.turnDir = Math.random() < 0.5 ? -1 : 1;
    mem.sRef = { x: px, y: py, t: t };
    if (mem.target && mem.target.kind === 'hint') {
      mem.sites[mem.target.idx].fails++;
      mem.target = null;
    } else if (mem.target && mem.target.kind === 'explore') {
      mem.target = null;
    }
  }

  // ---- bump: back off
  if (obs.bumped && t >= mem.backUntil) {
    mem.backUntil = t + 1.5;
    mem.turnDir = Math.random() < 0.5 ? -1 : 1;
  }
  if (t < mem.backUntil) {
    out.left = -0.4 - 0.2 * mem.turnDir;
    out.right = -0.4 + 0.2 * mem.turnDir;
    mem.prevCmdV = 0;
    return out;
  }

  // ---- drilling in progress
  if (mem.mode === 'drill') {
    const dr = obs.drilling || 0;
    if (dr >= 6) {
      mem.drillDone.push({ x: px, y: py });
