  } else if (obs.site && carried < mem.cap) {
    const a = (hdg + obs.site.bearing) * D2R;
    const sx = px + obs.site.distance * Math.cos(a);
    const sy = py + obs.site.distance * Math.sin(a);
    let near = false;
    for (const p of mem.drillDone) if (hyp(p.x, p.y, sx, sy) < 3) near = true;
    if (!near) T = { x: sx, y: sy, kind: 'site' };
  }

  if (!T) {
    // process current hint
    if (mem.target && mem.target.kind === 'hint') {
      const h = mem.target;
      const s = mem.sites[h.idx];
      if (s.done) {
        mem.target = null;
      } else if (h.phase === 'go') {
        const d = hyp(px, py, s.x, s.y);
        if (d < 4) {
          h.phase = 'search';
          h.wps = [];
          for (let k = 0; k < 6; k++) {
            const ang = k * 60 * D2R;
            h.wps.push({
              x: clamp(s.x + 12 * Math.cos(ang), 6, 394),
              y: clamp(s.y + 12 * Math.sin(ang), 6, 394)
            });
          }
          h.wi = 0;
          h.wt = t;
        } else if (t - h.t0 > d / 0.6 + 60) {
          s.fails++;
          mem.target = null;
        }
      }
      if (mem.target && h.phase === 'search') {
        const w = h.wps[h.wi];
        if (hyp(px, py, w.x, w.y) < 2.5 || t - h.wt > 25) {
          h.wi++;
          h.wt = t;
          if (h.wi >= h.wps.length) {
            s.done = true;
            mem.target = null;
          }
        }
      }
    }
    // pick a new hint if needed
    if (!mem.target || mem.target.kind === 'explore') {
      if (hasHints) {
        let best = -1, bs = -1;
        for (let i = 0; i < mem.sites.length; i++) {
          const s = mem.sites[i];
          if (s.done || s.fails >= 2) continue;
          const d1 = hyp(px, py, s.x, s.y);
          const d2 = hyp(s.x, s.y, mem.base.x, mem.base.y);
          const sc = (s.est + 0.5) / (d1 + 0.5 * d2 + 25);
          if (sc > bs) { bs = sc; best = i; }
        }
        if (best >= 0) mem.target = { kind: 'hint', idx: best, phase: 'go', t0: t };
      }
    }
    // explore if nothing else
    if (!mem.target) {
      const w = randWp(px, py);
      mem.target = { kind: 'explore', x: w.x, y: w.y, t0: t };
    }
    if (mem.target.kind === 'explore') {
      if (hyp(px, py, mem.target.x, mem.target.y) < 5 || t - mem.target.t0 > 60) {
        const w = randWp(px, py);
        mem.target = { kind: 'explore', x: w.x, y: w.y, t0: t };
      }
    }
    const tg = mem.target;
    if (tg.kind === 'hint') {
      const s = mem.sites[tg.idx];
      if (tg.phase === 'go') {
        T = { x: s.x, y: s.y, kind: 'hint' };
      } else {
        const w = tg.wps[tg.wi];
        T = { x: w.x, y: w.y, kind: 'search' };
      }
    } else {
      T = { x: tg.x, y: tg.y, kind: 'explore' };
    }
  }

  T.x = clamp(T.x, 6, 394);
  T.y = clamp(T.y, 6, 394);
  const dT = hyp(px, py, T.x, T.y);

