    const R = (rr(0) + rr(1) + rr(2) + rr(3)) / 4;
    const turn = Math.abs(L - R) > 1 ? clamp((L - R) / 6, -1, 1) : mem.turnDir;
    w += 0.5 * turn;
    v *= clamp(front / 5, 0.25, 1);
  }

  out.left = clamp(v - w, -1, 1);
  out.right = clamp(v + w, -1, 1);
  mem.prevCmdV = v;
  return out;
}

