    { x: c(hx + 12), y: c(hy) }, { x: c(hx - 12), y: c(hy) },
    { x: c(hx - 12), y: c(hy + 10) }, { x: c(hx + 12), y: c(hy + 10) }
  ];
}

function initMem(obs, mem) {
  const M = obs.mission || {};
