  mem.dirty = false;
  mem.lastGx = obs.x; mem.lastGy = obs.y; mem.gStill = 0;
  mem.dr = { x: obs.x, y: obs.y };
  mem.sref = { x: obs.x, y: obs.y, t: 0 };
  mem.lastV = 0;
