  const rightOpen = (rr(0) + rr(1) + rr(2)) / 3;
  if (front < 4 && d > 3) {
    if (now > mem.avoidUntil) mem.avoidDir = leftOpen >= rightOpen ? 1 : -1;
    mem.avoidUntil = now + 2.5;
    if (front < 2.5) { v = 0; w = 0.3 * mem.avoidDir; }
    else { v = Math.min(v, 0.2); w = clamp(w + 0.25 * mem.avoidDir, -0.3, 0.3); }
  }
  return { v: v, w: w };
}

function act(obs, mem) {
  const out = { left: 0, right: 0, drill: false };
  if (!mem.init) initMem(obs, mem);
  mem.tk = (mem.tk || 0) + 1;
  const now = typeof obs.t === 'number' ? obs.t : mem.tk * 0.1;
  const timeLeft = typeof obs.timeLeft === 'number' ? obs.timeLeft : 1200 - now;
  const battery = typeof obs.battery === 'number' ? obs.battery : 1;
  const carried = obs.carried || 0;
  const wl = obs.wheelLeft || 0, wr = obs.wheelRight || 0;
  const vW = (wl + wr) / 2;
  const hraw = typeof obs.heading === 'number' ? obs.heading : 0;

  // ---- GPS freeze detection and dead reckoning
  if (obs.x === mem.lastGx && obs.y === mem.lastGy) mem.gStill++;
  else { mem.gStill = 0; mem.lastGx = obs.x; mem.lastGy = obs.y; }
  if (mem.gStill === 0) { mem.dr.x = obs.x; mem.dr.y = obs.y; }
  else {
    const hh = (hraw + mem.bias) * D2R;
    mem.dr.x += vW * Math.cos(hh) * 0.1;
    mem.dr.y += vW * Math.sin(hh) * 0.1;
  }
  const frozen = mem.gStill > 25;
  const px = frozen ? mem.dr.x : obs.x;
  const py = frozen ? mem.dr.y : obs.y;

  // ---- compass bias correction using GPS course over straight runs
  const straight = wl > 0.2 && wr > 0.2 && Math.abs(wl - wr) < 0.1;
  if (!straight) mem.dirty = true;
  if (hyp(px, py, mem.anchor.x, mem.anchor.y) > 6) {
    if (!mem.dirty && !frozen) {
      const course = Math.atan2(py - mem.anchor.y, px - mem.anchor.x) / D2R;
      const diff = wrap(course - hraw);
      mem.bias = wrap(mem.bias + 0.3 * wrap(diff - mem.bias));
    }
    mem.anchor = { x: px, y: py };
    mem.dirty = false;
  }
  const hdg = wrap(hraw + mem.bias);
  const hr = hdg * D2R;

  // ---- stuck detection
  if (hyp(px, py, mem.sref.x, mem.sref.y) > 1.5) mem.sref = { x: px, y: py, t: now };
  if (mem.mode === 'nav' && Math.abs(mem.lastV) > 0.15 && now - mem.sref.t > 7) {
    failTarget(mem);
    startBack(mem, now, 2.5, px, py);
  }

  // ---- bump: back off
  if (obs.bumped && mem.mode === 'nav') {
    if (now - mem.bumpT > 30) mem.bumps = 0;
    mem.bumps++;
    mem.bumpT = now;
    if (mem.bumps >= 3) { failTarget(mem); mem.bumps = 0; }
    startBack(mem, now, 2.0, px, py);
  }

  // ---- backing off
  if (mem.mode === 'back') {
    if (now < mem.backUntil) {
      out.left = clamp(-0.3 - 0.2 * mem.turnDir, -1, 1);
      out.right = clamp(-0.3 + 0.2 * mem.turnDir, -1, 1);
      mem.lastV = 0;
      return out;
    }
    mem.mode = 'nav';
  }

  // ---- drilling
  if (mem.mode === 'drill') {
    const dr = obs.drilling || 0;
    if (dr >= 6) {
      mem.done.push({ x: px, y: py });
      for (const h of mem.hints) if (!h.done && hyp(h.x, h.y, px, py) < 12) h.done = true;
      mem.mode = 'nav'; mem.drillAnc = null; mem.siteT = null; mem.lastV = 0;
      return out;
    }
    if (now - mem.drillT0 > 25) {
      mem.bad.push({ x: px, y: py });
      mem.mode = 'nav'; mem.drillAnc = null; mem.lastV = 0;
      return out;
    }
    out.drill = true;
    const a = mem.drillAnc || { x: px, y: py };
    const fwd = (a.x - px) * Math.cos(hr) + (a.y - py) * Math.sin(hr);
    const pitch = typeof obs.pitch === 'number' ? obs.pitch : 0;
    const pos = fwd > 1.5 ? 0.2 * (fwd - 1.5) : (fwd < -1.5 ? 0.2 * (fwd + 1.5) : 0);
    const v = clamp(pos + 0.03 * pitch - 0.5 * vW, -0.2, 0.2);
    out.left = v; out.right = v;
    mem.lastV = 0;
    return out;
  }

  // ---- docking at base
  if (mem.mode === 'dock') {
    if (mem.dockT0 === null) mem.dockT0 = now;
    const waited = now - mem.dockT0;
    const dB2 = hyp(px, py, mem.base.x, mem.base.y);
    if (carried > 0 && !obs.docked && dB2 > 1.5 && waited < 30) {
      const c = steer(obs, mem, now, hdg, px, py, mem.base.x, mem.base.y, 0.15);
      out.left = clamp(c.v - c.w, -1, 1);
      out.right = clamp(c.v + c.w, -1, 1);
      mem.lastV = c.v;
      return out;
    }
    const leave = waited > 60 || (carried === 0 && (battery > 0.6 || (waited > 25 && timeLeft < 300)));
    if (leave) { mem.mode = 'nav'; mem.dockT0 = null; }
    mem.lastV = 0;
    return out;
  }

  // ---- navigation
  const dB = hyp(px, py, mem.base.x, mem.base.y);
  const hasHints = mem.hints.some(h => !h.done && h.fails < 2);
  const lowBat = battery < 0.22 + dB / 1500;
  const goHome = (carried > 0 && (carried >= mem.cap || !hasHints || timeLeft < dB / 0.7 + 60)) || lowBat;

  if (goHome && dB < 2.5) {
    mem.mode = 'dock'; mem.dockT0 = null; mem.lastV = 0;
    return out;
  }

  // site in sensor range
  let siteT = null;
  if (!goHome && obs.site && carried < mem.cap && obs.site.distance <= 8.5) {
    const a = (hdg + obs.site.bearing) * D2R;
    const sx = px + obs.site.distance * Math.cos(a);
    const sy = py + obs.site.distance * Math.sin(a);
    if (!nearAny(mem.done, sx, sy, 4) && !nearAny(mem.bad, sx, sy, 4)) siteT = { x: sx, y: sy };
    if (siteT && obs.site.distance <= 1.4) {
      mem.mode = 'drill';
      mem.drillT0 = now;
      mem.drillAnc = { x: px, y: py };
      mem.lastV = 0;
      out.drill = true;
      return out;
    }
  }

  let T = null, kind = 'explore';
  if (goHome) {
    if (mem.act) mem.act.phaseT0 = now, mem.act.wpT0 = now;
    T = { x: mem.base.x, y: mem.base.y };
    kind = 'base';
    mem.siteT = null;
  } else if (siteT) {
    T = siteT; kind = 'site'; mem.siteT = siteT;
  } else {
    mem.siteT = null;
    if (mem.act && mem.hints[mem.act.idx].done) mem.act = null;
    if (!mem.act && hasHints) pickHint(mem, px, py, now);
    if (mem.act) {
      const A = mem.act, h = mem.hints[A.idx];
      if (A.phase === 'go') {
        const d = hyp(px, py, h.x, h.y);
        if (d < 4) {
          A.phase = 'search';
          A.wps = searchWps(h.x, h.y);
          A.wi = 0;
          A.wpT0 = now;
        } else if (now - A.phaseT0 > d / 0.4 + 60) {
          h.fails++;
          mem.act = null;
        }
      }
      if (mem.act && A.phase === 'search') {
        const w = A.wps[A.wi];
        if (hyp(px, py, w.x, w.y) < 2.5 || now - A.wpT0 > 30) {
          A.wi++;
          A.wpT0 = now;
          if (A.wi >= A.wps.length) { h.done = true; mem.act = null; }
        }
      }
      if (mem.act) {
        T = A.phase === 'go' ? { x: h.x, y: h.y } : A.wps[A.wi];
        kind = A.phase;
      }
    }
    if (!T) {
      if (!mem.explore || hyp(px, py, mem.explore.x, mem.explore.y) < 6 || now - mem.explore.t0 > 90) {
        let x = 200, y = 200;
        for (let k = 0; k < 30; k++) {
          x = 25 + Math.random() * 350;
          y = 25 + Math.random() * 350;
          if (hyp(x, y, px, py) > 60) break;
        }
        mem.explore = { x: x, y: y, t0: now };
      }
      T = { x: mem.explore.x, y: mem.explore.y };
      kind = 'explore';
    }
  }

  const vmax = kind === 'base' ? 0.45 : (kind === 'site' ? 0.3 : 0.4);
  const c = steer(obs, mem, now, hdg, px, py, T.x, T.y, vmax);
  out.left = clamp(c.v - c.w, -1, 1);
  out.right = clamp(c.v + c.w, -1, 1);
  mem.lastV = c.v;
  return out;
}

const D2R = Math.PI / 180, R2D = 180 / Math.PI;
const GN = 200, GC = 2, OCC = 1.5;
const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];

function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function hyp(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function cX(x) { return clamp(Math.floor(x / GC), 0, GN - 1); }
function cY(y) { return clamp(Math.floor(y / GC), 0, GN - 1); }
function nearIdx(list, x, y, r) {
  for (let i = 0; i < list.length; i++) if (hyp(list[i].x, list[i].y, x, y) < r) return i;
  return -1;
}
function ringWps(h, r, n, ph) {
  const o = [];
  for (let k = 0; k < n; k++) {
    const a = (k * 360 / n + ph) * D2R;
    o.push({ x: clamp(h.x + r * Math.cos(a), 4, 396), y: clamp(h.y + r * Math.sin(a), 4, 396) });
  }
  return o;
}

// ---- binary heap on JS arrays
function hpush(hk, hv, k, v) {
  let i = hk.length;
  hk.push(k); hv.push(v);
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (hk[p] <= k) break;
    hk[i] = hk[p]; hv[i] = hv[p]; i = p;
  }
  hk[i] = k; hv[i] = v;
}
function hpop(hk, hv) {
  const top = hv[0];
  const lk = hk.pop(), lv = hv.pop();
  const n = hk.length;
  if (n > 0) {
    let i = 0;
    for (;;) {
      let c = 2 * i + 1;
      if (c >= n) break;
      if (c + 1 < n && hk[c + 1] < hk[c]) c++;
      if (hk[c] >= lk) break;
      hk[i] = hk[c]; hv[i] = hv[c]; i = c;
    }
    hk[i] = lk; hv[i] = lv;
  }
  return top;
}

function hh(x1, y1, x2, y2) {
  const dx = Math.abs(x1 - x2), dy = Math.abs(y1 - y2);
  return Math.max(dx, dy) + 0.414 * Math.min(dx, dy);
}
function occNear(L, x, y) {
  if (x > 0 && L[y * GN + x - 1] >= OCC) return true;
  if (x < GN - 1 && L[y * GN + x + 1] >= OCC) return true;
  if (y > 0 && L[(y - 1) * GN + x] >= OCC) return true;
  if (y < GN - 1 && L[(y + 1) * GN + x] >= OCC) return true;
  return false;
}

// A* on the occupancy grid; returns list of world points (excluding start) or null
function plan(mem, sx, sy, gx, gy) {
  const L = mem.L;
  const sxc = cX(sx), syc = cY(sy), gxc = cX(gx), gyc = cY(gy);
  const start = syc * GN + sxc, goal = gyc * GN + gxc;
  if (start === goal) return [];
  const N = GN * GN;
  const g = new Float32Array(N).fill(1e9);
  const par = new Int32Array(N).fill(-1);
  const closed = new Uint8Array(N);
  const hk = [], hv = [];
  g[start] = 0;
  hpush(hk, hv, hh(sxc, syc, gxc, gyc), start);
  let exp = 0, found = false;
  while (hk.length > 0 && exp < 25000) {
    const u = hpop(hk, hv);
    if (closed[u]) continue;
    closed[u] = 1; exp++;
    if (u === goal) { found = true; break; }
    const ux = u % GN, uy = (u - ux) / GN;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        const nx = ux + dx, ny = uy + dy;
        if (nx < 0 || ny < 0 || nx >= GN || ny >= GN) continue;
        const v = ny * GN + nx;
        if (closed[v]) continue;
        if (v !== goal && L[v] >= OCC) continue;
        let c = (dx && dy) ? 1.414 : 1;
        if (occNear(L, nx, ny)) c += 1.5;
        const ng = g[u] + c;
        if (ng < g[v]) {
          g[v] = ng; par[v] = u;
          hpush(hk, hv, ng + hh(nx, ny, gxc, gyc), v);
        }
      }
    }
  }
  if (!found) return null;
  const pts = [];
  let c = goal;
  while (c !== start && c !== -1) {
    pts.push({ x: ((c % GN) + 0.5) * GC, y: (Math.floor(c / GN) + 0.5) * GC });
    c = par[c];
  }
  pts.reverse();
  return pts;
}

function mapUpdate(L, px, py, hdg, rays) {
  for (let j = 0; j < 9; j++) {
    const v = rays[j];
    const r = (typeof v === 'number' && isFinite(v)) ? v : 15;
    const hit = r < 14.5;
    const maxR = hit ? r : 15;
    const a = (hdg + ANG[j]) * D2R;
    const ca = Math.cos(a), sa = Math.sin(a);
    for (let s = 1.0; s < maxR - 0.5; s += 1.0) {
      const k = cY(py + sa * s) * GN + cX(px + ca * s);
      const nv = L[k] - 0.5;
      L[k] = nv < -3 ? -3 : nv;
    }
    if (hit && r > 1.0) {
      const k = cY(py + sa * r) * GN + cX(px + ca * r);
      const nv = L[k] + 1.0;
      L[k] = nv > 3 ? 3 : nv;
    }
  }
}

function pickHint(mem, px, py) {
  let best = -1, bs = -1;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.done || h.fails >= 2) continue;
    const d1 = hyp(px, py, h.x, h.y);
    const d2 = hyp(h.x, h.y, mem.base.x, mem.base.y);
    const sc = (h.est + 0.5) / (d1 + 0.6 * d2 + 25);
    if (sc > bs) { bs = sc; best = i; }
  }
  return best;
}

function pickExplore(mem, px, py) {
  let best = { x: 200, y: 200 }, bs = -1e9;
  for (let k = 0; k < 8; k++) {
    const x = 20 + Math.random() * 360, y = 20 + Math.random() * 360;
    let dmin = 200;
    for (const v of mem.visited) {
      const d = hyp(x, y, v.x, v.y);
      if (d < dmin) dmin = d;
    }
    const sc = Math.min(dmin, 120) - 0.25 * hyp(x, y, px, py);
    if (sc > bs) { bs = sc; best = { x: x, y: y }; }
  }
  return best;
}

function onStuck(mem, px, py, hdg, t, bumped) {
  mem.mode = 'back';
  mem.backUntil = t + 1.8;
  mem.td = Math.random() < 0.5 ? -1 : 1;
  mem.stRef = { x: px, y: py, t: t };
  mem.replan = true;
  mem.path = null;
  if (bumped) {
    const a = hdg * D2R;
    const k = cY(py + 1.5 * Math.sin(a)) * GN + cX(px + 1.5 * Math.cos(a));
    mem.L[k] = 3;
  }
  const task = mem.task;
  if (task && task.kind === 'hint') {
    task.stuck = (task.stuck || 0) + 1;
    if (task.stuck >= 3) { mem.hints[task.idx].fails = 2; mem.task = null; }
  } else if (task && task.kind === 'explore') {
    task.stuck = (task.stuck || 0) + 1;
    if (task.stuck >= 2) mem.task = null;
  }
  if (mem.siteGoal) {
    mem.bad.push({ x: mem.siteGoal.x, y: mem.siteGoal.y });
    mem.siteGoal = null;
  }
}

function drive(mem, px, py, hdg, tgt, vmax, stopR, rays, t) {
  const dG = hyp(px, py, tgt.x, tgt.y);
  if (dG < stopR) { mem.lastV = 0; mem.lastW = 0; return { left: 0, right: 0 }; }
  if (!mem.path || mem.replan || hyp(mem.pgx, mem.pgy, tgt.x, tgt.y) > 3 || t - mem.planT > 5) {
    const P = plan(mem, px, py, tgt.x, tgt.y);
    mem.path = (P || []).concat([{ x: tgt.x, y: tgt.y }]);
    mem.pi = 0; mem.pgx = tgt.x; mem.pgy = tgt.y; mem.planT = t; mem.replan = false;
  }
  const P = mem.path;
  while (mem.pi < P.length - 1 && hyp(px, py, P[mem.pi].x, P[mem.pi].y) < 1.8) mem.pi++;
  const aim = P[mem.pi];
  if (mem.pi < P.length - 1 && mem.L[cY(aim.y) * GN + cX(aim.x)] >= OCC && t - mem.planT > 1) mem.replan = true;

  const rd = j => { const v = rays[j]; return (typeof v === 'number' && isFinite(v)) ? v : 15; };
  const want = Math.atan2(aim.y - py, aim.x - px) * R2D;
  const e = wrap(want - hdg);
  let w = clamp(0.35 * e * D2R, -0.45, 0.45);
  if (Math.abs(e) > 5 && Math.abs(w) < 0.1) w = 0.1 * (e > 0 ? 1 : -1);
  const f = clamp(1 - Math.abs(e) / 55, 0, 1);
  let v = vmax * f;
  if (dG < 4) v = Math.min(v, 0.12 + 0.1 * dG);
  const fr = Math.min(rd(3), rd(4), rd(5));
  if (fr < 1.2) {
    const side = (rd(6) + rd(7) + rd(8)) - (rd(0) + rd(1) + rd(2));
    v = Math.min(v, 0.1);
    w += 0.35 * (side >= 0 ? 1 : -1);
  }
  w = clamp(w, -0.6, 0.6);
  mem.lastV = v; mem.lastW = w;
  return { left: clamp(v - w, -1, 1), right: clamp(v + w, -1, 1) };
}

function init(obs, mem) {
  const M = obs.mission || {};
  const b = M.base || { x: obs.x, y: obs.y };
  mem.base = { x: b.x, y: b.y };
  mem.cap = M.capacity || 5;
  mem.hints = (M.hints || []).map(h => ({ x: h.x, y: h.y, est: h.estimate || 0, fails: 0, done: false }));
  mem.L = new Float32Array(GN * GN);
  mem.done = []; mem.bad = []; mem.tries = []; mem.visited = [];
  mem.mode = 'nav'; mem.task = null;
  mem.path = null; mem.pi = 0; mem.pgx = 0; mem.pgy = 0; mem.planT = -99; mem.replan = true;
  mem.bias = 0; mem.anc = { x: obs.x, y: obs.y }; mem.straight = false;
  mem.dr = { x: obs.x, y: obs.y }; mem.gStill = 0; mem.lastGx = obs.x; mem.lastGy = obs.y;
  mem.lastV = 0; mem.lastW = 0;
  mem.stRef = { x: obs.x, y: obs.y, t: 0 };
  mem.backUntil = -1; mem.td = 1;
  mem.dockT0 = null; mem.charge = false; mem.homeBlock = 0;
  mem.drillT0 = 0; mem.drillAnc = null; mem.drillCarried = 0;
  mem.pending = null; mem.siteGoal = null; mem.siteSeen = -99;
  mem.lastVisit = -99; mem.dyn = 0;
  mem.init = true;
}

function act(obs, mem) {
  const out = { left: 0, right: 0, drill: false };
  if (!mem.init) init(obs, mem);
  mem.tk = (mem.tk || 0) + 1;
  const t = typeof obs.t === 'number' ? obs.t : mem.tk * 0.1;
  const timeLeft = typeof obs.timeLeft === 'number' ? obs.timeLeft : 1200 - t;
  const bat = typeof obs.battery === 'number' ? obs.battery : 1;
  const carried = obs.carried || 0;
  const wl = typeof obs.wheelLeft === 'number' ? obs.wheelLeft : 0;
  const wr = typeof obs.wheelRight === 'number' ? obs.wheelRight : 0;
  const vW = (wl + wr) / 2;
  const hraw = typeof obs.heading === 'number' ? obs.heading : 0;
  const pitch = typeof obs.pitch === 'number' ? obs.pitch : 0;
  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  const science = typeof obs.science === 'number' ? obs.science : 0;

  const pV = mem.lastV || 0, pW = mem.lastW || 0;
  mem.lastV = 0; mem.lastW = 0;

  // ---- localisation: GPS with dead reckoning fallback
  if (obs.x === mem.lastGx && obs.y === mem.lastGy) mem.gStill++;
  else { mem.gStill = 0; mem.lastGx = obs.x; mem.lastGy = obs.y; }
  if (mem.gStill === 0) { mem.dr.x = obs.x; mem.dr.y = obs.y; }
  else {
    const hp = wrap(hraw + mem.bias) * D2R;
    mem.dr.x += vW * Math.cos(hp) * 0.1;
    mem.dr.y += vW * Math.sin(hp) * 0.1;
  }
  const frozen = mem.gStill > 25;
  const px = frozen ? mem.dr.x : obs.x;
  const py = frozen ? mem.dr.y : obs.y;

  // ---- compass bias from GPS course over straight forward runs
  if (!(pV > 0.25 && Math.abs(pW) < 0.03)) mem.straight = false;
  if (hyp(px, py, mem.anc.x, mem.anc.y) > 4) {
    if (mem.straight && !frozen) {
      const course = Math.atan2(py - mem.anc.y, px - mem.anc.x) * R2D;
      const diff = wrap(course - (hraw + mem.bias));
      mem.bias = wrap(mem.bias + 0.3 * diff);
    }
    mem.anc = { x: px, y: py };
    mem.straight = true;
  }
  const hdg = wrap(hraw + mem.bias);
  const dBase = hyp(px, py, mem.base.x, mem.base.y);

  mapUpdate(mem.L, px, py, hdg, rays);

  if (t - mem.lastVisit > 20) { mem.lastVisit = t; mem.visited.push({ x: px, y: py }); }

  // ---- stuck / bump detection
  if (hyp(px, py, mem.stRef.x, mem.stRef.y) > 1.0) mem.stRef = { x: px, y: py, t: t };
  if (mem.mode === 'nav') {
    if (obs.bumped) onStuck(mem, px, py, hdg, t, true);
    else if (pV > 0.25 && t - mem.stRef.t > 8) onStuck(mem, px, py, hdg, t, false);
  }

  // ---- backing off
  if (mem.mode === 'back') {
    if (t < mem.backUntil) {
      out.left = -0.4 - 0.25 * mem.td;
      out.right = -0.4 + 0.25 * mem.td;
      mem.lastV = -0.4; mem.lastW = 0;
      return out;
    }
    mem.mode = 'nav';
  }

  // ---- drilling
  if (mem.mode === 'drill') {
    const dr = obs.drilling || 0;
    const anc = mem.drillAnc;
    if (dr >= 6 || t - mem.drillT0 > 14) {
      if (dr >= 6) {
        mem.done.push({ x: anc.x, y: anc.y });
        mem.pending = {
          x: anc.x, y: anc.y, c: mem.drillCarried, t: t,
          idx: (mem.task && mem.task.kind === 'hint') ? mem.task.idx : -1
        };
      } else {
        mem.bad.push({ x: anc.x, y: anc.y });
      }
      mem.mode = 'nav';
      return out;
    }
    out.drill = true;
    const hd = hdg * D2R;
    const f = (px - anc.x) * Math.cos(hd) + (py - anc.y) * Math.sin(hd);
    const pos = f > 0.3 ? -0.12 : (f < -0.3 ? 0.12 : 0);
    const u = clamp(0.012 * pitch - 0.6 * vW + pos, -0.25, 0.25);
    out.left = u; out.right = u;
    return out;
  }

  // ---- docking at base
  if (mem.mode === 'dock') {
    if (mem.dockT0 === null) mem.dockT0 = t;
    const waited = t - mem.dockT0;
    const wait = carried > 0 ? waited < 20 : (mem.charge && bat < 0.7 && waited < 30);
    if (wait) {
      if (!obs.docked && carried > 0 && dBase > 1.2 && waited > 3) {
        const o = drive(mem, px, py, hdg, mem.base, 0.2, 0.8, rays, t);
        out.left = o.left; out.right = o.right;
      }
      return out;
    }
    mem.mode = 'nav'; mem.dockT0 = null; mem.task = null; mem.path = null; mem.replan = true;
    mem.charge = false;
    if (carried > 0) mem.homeBlock = t + 60;
  }

  // ---- resolve finished drill: did the sample register?
  if (mem.pending && t - mem.pending.t > 1.5) {
    const p = mem.pending;
    mem.pending = null;
    if (carried > p.c) {
      if (p.idx >= 0) mem.hints[p.idx].done = true;
      for (const h of mem.hints) if (hyp(h.x, h.y, p.x, p.y) < 12) h.done = true;
    } else {
      mem.done = mem.done.filter(q => hyp(q.x, q.y, p.x, p.y) > 0.01);
      const i = nearIdx(mem.tries, p.x, p.y, 3);
      if (i >= 0) {
        mem.tries[i].n++;
        if (mem.tries[i].n >= 2) mem.bad.push({ x: p.x, y: p.y });
      } else {
        mem.tries.push({ x: p.x, y: p.y, n: 1 });
      }
    }
  }

  // ---- go home decision
  const openHints = mem.hints.some(h => !h.done && h.fails < 2);
  const reserve = 0.05 + 0.0022 * dBase;
  const homeOK = t >= mem.homeBlock;
  let goHome = false, charge = false;
  if (carried > 0 && homeOK) {
    goHome = carried >= mem.cap || (carried >= 2 && dBase < 20) || !openHints ||
      bat < reserve + 0.08 || timeLeft < dBase / 0.4 + 40;
  }
  if (!goHome && carried === 0 && homeOK && bat < 0.25 && bat > reserve + 0.03 && timeLeft > 200) {
    goHome = true; charge = true;
  }
  if (goHome && dBase < 2.2) {
    mem.mode = 'dock'; mem.dockT0 = null; mem.charge = charge;
    return out;
  }

  // ---- opportunistic site from sensor
  const site = obs.site;
  if (!goHome && site && carried < mem.cap && typeof site.distance === 'number' && site.distance <= 8.5) {
    const a = (hdg + (site.bearing || 0)) * D2R;
    const sx = px + site.distance * Math.cos(a), sy = py + site.distance * Math.sin(a);
    if (nearIdx(mem.done, sx, sy, 3) < 0 && nearIdx(mem.bad, sx, sy, 3) < 0) {
      mem.siteGoal = { x: sx, y: sy };
      mem.siteSeen = t;
      if (site.distance <= 1.2 || hyp(px, py, sx, sy) < 0.6) {
        mem.mode = 'drill'; mem.drillT0 = t;
        mem.drillAnc = { x: px, y: py };
        mem.drillCarried = carried;
        mem.siteGoal = null;
        out.drill = true;
        return out;
      }
    }
  }
  if (mem.siteGoal && t - mem.siteSeen > 3) mem.siteGoal = null;

  // ---- choose target
  let tgt = null, vmax = 0.6, stopR = 1.0;
  if (goHome) {
    mem.task = null;
    tgt = mem.base; vmax = 0.5; stopR = 0;
  } else if (mem.siteGoal) {
    tgt = mem.siteGoal; vmax = 0.3; stopR = 0.3;
  } else {
    if (mem.task && mem.task.kind === 'hint' && mem.hints[mem.task.idx].done) mem.task = null;
    if (!mem.task) {
      const idx = pickHint(mem, px, py);
      if (idx >= 0) {
        mem.task = { kind: 'hint', idx: idx, phase: 'go', t0: t, wps: null, wi: 0, wt: t, ring: 1, sci: 0 };
      } else {
        const e = pickExplore(mem, px, py);
        mem.task = { kind: 'explore', x: e.x, y: e.y, t0: t };
      }
      mem.replan = true;
    }
    const task = mem.task;
    if (task.kind === 'explore' && science > 0.8 && mem.dyn < 6 &&
        !mem.hints.some(h => !h.done && hyp(h.x, h.y, px, py) < 10)) {
      mem.dyn++;
      mem.hints.push({ x: px, y: py, est: 0.5, fails: 0, done: false });
      const hi = mem.hints.length - 1;
      mem.task = {
        kind: 'hint', idx: hi, phase: 'search', t0: t,
        wps: [{ x: px, y: py }].concat(ringWps({ x: px, y: py }, 8, 6, 0)),
        wi: 0, wt: t, ring: 1, sci: 0
      };
      mem.replan = true;
    }
    if (mem.task && mem.task.kind === 'hint') {
      const ht = mem.task;
      const h = mem.hints[ht.idx];
      if (ht.phase === 'go') {
        const d = hyp(px, py, h.x, h.y);
        if (d < 3.5) {
          ht.phase = 'search';
          ht.wps = [{ x: h.x, y: h.y }].concat(ringWps(h, 8, 6, 0));
          ht.wi = 0; ht.wt = t; ht.sci = 0;
          mem.replan = true;
        } else if (t - ht.t0 > d / 0.3 + 60) {
          h.fails = 2; mem.task = null; mem.replan = true;
        }
      }
      if (mem.task && ht.phase === 'search') {
        ht.sci = Math.max(ht.sci, science);
        const w = ht.wps[ht.wi];
        if (hyp(px, py, w.x, w.y) < 2 || t - ht.wt > 35) {
          ht.wi++; ht.wt = t; mem.replan = true;
          if (ht.wi >= ht.wps.length) {
            if (ht.ring === 1 && ht.sci > 0.3 && timeLeft > 300) {
              ht.ring = 2; ht.wps = ringWps(h, 16, 8, 22); ht.wi = 0;
            } else {
              h.done = true; mem.task = null;
            }
          }
        }
      }
      if (mem.task) {
        if (ht.phase === 'go') { tgt = { x: h.x, y: h.y }; vmax = 0.6; stopR = 0.5; }
        else { tgt = ht.wps[ht.wi]; vmax = 0.45; stopR = 0.5; }
      }
    } else if (mem.task && mem.task.kind === 'explore') {
      const ex = mem.task;
      if (hyp(px, py, ex.x, ex.y) < 4 || t - ex.t0 > 120) {
        mem.task = null;
      } else {
        tgt = { x: ex.x, y: ex.y }; vmax = 0.6; stopR = 1.0;
      }
    }
  }

  if (!tgt) { mem.lastV = 0; mem.lastW = 0; return out; }
  const o = drive(mem, px, py, hdg, tgt, vmax, stopR, rays, t);
  out.left = o.left; out.right = o.right;
  return out;
}

const D2R = Math.PI / 180, R2D = 180 / Math.PI;
const GN = 200, GC = 2, OCC = 1.5;
const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];

function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function hyp(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function num(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : d; }
function ci(v) { return clamp(Math.floor(v / GC), 0, GN - 1); }
function nearL(list, x, y, r) {
  for (let i = 0; i < list.length; i++) if (hyp(list[i].x, list[i].y, x, y) < r) return true;
  return false;
}
function ringWps(cx, cy, r, n, ph) {
  const o = [];
  for (let k = 0; k < n; k++) {
    const a = (k * 360 / n + ph) * D2R;
    o.push({ x: clamp(cx + r * Math.cos(a), 4, 396), y: clamp(cy + r * Math.sin(a), 4, 396) });
  }
  return o;
}

// ---- binary heap
function hpush(hk, hv, k, v) {
  let i = hk.length;
  hk.push(k); hv.push(v);
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (hk[p] <= k) break;
    hk[i] = hk[p]; hv[i] = hv[p]; i = p;
  }
  hk[i] = k; hv[i] = v;
}
function hpop(hk, hv) {
  const top = hv[0];
  const lk = hk.pop(), lv = hv.pop();
  const n = hk.length;
  if (n > 0) {
    let i = 0;
    for (;;) {
      let c = 2 * i + 1;
      if (c >= n) break;
      if (c + 1 < n && hk[c + 1] < hk[c]) c++;
      if (hk[c] >= lk) break;
      hk[i] = hk[c]; hv[i] = hv[c]; i = c;
    }
    hk[i] = lk; hv[i] = lv;
  }
  return top;
}

function nearOcc(L, x, y) {
  if (x > 0 && L[y * GN + x - 1] >= OCC) return true;
  if (x < GN - 1 && L[y * GN + x + 1] >= OCC) return true;
  if (y > 0 && L[(y - 1) * GN + x] >= OCC) return true;
  if (y < GN - 1 && L[(y + 1) * GN + x] >= OCC) return true;
  return false;
}

// A* on occupancy grid; returns world points (excluding start) or null
function plan(mem, sx, sy, gx, gy) {
  const L = mem.L;
  const s = ci(sy) * GN + ci(sx);
  const g = ci(gy) * GN + ci(gx);
  if (s === g) return [];
  const N = GN * GN;
  const gc = new Float32Array(N).fill(1e9);
  const par = new Int32Array(N).fill(-1);
  const closed = new Uint8Array(N);
  const gxc = g % GN, gyc = (g - gxc) / GN;
  const hk = [], hv = [];
  gc[s] = 0;
  hpush(hk, hv, 0, s);
  let found = false, exp = 0;
  while (hk.length > 0 && exp < 15000) {
    const u = hpop(hk, hv);
    if (closed[u]) continue;
    closed[u] = 1; exp++;
    if (u === g) { found = true; break; }
    const ux = u % GN, uy = (u - ux) / GN;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        const nx = ux + dx, ny = uy + dy;
        if (nx < 0 || ny < 0 || nx >= GN || ny >= GN) continue;
        const v = ny * GN + nx;
        if (closed[v]) continue;
        if (v !== g && L[v] >= OCC) continue;
        let c = (dx && dy) ? 1.414 : 1;
        if (nearOcc(L, nx, ny)) c += 1.0;
        const ng = gc[u] + c;
        if (ng < gc[v]) {
          gc[v] = ng; par[v] = u;
          const ax = Math.abs(nx - gxc), ay = Math.abs(ny - gyc);
          hpush(hk, hv, ng + Math.max(ax, ay) + 0.414 * Math.min(ax, ay), v);
        }
      }
    }
  }
  if (!found) return null;
  const pts = [];
  let c = g;
  while (c !== s && c !== -1) {
    pts.push({ x: ((c % GN) + 0.5) * GC, y: (Math.floor(c / GN) + 0.5) * GC });
    c = par[c];
  }
  pts.reverse();
  return pts;
}

function mapUpdate(L, px, py, hdg, rays) {
  for (let j = 0; j < 9; j++) {
    const r0 = num(rays[j], 15);
    const hit = r0 < 14.5;
    const r = clamp(r0, 0, 15);
    const a = (hdg + ANG[j]) * D2R;
    const ca = Math.cos(a), sa = Math.sin(a);
    for (let s = 1.0; s < r - 0.5; s += 1.0) {
      const k = ci(py + sa * s) * GN + ci(px + ca * s);
      const nv = L[k] - 0.4;
      L[k] = nv < -2 ? -2 : nv;
    }
    if (hit && r > 1.0) {
      const k = ci(py + sa * r) * GN + ci(px + ca * r);
      const nv = L[k] + 1.0;
      L[k] = nv > 3 ? 3 : nv;
    }
  }
}

function pickHint(mem, px, py) {
  let best = -1, bs = -1;
  const b = mem.base;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.done || h.fails >= 2) continue;
    const sc = (h.est + 0.5) / (hyp(px, py, h.x, h.y) + 0.5 * hyp(h.x, h.y, b.x, b.y) + 30);
    if (sc > bs) { bs = sc; best = i; }
  }
  return best;
}

function nearHint(mem, x, y, r) {
  for (const h of mem.hints) if (hyp(h.x, h.y, x, y) < r) return true;
  return false;
}

function pickExplore(mem, px, py) {
  let best = { x: 200, y: 200 }, bs = -1e9;
  for (let k = 0; k < 8; k++) {
    const x = 20 + Math.random() * 360, y = 20 + Math.random() * 360;
    let dm = 150;
    for (const v of mem.visited) {
      const d = hyp(x, y, v.x, v.y);
      if (d < dm) dm = d;
    }
    const sc = dm - 0.25 * hyp(x, y, px, py);
    if (sc > bs) { bs = sc; best = { x: x, y: y }; }
  }
  return best;
}

function failTarget(mem, t) {
  if (mem.siteAct) { mem.bad.push({ x: mem.siteAct.x, y: mem.siteAct.y }); mem.siteAct = null; }
  const k = mem.task;
  if (k) {
    if (k.kind === 'hint') {
      if (k.phase === 'go') { mem.hints[k.idx].fails++; mem.task = null; }
      else {
        k.wi++; k.wT = t;
        if (k.wi >= k.wps.length) { mem.hints[k.idx].done = true; mem.task = null; }
      }
    } else {
      mem.task = null;
    }
  }
  mem.path = null; mem.replan = true;
}

function startBack(mem, t, px, py, hr, hit, fail) {
  mem.mode = 'back';
  mem.backT = t + 2.0;
  mem.td = Math.random() < 0.5 ? -1 : 1;
  if (hit) {
    const ax = px + 1.5 * Math.cos(hr), ay = py + 1.5 * Math.sin(hr);
    mem.L[ci(ay) * GN + ci(ax)] = 3;
  }
  mem.path = null; mem.replan = true;
  mem.stT = t; mem.stRef = { x: px, y: py };
  if (fail) failTarget(mem, t);
}

function followPath(mem, px, py, t, T) {
  let need = !mem.path || mem.replan || hyp(mem.pgx, mem.pgy, T.x, T.y) > 2.5 || t - mem.planT > 8;
  if (!need && mem.pi < mem.path.length - 1) {
    const a = mem.path[mem.pi];
    if (t - mem.planT > 2 && mem.L[ci(a.y) * GN + ci(a.x)] >= OCC) need = true;
  }
  if (need) {
    const P = plan(mem, px, py, T.x, T.y);
    mem.path = P ? P.concat([{ x: T.x, y: T.y }]) : [{ x: T.x, y: T.y }];
    mem.pi = 0; mem.pgx = T.x; mem.pgy = T.y; mem.planT = t; mem.replan = false;
    mem.ei = 0;
  }
  const P = mem.path;
  while (mem.pi < P.length - 1 && hyp(px, py, P[mem.pi].x, P[mem.pi].y) < 2.0) mem.pi++;
  return P[mem.pi];
}

function steerTo(mem, px, py, hdg, ax, ay, vmax, rays, t) {
  const e = wrap(Math.atan2(ay - py, ax - px) * R2D - hdg);
  const ae = Math.abs(e);
  if (ae < 30) mem.ei = clamp(mem.ei + e * 0.1, -40, 40);
  else mem.ei *= 0.9;
  let w = 0.0045 * e + 0.003 * mem.ei;
  if (ae > 6 && Math.abs(w) < 0.06) w = 0.06 * (e > 0 ? 1 : -1);
  let v = vmax * clamp(1 - ae / 60, 0, 1);
  if (ae > 80) v = 0;
  const rd = j => num(rays[j], 15);
  const front = Math.min(rd(3), rd(4), rd(5));
  if (front < 4) v = Math.min(v, vmax * clamp((front - 1.2) / 2.8, 0, 1));
  if (front < 2.5) {
    const lO = (rd(6) + rd(7) + rd(8)) / 3, rO = (rd(0) + rd(1) + rd(2)) / 3;
    if (t > mem.avoidUntil) mem.avoidSign = lO >= rO ? 1 : -1;
    mem.avoidUntil = t + 1.5;
    w += 0.25 * mem.avoidSign;
  }
  w = clamp(w, -0.45, 0.45);
  return { v: v, w: w };
}

function finish(mem, out, s) {
  out.left = clamp(s.v - s.w, -1, 1);
  out.right = clamp(s.v + s.w, -1, 1);
  mem.lastV = s.v; mem.lastW = s.w;
  return out;
}

function initMem(obs, mem) {
  const M = obs.mission || {};
  const x0 = num(obs.x, 200), y0 = num(obs.y, 200);
  const b = M.base || { x: x0, y: y0 };
  mem.base = { x: b.x, y: b.y };
  mem.cap = num(M.capacity, 5);
  mem.hints = (M.hints || []).map(h => ({ x: h.x, y: h.y, est: num(h.estimate, 0), fails: 0, done: false }));
  mem.L = new Float32Array(GN * GN);
  mem.done = []; mem.bad = []; mem.visited = [];
  mem.mode = 'nav'; mem.task = null;
  mem.path = null; mem.pi = 0; mem.pgx = 0; mem.pgy = 0; mem.planT = -99; mem.replan = true;
  mem.bias = 0; mem.anc = { x: x0, y: y0 }; mem.segOK = true;
  mem.dr = { x: x0, y: y0 }; mem.still = 0; mem.lgx = undefined; mem.lgy = undefined;
  mem.lastV = 0; mem.lastW = 0; mem.ei = 0;
  mem.stRef = { x: x0, y: y0 }; mem.stT = 0;
  mem.backT = -1; mem.td = 1; mem.bumps = 0; mem.bumpT = -99;
  mem.dockT0 = null; mem.homeBlock = -1; mem.charging = false;
  mem.drillT0 = 0; mem.drillSX = 0; mem.drillSY = 0; mem.hold = 0;
  mem.siteAct = null; mem.dyn = 0; mem.lastVisit = -99;
  mem.avoidUntil = -1; mem.avoidSign = 1;
  mem.tk = 0; mem.init = true;
}

function act(obs, mem) {
  const out = { left: 0, right: 0, drill: false };
  if (!mem.init) initMem(obs, mem);
  mem.tk++;
  const t = num(obs.t, mem.tk * 0.1);
  const timeLeft = num(obs.timeLeft, 1200 - t);
  const bat = num(obs.battery, 1);
  const carried = num(obs.carried, 0);
  const cap = mem.cap;
  const wl = num(obs.wheelLeft, 0), wr = num(obs.wheelRight, 0);
  const vW = (wl + wr) / 2;
  const hraw = num(obs.heading, 0);
  const pitch = num(obs.pitch, 0);
  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  const sci = num(obs.science, 0);
  const lastV = mem.lastV, lastW = mem.lastW;
  mem.lastV = 0; mem.lastW = 0;

  // ---- localisation: GPS with dead-reckoning fallback
  const ox = num(obs.x, mem.dr.x), oy = num(obs.y, mem.dr.y);
  const hdgPrev = wrap(hraw + mem.bias) * D2R;
  if (ox === mem.lgx && oy === mem.lgy) mem.still++;
  else { mem.still = 0; mem.lgx = ox; mem.lgy = oy; }
  if (mem.still === 0) { mem.dr.x = ox; mem.dr.y = oy; }
  else {
    mem.dr.x += vW * 0.1 * Math.cos(hdgPrev);
    mem.dr.y += vW * 0.1 * Math.sin(hdgPrev);
  }
  const frozen = mem.still > 30;
  const px = frozen ? mem.dr.x : ox, py = frozen ? mem.dr.y : oy;
  const hdg = wrap(hraw + mem.bias), hr = hdg * D2R;

  // ---- compass bias from GPS course over straight-ish segments
  if (lastV < 0.12 || Math.abs(lastW) > 0.1 || vW < 0.1) mem.segOK = false;
  if (hyp(px, py, mem.anc.x, mem.anc.y) > 5) {
    if (mem.segOK && !frozen) {
      const course = Math.atan2(py - mem.anc.y, px - mem.anc.x) * R2D;
      const diff = wrap(course - hraw);
      mem.bias = wrap(mem.bias + 0.2 * wrap(diff - mem.bias));
    }
    mem.anc = { x: px, y: py };
    mem.segOK = true;
  }

  if (!frozen) mapUpdate(mem.L, px, py, hdg, rays);
  if (t - mem.lastVisit > 15) { mem.lastVisit = t; mem.visited.push({ x: px, y: py }); }

  // ---- stuck / bump detection
  if (hyp(px, py, mem.stRef.x, mem.stRef.y) > 0.8) { mem.stRef = { x: px, y: py }; mem.stT = t; }
  const moving = lastV > 0.12 || Math.abs(lastW) > 0.12;
  if (mem.mode === 'nav' && moving && t - mem.stT > 12) {
    startBack(mem, t, px, py, hr, false, true);
  }
  if (obs.bumped === true && mem.mode === 'nav') {
    if (t - mem.bumpT > 30) mem.bumps = 0;
    mem.bumps++; mem.bumpT = t;
    startBack(mem, t, px, py, hr, true, mem.bumps >= 2);
    if (mem.bumps >= 2) mem.bumps = 0;
  }

  // ---- backing off
  if (mem.mode === 'back') {
    if (t < mem.backT) {
      out.left = -0.3 - 0.12 * mem.td;
      out.right = -0.3 + 0.12 * mem.td;
      return out;
    }
    mem.mode = 'nav'; mem.stT = t; mem.stRef = { x: px, y: py };
  }

  // ---- drilling
  if (mem.mode === 'drill') {
    const dr = num(obs.drilling, 0);
    if (dr >= 6) {
      mem.done.push({ x: mem.drillSX, y: mem.drillSY });
      for (const h of mem.hints) if (!h.done && hyp(h.x, h.y, mem.drillSX, mem.drillSY) < 10) h.done = true;
      mem.mode = 'nav'; mem.hold = 0; mem.siteAct = null;
      return out;
    }
    if (t - mem.drillT0 > 16) {
      mem.bad.push({ x: mem.drillSX, y: mem.drillSY });
      mem.mode = 'nav'; mem.hold = 0;
      return out;
    }
    out.drill = true;
    mem.hold = clamp(mem.hold - 0.05 * vW, -0.25, 0.25);
    const u = clamp(-1.5 * vW + mem.hold + 0.01 * pitch, -0.25, 0.25);
    out.left = u; out.right = u;
    return out;
  }

  const base = mem.base;
  const dB = hyp(px, py, base.x, base.y);

  // ---- docking / unloading / charging
  if (mem.mode === 'dock') {
    if (mem.dockT0 === null) mem.dockT0 = t;
    const w = t - mem.dockT0;
    let leave = false;
    if (carried > 0) {
      if (w > 25) { leave = true; mem.homeBlock = t + 20; }
      else if (dB > 2.4) {
        const s = steerTo(mem, px, py, hdg, base.x, base.y, 0.2, rays, t);
        return finish(mem, out, s);
      }
    } else {
      if (mem.charging && bat < 0.8 && w < 40 && timeLeft > 60) { /* charging */ }
      else { leave = true; if (mem.charging) mem.homeBlock = t + 60; }
    }
    if (leave) { mem.mode = 'nav'; mem.dockT0 = null; mem.charging = false; mem.stT = t; mem.stRef = { x: px, y: py }; }
    return out;
  }

  // ---- navigation decisions
  const openH = mem.hints.some(h => !h.done && h.fails < 2);
  let needHome = false, charge = false;
  if (t >= mem.homeBlock) {
    if (carried > 0) {
      needHome = carried >= cap || carried >= 3 || (carried >= 1 && dB < 15) || !openH || timeLeft < dB / 0.45 + 60;
    }
    if (bat < 0.12 + 0.0008 * dB) { needHome = true; charge = carried === 0; }
  }
  if (needHome && dB < 2.4) {
    mem.mode = 'dock'; mem.dockT0 = null; mem.charging = charge; mem.task = null;
    return out;
  }

  // ---- opportunistic site from the site sensor
  const site = obs.site;
  let sAim = null;
  mem.siteAct = null;
  if (!needHome && carried < cap && site && typeof site.distance === 'number' && site.distance <= 8.5) {
    const a = (hdg + num(site.bearing, 0)) * D2R;
    const sx = px + site.distance * Math.cos(a), sy = py + site.distance * Math.sin(a);
    if (!nearL(mem.done, sx, sy, 5) && !nearL(mem.bad, sx, sy, 3)) sAim = { x: sx, y: sy, d: site.distance };
  }
  if (sAim && sAim.d <= 1.4) {
    mem.mode = 'drill'; mem.drillT0 = t;
    mem.drillSX = sAim.x; mem.drillSY = sAim.y; mem.hold = 0;
    out.drill = true;
    return out;
  }
  if (sAim) {
    mem.siteAct = { x: sAim.x, y: sAim.y };
    const vs = clamp(0.05 + 0.2 * (sAim.d - 1.0), 0.05, 0.3);
    const s = steerTo(mem, px, py, hdg, sAim.x, sAim.y, vs, rays, t);
    return finish(mem, out, s);
  }

  // ---- choose target
  let T = null, stopR = 1.0, vmax = 0.4;
  if (needHome) {
    mem.task = null;
    T = base; stopR = 0.5; vmax = 0.4;
  } else {
    const k0 = mem.task;
    if (k0 && k0.kind === 'hint' && (mem.hints[k0.idx].done || mem.hints[k0.idx].fails >= 2)) mem.task = null;
    if (!mem.task) {
      const idx = pickHint(mem, px, py);
      if (idx >= 0) {
        const hh = mem.hints[idx];
        mem.task = { kind: 'hint', idx: idx, phase: 'go', t0: t, d0: hyp(px, py, hh.x, hh.y), wps: null, wi: 0, wT: t, ring: 1, sci: 0 };
      } else {
        const e = pickExplore(mem, px, py);
        mem.task = { kind: 'explore', x: e.x, y: e.y, t0: t };
      }
      mem.replan = true;
    }
    const k = mem.task;
    if (k.kind === 'hint') {
      const h = mem.hints[k.idx];
      if (k.phase === 'go') {
        const d = hyp(px, py, h.x, h.y);
        if (d < 3) {
          k.phase = 'ring';
          k.wps = [{ x: h.x, y: h.y }].concat(ringWps(h.x, h.y, 7, 6, 0));
          k.wi = 0; k.wT = t; mem.replan = true;
        } else if (t - k.t0 > k.d0 / 0.3 + 40) {
          h.fails++; mem.task = null; mem.replan = true;
        }
      }
      if (mem.task && k.phase === 'ring') {
        k.sci = Math.max(k.sci, sci);
        const w = k.wps[k.wi];
        if (hyp(px, py, w.x, w.y) < 2.2 || t - k.wT > 35) {
          k.wi++; k.wT = t; mem.replan = true;
          if (k.wi >= k.wps.length) {
            if (k.ring === 1 && k.sci > 0.4 && timeLeft > 300) {
              k.ring = 2; k.wps = ringWps(h.x, h.y, 14, 10, 0); k.wi = 0;
            } else {
              h.done = true; mem.task = null;
            }
          }
        }
      }
      if (mem.task && k.phase === 'go') { T = { x: h.x, y: h.y }; stopR = 2.5; vmax = 0.4; }
      else if (mem.task && k.phase === 'ring') { T = k.wps[k.wi]; stopR = 1.2; vmax = 0.35; }
    } else if (k.kind === 'explore') {
      if (sci > 1.0 && mem.dyn < 6 && !nearHint(mem, px, py, 10)) {
        mem.dyn++;
        mem.hints.push({ x: px, y: py, est: 0.5, fails: 0, done: false });
        mem.task = { kind: 'hint', idx: mem.hints.length - 1, phase: 'go', t0: t, d0: 0, wps: null, wi: 0, wT: t, ring: 1, sci: 0 };
        mem.replan = true;
      } else if (hyp(px, py, k.x, k.y) < 4 || t - k.t0 > 100) {
        mem.task = null;
      } else {
        T = { x: k.x, y: k.y }; stopR = 3; vmax = 0.4;
      }
    }
  }

  if (!T) { mem.lastV = 0; mem.lastW = 0; return out; }
  if (hyp(px, py, T.x, T.y) < stopR) { mem.lastV = 0; mem.lastW = 0; return out; }
  const aim = followPath(mem, px, py, t, T);
  const s = steerTo(mem, px, py, hdg, aim.x, aim.y, vmax, rays, t);
  return finish(mem, out, s);
}

const D2R = Math.PI / 180, R2D = 180 / Math.PI;
const GN = 200, GC = 2, OCC = 1.5;
const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
const CRUISE = 0.2;

function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function hyp(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function num(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : d; }
function ci(v) { return clamp(Math.floor(v / GC), 0, GN - 1); }
function near(list, x, y, r) {
  for (let i = 0; i < list.length; i++) if (hyp(list[i].x, list[i].y, x, y) < r) return true;
  return false;
}
function ringWps(cx, cy, r, n, ph) {
  const o = [];
  for (let k = 0; k < n; k++) {
    const a = (k * 360 / n + ph) * D2R;
    o.push({ x: clamp(cx + r * Math.cos(a), 4, 396), y: clamp(cy + r * Math.sin(a), 4, 396) });
  }
  return o;
}

// ---- binary heap
function hpush(hk, hv, k, v) {
  let i = hk.length;
  hk.push(k); hv.push(v);
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (hk[p] <= k) break;
    hk[i] = hk[p]; hv[i] = hv[p]; i = p;
  }
  hk[i] = k; hv[i] = v;
}
function hpop(hk, hv) {
  const top = hv[0];
  const lk = hk.pop(), lv = hv.pop();
  const n = hk.length;
  if (n > 0) {
    let i = 0;
    for (;;) {
      let c = 2 * i + 1;
      if (c >= n) break;
      if (c + 1 < n && hk[c + 1] < hk[c]) c++;
      if (hk[c] >= lk) break;
      hk[i] = hk[c]; hv[i] = hv[c]; i = c;
    }
    hk[i] = lk; hv[i] = lv;
  }
  return top;
}

function nearOcc(L, x, y) {
  if (x > 0 && L[y * GN + x - 1] >= OCC) return true;
  if (x < GN - 1 && L[y * GN + x + 1] >= OCC) return true;
  if (y > 0 && L[(y - 1) * GN + x] >= OCC) return true;
  if (y < GN - 1 && L[(y + 1) * GN + x] >= OCC) return true;
  return false;
}

// A* on the occupancy grid; returns list of world points (excluding start) or null
function plan(L, sx, sy, gx, gy) {
  const s = ci(sy) * GN + ci(sx), g = ci(gy) * GN + ci(gx);
  if (s === g) return [];
  const N = GN * GN;
  const gc = new Float32Array(N).fill(1e9);
  const par = new Int32Array(N).fill(-1);
  const closed = new Uint8Array(N);
  const gxc = g % GN, gyc = (g - gxc) / GN;
  const hk = [], hv = [];
  gc[s] = 0;
  hpush(hk, hv, 0, s);
  let found = false, exp = 0;
  while (hk.length > 0 && exp < 9000) {
    const u = hpop(hk, hv);
    if (closed[u]) continue;
    closed[u] = 1; exp++;
    if (u === g) { found = true; break; }
    const ux = u % GN, uy = (u - ux) / GN;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        const nx = ux + dx, ny = uy + dy;
        if (nx < 0 || ny < 0 || nx >= GN || ny >= GN) continue;
        const v = ny * GN + nx;
        if (closed[v]) continue;
        if (v !== g && L[v] >= OCC) continue;
        if (dx && dy && (L[uy * GN + nx] >= OCC || L[ny * GN + ux] >= OCC)) continue;
        let c = (dx && dy) ? 1.414 : 1;
        if (nearOcc(L, nx, ny)) c += 1.0;
        const ng = gc[u] + c;
        if (ng < gc[v]) {
          gc[v] = ng; par[v] = u;
          const ax = Math.abs(nx - gxc), ay = Math.abs(ny - gyc);
          hpush(hk, hv, ng + Math.max(ax, ay) + 0.414 * Math.min(ax, ay), v);
        }
      }
    }
  }
  if (!found) return null;
  const pts = [];
  let c = g;
  while (c !== s && c !== -1) {
    pts.push({ x: ((c % GN) + 0.5) * GC, y: (Math.floor(c / GN) + 0.5) * GC });
    c = par[c];
  }
  pts.reverse();
  return pts;
}

function mapUpdate(L, px, py, hdg, rays) {
  for (let j = 0; j < 9; j++) {
    const r0 = num(rays[j], 15);
    const hit = r0 < 14.5;
    const r = clamp(r0, 0, 15);
    const a = (hdg + ANG[j]) * D2R;
    const ca = Math.cos(a), sa = Math.sin(a);
    for (let s = 1.0; s < r - 0.5; s += 1.0) {
      const k = ci(py + sa * s) * GN + ci(px + ca * s);
      const nv = L[k] - 0.4;
      L[k] = nv < -2 ? -2 : nv;
    }
    if (hit && r > 1.0) {
      const k = ci(py + sa * r) * GN + ci(px + ca * r);
      const nv = L[k] + 1.0;
      L[k] = nv > 3 ? 3 : nv;
    }
  }
}

function pickHint(mem, px, py) {
  let best = null, bs = -1;
  const b = mem.base;
  for (const h of mem.hints) {
    if (h.done || h.fails >= 2) continue;
    const sc = (h.est + 0.5) / (hyp(px, py, h.x, h.y) + 0.5 * hyp(h.x, h.y, b.x, b.y) + 30);
    if (sc > bs) { bs = sc; best = h; }
  }
  return best;
}

function pickExplore(mem, px, py) {
  let best = { x: 200, y: 200 }, bs = -1e9;
  for (let k = 0; k < 10; k++) {
    const x = 20 + Math.random() * 360, y = 20 + Math.random() * 360;
    let dm = 150;
    for (const v of mem.visited) {
      const d = hyp(x, y, v.x, v.y);
      if (d < dm) dm = d;
    }
    const sc = dm - 0.25 * hyp(x, y, px, py);
    if (sc > bs) { bs = sc; best = { x: x, y: y }; }
  }
  return best;
}

function onStuck(mem, px, py, hr, t, why) {
  mem.mode = 'back';
  mem.backT = t + (why === 'bump' ? 1.5 : 2.5);
  mem.td = Math.random() < 0.5 ? -1 : 1;
  for (const d of [1.5, 2.5]) {
    const k = ci(py + d * Math.sin(hr)) * GN + ci(px + d * Math.cos(hr));
    mem.L[k] = 3;
  }
  mem.path = null; mem.replan = true; mem.ei = 0;
  mem.ref = { x: px, y: py, t: t }; mem.pushCnt = 0; mem.spinCnt = 0;
  if (mem.siteTgt) { mem.bad.push({ x: mem.siteTgt.x, y: mem.siteTgt.y }); mem.siteTgt = null; }
  const k = mem.task;
  if (k) {
    k.stuck = (k.stuck || 0) + 1;
    if (k.kind === 'hint' && k.phase === 'ring') {
      k.wi++; k.wT = t;
      if (k.stuck >= 4) { k.h.fails++; mem.task = null; }
    } else if (k.stuck >= 2) {
      if (k.kind === 'hint') k.h.fails++;
      mem.task = null;
    }
  }
}

function steer(mem, px, py, hdg, ax, ay, vmax, rays, t) {
  const e = wrap(Math.atan2(ay - py, ax - px) * R2D - hdg);
  const ae = Math.abs(e);
  if (ae < 35) mem.ei = clamp(mem.ei + e * 0.1, -40, 40);
  else mem.ei *= 0.95;
  let w = 0.0045 * e + 0.002 * mem.ei;
  if (ae > 4 && Math.abs(w) < 0.07) w = 0.07 * (e > 0 ? 1 : -1);
  let v = vmax * clamp(1 - ae / 50, 0, 1);
  const rd = j => num(rays[j], 15);
  const front = Math.min(rd(3), rd(4), rd(5));
  if (front < 3.5) v = Math.min(v, vmax * clamp((front - 0.8) / 2.7, 0.15, 1));
  if (front < 1.8) {
    const lO = (rd(6) + rd(7) + rd(8)) / 3, rO = (rd(0) + rd(1) + rd(2)) / 3;
    if (t > mem.avoidUntil) mem.avoidSign = lO >= rO ? 1 : -1;
    mem.avoidUntil = t + 1.5;
    w += 0.3 * mem.avoidSign;
    if (front < 1.0) v = Math.min(v, 0.08);
  }
  w = clamp(w, -0.4, 0.4);
  mem.lastV = v; mem.lastW = w;
  return { left: clamp(v - w, -1, 1), right: clamp(v + w, -1, 1) };
}

function drive(out, s) { out.left = s.left; out.right = s.right; return out; }

function followPath(mem, px, py, t, T, L) {
  let need = !mem.path || mem.replan || hyp(mem.pgx, mem.pgy, T.x, T.y) > 2.5 || t - mem.planT > 6;
  if (!need && mem.path && mem.pi < mem.path.length - 1 && t - mem.planT > 1.5) {
    const a = mem.path[mem.pi];
    if (L[ci(a.y) * GN + ci(a.x)] >= OCC) need = true;
  }
  if (need) {
    const P = plan(L, px, py, T.x, T.y);
    if (P === null) { mem.path = [{ x: T.x, y: T.y }]; mem.planFail++; }
    else { mem.path = P.concat([{ x: T.x, y: T.y }]); mem.planFail = 0; }
    mem.pi = 0; mem.pgx = T.x; mem.pgy = T.y; mem.planT = t; mem.replan = false;
  }
  const P = mem.path;
  while (mem.pi < P.length - 1 && hyp(px, py, P[mem.pi].x, P[mem.pi].y) < 2.0) mem.pi++;
  return P[mem.pi];
}

function initMem(obs, mem) {
  const M = obs.mission || {};
  const x0 = num(obs.x, 200), y0 = num(obs.y, 200);
  const b = M.base || { x: x0, y: y0 };
  mem.base = { x: num(b.x, x0), y: num(b.y, y0) };
  mem.cap = num(M.capacity, 5);
  mem.hints = (M.hints || []).map(h => ({ x: num(h.x, 200), y: num(h.y, 200), est: num(h.estimate, 0), fails: 0, done: false }));
  mem.L = new Float32Array(GN * GN);
  mem.done = []; mem.bad = []; mem.visited = [];
  mem.mode = 'nav'; mem.task = null;
  mem.path = null; mem.pi = 0; mem.pgx = 0; mem.pgy = 0; mem.planT = -99; mem.replan = true; mem.planFail = 0;
  mem.bias = 0; mem.anc = { x: x0, y: y0 }; mem.segOK = true;
  mem.dr = { x: x0, y: y0 }; mem.still = 0; mem.lgx = undefined; mem.lgy = undefined;
  mem.lastV = 0; mem.lastW = 0; mem.ei = 0;
  mem.ref = { x: x0, y: y0, t: 0 }; mem.pushCnt = 0; mem.spinCnt = 0;
  mem.backT = -1; mem.td = 1; mem.bumpT = -99;
  mem.dockT0 = null; mem.homeBlock = -1; mem.charging = false;
  mem.drillT0 = 0; mem.drillAt = { x: x0, y: y0, rx: x0, ry: y0 };
  mem.siteTgt = null; mem.siteT0 = -99; mem.siteBest = 99;
  mem.avoidUntil = -1; mem.avoidSign = 1;
  mem.dyn = 0; mem.lastVisit = -99;
  mem.tk = 0; mem.init = true;
}

function act(obs, mem) {
  const out = { left: 0, right: 0, drill: false };
  if (!mem.init) initMem(obs, mem);
  mem.tk++;
  const t = num(obs.t, mem.tk * 0.1);
  const timeLeft = num(obs.timeLeft, 1200 - t);
  const bat = num(obs.battery, 1);
  const carried = num(obs.carried, 0);
  const cap = num(mem.cap, 5);
  const wl = num(obs.wheelLeft, 0), wr = num(obs.wheelRight, 0);
  const vW = (wl + wr) / 2;
  const hraw = num(obs.heading, 0);
  const pitch = num(obs.pitch, 0);
  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  const sci = num(obs.science, 0);
  const lastV = mem.lastV, lastW = mem.lastW;
  mem.lastV = 0; mem.lastW = 0;

  // ---- localisation: GPS with dead-reckoning fallback
  const ox = num(obs.x, mem.dr.x), oy = num(obs.y, mem.dr.y);
  const hPrev = wrap(hraw + mem.bias) * D2R;
  if (ox === mem.lgx && oy === mem.lgy) mem.still++;
  else { mem.still = 0; mem.lgx = ox; mem.lgy = oy; }
  if (mem.still === 0) { mem.dr.x = ox; mem.dr.y = oy; }
  else { mem.dr.x += vW * 0.1 * Math.cos(hPrev); mem.dr.y += vW * 0.1 * Math.sin(hPrev); }
  const frozen = mem.still > 30 && Math.abs(vW) > 0.05;
  const px = frozen ? mem.dr.x : ox, py = frozen ? mem.dr.y : oy;

  // ---- compass bias from GPS course on straight-ish runs
  const straight = lastV > 0.12 && Math.abs(lastW) < 0.12;
  if (!straight) mem.segOK = false;
  if (hyp(px, py, mem.anc.x, mem.anc.y) > 6) {
    if (mem.segOK && !frozen) {
      const course = Math.atan2(py - mem.anc.y, px - mem.anc.x) * R2D;
      const diff = wrap(course - hraw);
      mem.bias = wrap(mem.bias + 0.25 * wrap(diff - mem.bias));
    }
    mem.anc = { x: px, y: py }; mem.segOK = true;
  }
  const hdg = wrap(hraw + mem.bias), hr = hdg * D2R;
  const dB = hyp(px, py, mem.base.x, mem.base.y);

  if (!frozen) mapUpdate(mem.L, px, py, hdg, rays);
  if (t - mem.lastVisit > 15) { mem.lastVisit = t; mem.visited.push({ x: px, y: py }); }

  // ---- stall / bump detection
  if (hyp(px, py, mem.ref.x, mem.ref.y) > 1.0) { mem.ref = { x: px, y: py, t: t }; mem.pushCnt = 0; mem.spinCnt = 0; }
  if (lastV > 0.08) mem.pushCnt++;
  if (lastV === 0 && Math.abs(lastW) > 0.05) mem.spinCnt++;
  const bumped = obs.bumped === true && t - mem.bumpT > 1.5;
  if (bumped) mem.bumpT = t;
  if (mem.mode === 'nav') {
    if (bumped) onStuck(mem, px, py, hr, t, 'bump');
    else if (mem.pushCnt > 100) onStuck(mem, px, py, hr, t, 'push');
    else if (mem.spinCnt > 100) onStuck(mem, px, py, hr, t, 'spin');
  }

  // ---- backing off
  if (mem.mode === 'back') {
    if (t < mem.backT) {
      out.left = -0.15 - 0.08 * mem.td;
      out.right = -0.15 + 0.08 * mem.td;
      return out;
    }
    mem.mode = 'nav'; mem.ref = { x: px, y: py, t: t }; mem.pushCnt = 0; mem.spinCnt = 0;
  }

  // ---- drilling
  if (mem.mode === 'drill') {
    const dr = num(obs.drilling, 0);
    const mv = hyp(px, py, mem.drillAt.rx, mem.drillAt.ry);
    if (dr >= 6) {
      mem.done.push({ x: mem.drillAt.x, y: mem.drillAt.y });
      for (const h of mem.hints) if (hyp(h.x, h.y, mem.drillAt.x, mem.drillAt.y) < 12) h.done = true;
      mem.task = null; mem.siteTgt = null;
      mem.mode = 'nav'; mem.ref = { x: px, y: py, t: t }; mem.pushCnt = 0; mem.spinCnt = 0;
      mem.path = null; mem.replan = true;
      return out;
    }
    if (t - mem.drillT0 > 16 || mv > 2.0) {
      mem.bad.push({ x: mem.drillAt.x, y: mem.drillAt.y });
      mem.mode = 'nav'; mem.ref = { x: px, y: py, t: t }; mem.pushCnt = 0; mem.spinCnt = 0;
      mem.path = null; mem.replan = true;
      return out;
    }
    out.drill = true;
    const u = clamp(-1.5 * vW + 0.01 * pitch, -0.25, 0.25);
    out.left = u; out.right = u;
    return out;
  }

  // ---- docking / unloading / charging
  if (mem.mode === 'dock') {
    if (mem.dockT0 === null) mem.dockT0 = t;
    const w = t - mem.dockT0;
    if (carried > 0 && w < 25) {
      if (dB > 1.8 && w > 3) return drive(out, steer(mem, px, py, hdg, mem.base.x, mem.base.y, 0.12, rays, t));
      return out;
    }
    if (carried > 0) mem.homeBlock = t + 30;
    if (mem.charging && carried === 0 && bat < 0.6 && w < 60 && timeLeft > 200) return out;
    mem.mode = 'nav'; mem.dockT0 = null; mem.charging = false;
    mem.ref = { x: px, y: py, t: t }; mem.pushCnt = 0; mem.spinCnt = 0;
    mem.path = null; mem.replan = true;
    return out;
  }

  // ---- go-home decision
  const hintsLeft = mem.hints.some(h => !h.done && h.fails < 2);
  let needHome = false, charge = false;
  if (t >= mem.homeBlock) {
    if (carried > 0) {
      needHome = carried >= cap || carried >= 3 || (carried >= 1 && (!hintsLeft || dB < 25)) ||
        timeLeft < dB / 0.35 + 60 || bat < 0.12 + 0.0012 * dB;
    } else if (bat < 0.2 && timeLeft > 150) {
      needHome = true; charge = true;
    }
  }
  if (needHome && dB < 2.6) {
    mem.mode = 'dock'; mem.dockT0 = null; mem.charging = bat < 0.5 || charge;
    mem.task = null; mem.path = null; mem.siteTgt = null;
    return out;
  }

  // ---- opportunistic site from the site sensor
  const site = obs.site;
  let sAim = null;
  if (!needHome && carried < cap && site && typeof site.distance === 'number' && site.distance <= 8.5) {
    const a = (hdg + num(site.bearing, 0)) * D2R;
    const sx = px + site.distance * Math.cos(a), sy = py + site.distance * Math.sin(a);
    if (!near(mem.done, sx, sy, 4) && !near(mem.bad, sx, sy, 3)) sAim = { x: sx, y: sy, d: site.distance };
  }
  mem.siteTgt = sAim;
  if (sAim && sAim.d <= 1.3) {
    mem.mode = 'drill'; mem.drillT0 = t;
    mem.drillAt = { x: sAim.x, y: sAim.y, rx: px, ry: py };
    mem.siteTgt = null; mem.siteT0 = -99;
    out.drill = true;
    return out;
  }
  if (sAim) {
    if (mem.siteT0 < 0 || sAim.d < mem.siteBest - 0.3) { mem.siteBest = sAim.d; mem.siteT0 = t; }
    if (t - mem.siteT0 > 12) {
      mem.bad.push({ x: sAim.x, y: sAim.y }); mem.siteTgt = null; mem.siteT0 = -99;
    } else {
      const v = clamp(0.05 + 0.1 * (sAim.d - 1.0), 0.05, 0.15);
      return drive(out, steer(mem, px, py, hdg, sAim.x, sAim.y, v, rays, t));
    }
  }

  // ---- choose target
  let T = null, stopR = 1.0, vmax = CRUISE;
  if (needHome) {
    mem.task = null;
    T = mem.base; stopR = 2.4; vmax = CRUISE;
  } else {
    let k = mem.task;
    if (k && k.kind === 'hint' && (k.h.done || k.h.fails >= 2)) { mem.task = null; k = null; }
    if (!k) {
      const h = pickHint(mem, px, py);
      if (h) {
        mem.task = { kind: 'hint', h: h, phase: 'go', t0: t, d0: hyp(px, py, h.x, h.y), wps: null, wi: 0, wT: t, ring: 1, sci: 0, stuck: 0 };
      } else {
        const e = pickExplore(mem, px, py);
        mem.task = { kind: 'explore', x: e.x, y: e.y, t0: t, stuck: 0 };
      }
      mem.replan = true;
      k = mem.task;
    }
    if (k.kind === 'hint') {
      const h = k.h;
      if (k.phase === 'go') {
        const d = hyp(px, py, h.x, h.y);
        if (d < 3.0) {
          k.phase = 'ring';
          k.wps = [{ x: h.x, y: h.y }].concat(ringWps(h.x, h.y, 6, 6, 0));
          k.wi = 0; k.wT = t; mem.replan = true;
        } else if (t - k.t0 > k.d0 / 0.2 + 60) {
          h.fails++; mem.task = null; mem.replan = true;
        }
      }
      if (mem.task && k.phase === 'ring') {
        k.sci = Math.max(k.sci, sci);
        while (k.wi < k.wps.length) {
          const w = k.wps[k.wi];
          if (hyp(px, py, w.x, w.y) < 2.0 || t - k.wT > 30) { k.wi++; k.wT = t; mem.replan = true; }
          else break;
        }
        if (k.wi >= k.wps.length) {
          if (k.ring === 1 && k.sci > 0.3 && timeLeft > 350) {
            k.ring = 2; k.wps = ringWps(h.x, h.y, 12, 8, 0); k.wi = 0; k.wT = t;
          } else {
            h.done = true; mem.task = null;
          }
        }
      }
    } else {
      if (sci > 1.0 && mem.dyn < 6 && !near(mem.hints, px, py, 10)) {
        mem.dyn++;
        const nh = { x: px, y: py, est: 5, fails: 0, done: false };
        mem.hints.push(nh);
        mem.task = { kind: 'hint', h: nh, phase: 'go', t0: t, d0: 0, wps: null, wi: 0, wT: t, ring: 1, sci: 0, stuck: 0 };
        mem.replan = true;
      } else if (hyp(px, py, k.x, k.y) < 4 || t - k.t0 > 100) {
        mem.task = null; mem.replan = true;
      }
    }
    if (mem.task) {
      const q = mem.task;
      if (q.kind === 'hint') {
        if (q.phase === 'go') { T = q.h; stopR = 2.5; vmax = CRUISE; }
        else if (q.wi < q.wps.length) { T = q.wps[q.wi]; stopR = 1.2; vmax = CRUISE; }
      } else {
        T = { x: q.x, y: q.y }; stopR = 3; vmax = CRUISE;
      }
    }
  }

  if (!T) { mem.lastV = 0; mem.lastW = 0; return out; }
  const dT = hyp(px, py, T.x, T.y);
  if (dT < stopR) { mem.lastV = 0; mem.lastW = 0; return out; }
  const aim = followPath(mem, px, py, t, T, mem.L);
  if (mem.planFail >= 4) {
    if (mem.task && mem.task.kind === 'hint') mem.task.h.fails++;
    mem.task = null; mem.planFail = 0; mem.replan = true;
    mem.lastV = 0; mem.lastW = 0;
    return out;
  }
  const vEff = Math.min(vmax, 0.08 + 0.1 * dT);
  return drive(out, steer(mem, px, py, hdg, aim.x, aim.y, vEff, rays, t));
}

const D2R = Math.PI / 180, R2D = 180 / Math.PI;
const GN = 200, GC = 2, OCC = 1.5;
const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
const VMAX = 0.2;

function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function hyp(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function num(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : d; }
function ci(v) { return clamp(Math.floor(v / GC), 0, GN - 1); }
function near(list, x, y, r) {
  for (let i = 0; i < list.length; i++) if (hyp(list[i].x, list[i].y, x, y) < r) return true;
  return false;
}
function ringWps(cx, cy, r, n, ph) {
  const o = [];
  for (let k = 0; k < n; k++) {
    const a = (k * 360 / n + ph) * D2R;
    o.push({ x: clamp(cx + r * Math.cos(a), 4, 396), y: clamp(cy + r * Math.sin(a), 4, 396) });
  }
  return o;
}

// ---- binary heap
function hpush(hk, hv, k, v) {
  let i = hk.length;
  hk.push(k); hv.push(v);
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (hk[p] <= k) break;
    hk[i] = hk[p]; hv[i] = hv[p]; i = p;
  }
  hk[i] = k; hv[i] = v;
}
function hpop(hk, hv) {
  const top = hv[0];
  const lk = hk.pop(), lv = hv.pop();
  const n = hk.length;
  if (n > 0) {
    let i = 0;
    for (;;) {
      let c = 2 * i + 1;
      if (c >= n) break;
      if (c + 1 < n && hk[c + 1] < hk[c]) c++;
      if (hk[c] >= lk) break;
      hk[i] = hk[c]; hv[i] = hv[c]; i = c;
    }
    hk[i] = lk; hv[i] = lv;
  }
  return top;
}

function nearOcc(L, x, y) {
  if (x > 0 && L[y * GN + x - 1] >= OCC) return true;
  if (x < GN - 1 && L[y * GN + x + 1] >= OCC) return true;
  if (y > 0 && L[(y - 1) * GN + x] >= OCC) return true;
  if (y < GN - 1 && L[(y + 1) * GN + x] >= OCC) return true;
  return false;
}

// A* on occupancy grid; returns world points (excluding start) or null
function plan(L, sx, sy, gx, gy) {
  const s = ci(sy) * GN + ci(sx), g = ci(gy) * GN + ci(gx);
  if (s === g) return [];
  const N = GN * GN;
  const gc = new Float32Array(N).fill(1e9);
  const par = new Int32Array(N).fill(-1);
  const closed = new Uint8Array(N);
  const gxc = g % GN, gyc = (g - gxc) / GN;
  const hk = [], hv = [];
  gc[s] = 0;
  hpush(hk, hv, 0, s);
  let found = false, exp = 0;
  while (hk.length > 0 && exp < 9000) {
    const u = hpop(hk, hv);
    if (closed[u]) continue;
    closed[u] = 1; exp++;
    if (u === g) { found = true; break; }
    const ux = u % GN, uy = (u - ux) / GN;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        const nx = ux + dx, ny = uy + dy;
        if (nx < 0 || ny < 0 || nx >= GN || ny >= GN) continue;
        const v = ny * GN + nx;
        if (closed[v]) continue;
        if (v !== g && L[v] >= OCC) continue;
        if (dx && dy && (L[uy * GN + nx] >= OCC || L[ny * GN + ux] >= OCC)) continue;
        let c = (dx && dy) ? 1.414 : 1;
        if (nearOcc(L, nx, ny)) c += 1.0;
        const ng = gc[u] + c;
        if (ng < gc[v]) {
          gc[v] = ng; par[v] = u;
          const ax = Math.abs(nx - gxc), ay = Math.abs(ny - gyc);
          hpush(hk, hv, ng + Math.max(ax, ay) + 0.414 * Math.min(ax, ay), v);
        }
      }
    }
  }
  if (!found) return null;
  const pts = [];
  let c = g;
  while (c !== s && c !== -1) {
    pts.push({ x: ((c % GN) + 0.5) * GC, y: (Math.floor(c / GN) + 0.5) * GC });
    c = par[c];
  }
  pts.reverse();
  return pts;
}

function mapUpdate(L, px, py, hdg, rays) {
  for (let j = 0; j < 9; j++) {
    const r0 = num(rays[j], 15);
    const hit = r0 < 14.5;
    const r = clamp(r0, 0, 15);
    const a = (hdg + ANG[j]) * D2R;
    const ca = Math.cos(a), sa = Math.sin(a);
    for (let s = 1.0; s < r - 0.5; s += 1.0) {
      const k = ci(py + sa * s) * GN + ci(px + ca * s);
      const nv = L[k] - 0.4;
      L[k] = nv < -2 ? -2 : nv;
    }
    if (hit && r > 1.0) {
      const k = ci(py + sa * r) * GN + ci(px + ca * r);
      const nv = L[k] + 1.0;
      L[k] = nv > 3 ? 3 : nv;
    }
  }
}

function pickHint(mem, px, py) {
  let best = -1, bs = -1;
  const b = mem.base;
  for (let i = 0; i < mem.hints.length; i++) {
    const h = mem.hints[i];
    if (h.done || h.fails >= 2) continue;
    const sc = (h.est + 0.5) / (hyp(px, py, h.x, h.y) + 0.5 * hyp(h.x, h.y, b.x, b.y) + 30);
    if (sc > bs) { bs = sc; best = i; }
  }
  return best;
}

function pickExplore(mem, px, py) {
  let best = { x: 200, y: 200 }, bs = -1e9;
  for (let i = 0; i < 10; i++) {
    const x = 20 + Math.random() * 360, y = 20 + Math.random() * 360;
    let dm = 150;
    for (const v of mem.visited) {
      const d = hyp(x, y, v.x, v.y);
      if (d < dm) dm = d;
    }
    const sc = dm - 0.25 * hyp(x, y, px, py);
    if (sc > bs) { bs = sc; best = { x: x, y: y }; }
  }
  return best;
}

function set(out, mem, l, r) {
  out.left = clamp(l, -1, 1);
  out.right = clamp(r, -1, 1);
  mem.lastL = out.left; mem.lastR = out.right;
  mem.lastV = (out.left + out.right) / 2;
  mem.lastW = (out.right - out.left) / 2;
  return out;
}

function drive(out, mem, s) { return set(out, mem, s.v - s.w, s.v + s.w); }

// heading controller: returns {v, w}; w>0 turns left
function steer(mem, px, py, hdg, ax, ay, vmax, rays, t) {
  const e = wrap(Math.atan2(ay - py, ax - px) * R2D - hdg);
  const ae = Math.abs(e);
  let v, w;
  if (ae > 50) {
    v = 0; mem.ei = 0;
    w = e > 0 ? 0.3 : -0.3;
  } else {
    mem.ei = clamp(mem.ei + e * 0.1, -300, 300);
    w = 0.006 * e + 0.0003 * mem.ei;
    if (ae > 3 && Math.abs(w) < 0.05) w = e > 0 ? 0.05 : -0.05;
    v = vmax * (1 - ae / 60);
  }
  const rd = j => num(rays[j], 15);
  const front = Math.min(rd(3), rd(4), rd(5));
  if (front < 3.0) v = Math.min(v, vmax * clamp((front - 1.0) / 2.0, 0, 1));
  if (front < 1.6) {
    const lO = (rd(6) + rd(7) + rd(8)) / 3, rO = (rd(0) + rd(1) + rd(2)) / 3;
    if (t > mem.avoidUntil) mem.avoidSign = lO >= rO ? 1 : -1;
    mem.avoidUntil = t + 1.5;
  }
  if (t < mem.avoidUntil) w += 0.2 * mem.avoidSign;
  w = clamp(w, -0.4, 0.4);
  return { v: v, w: w };
}

function followPath(mem, px, py, t, T) {
  let need = !mem.path || mem.replan || hyp(mem.pgx, mem.pgy, T.x, T.y) > 2.5 || t - mem.planT > 6;
  if (!need && mem.pi < mem.path.length - 1 && t - mem.planT > 1.5) {
    const a = mem.path[mem.pi];
    if (mem.L[ci(a.y) * GN + ci(a.x)] >= OCC) need = true;
  }
  if (need) {
    const P = plan(mem.L, px, py, T.x, T.y);
    if (P === null) { mem.path = [{ x: T.x, y: T.y }]; mem.planFail++; }
    else { mem.path = P.concat([{ x: T.x, y: T.y }]); mem.planFail = 0; }
    mem.pi = 0; mem.pgx = T.x; mem.pgy = T.y; mem.planT = t; mem.replan = false;
  }
  const P = mem.path;
  while (mem.pi < P.length - 1 && hyp(px, py, P[mem.pi].x, P[mem.pi].y) < 2.0) mem.pi++;
  return P[mem.pi];
}

function startBack(mem, t, px, py, hdg, bump) {
  mem.mode = 'back';
  mem.backT = t + (bump ? 1.5 : 2.0);
  mem.td = Math.random() < 0.5 ? -1 : 1;
  const hr = hdg * D2R;
  for (const d of [1.5, 2.5]) {
    const k = ci(py + d * Math.sin(hr)) * GN + ci(px + d * Math.cos(hr));
    mem.L[k] = 3;
  }
  if (mem.apPos) { mem.bad.push({ x: mem.apPos.x, y: mem.apPos.y }); mem.apPos = null; }
  mem.path = null; mem.replan = true; mem.ei = 0;
  mem.sRef = { x: px, y: py, h: hdg, t: t };
  const k = mem.task;
  if (k) {
    k.stuck = (k.stuck || 0) + 1;
    if (k.stuck >= 3) {
      if (k.kind === 'hint') mem.hints[k.idx].fails++;
      mem.task = null;
    }
  }
}

function leaveDock(mem, t, blk, px, py, hdg) {
  mem.mode = 'nav'; mem.dT0 = null; mem.homeBlock = t + blk;
  mem.path = null; mem.replan = true;
  mem.sRef = { x: px, y: py, h: hdg, t: t };
  if (mem.task) { mem.task.t0 = t; mem.task.wT = t; }
  mem.charging = false;
}

function updateTask(mem, px, py, t, timeLeft, sci) {
  const k = mem.task;
  if (!k) return;
  if (k.kind === 'hint') {
    const h = mem.hints[k.idx];
    if (h.done || h.fails >= 2) { mem.task = null; return; }
    if (k.phase === 'go') {
      const d = hyp(px, py, h.x, h.y);
      if (d < 5) {
        k.phase = 'search'; k.wps = ringWps(h.x, h.y, 6, 8, 0); k.wi = 0; k.wT = t;
        mem.path = null; mem.replan = true;
      } else if (t - k.t0 > k.d0 / 0.3 + 60) {
        h.fails++; mem.task = null; mem.path = null; mem.replan = true;
        return;
      } else return;
    }
    k.sciMax = Math.max(k.sciMax, sci);
    while (k.wi < k.wps.length) {
      const w = k.wps[k.wi];
      if (hyp(px, py, w.x, w.y) < 2.0 || t - k.wT > 40) {
        k.wi++; k.wT = t; mem.path = null; mem.replan = true;
      } else break;
    }
    if (k.wi >= k.wps.length) {
      if (k.ring === 1 && k.sciMax > 0.25 && timeLeft > 400) {
        k.ring = 2; k.wps = ringWps(h.x, h.y, 12, 10, 0.3); k.wi = 0; k.wT = t;
        mem.path = null; mem.replan = true;
      } else {
        h.done = true; mem.task = null; mem.path = null; mem.replan = true;
      }
    }
  } else {
    if (hyp(px, py, k.x, k.y) < 4 || t - k.t0 > 120) {
      mem.task = null; mem.path = null; mem.replan = true;
      return;
    }
    if (sci > 0.8 && mem.dyn < 6 && !near(mem.hints, px, py, 12)) {
      mem.dyn++;
      mem.hints.push({ x: px, y: py, est: 3, fails: 0, done: false });
      mem.task = { kind: 'hint', idx: mem.hints.length - 1, phase: 'go', t0: t, d0: 0, wps: null, wi: 0, wT: t, ring: 1, sciMax: 0, stuck: 0 };
      mem.path = null; mem.replan = true;
    }
  }
}

function currentTarget(mem) {
  const k = mem.task;
  if (!k) return null;
  if (k.kind === 'hint') {
    const h = mem.hints[k.idx];
    if (k.phase === 'go') return { x: h.x, y: h.y, stopR: 3, vmax: VMAX };
    if (k.wi < k.wps.length) return { x: k.wps[k.wi].x, y: k.wps[k.wi].y, stopR: 1.2, vmax: 0.15 };
    return null;
  }
  return { x: k.x, y: k.y, stopR: 3, vmax: VMAX };
}

function initMem(obs, mem) {
  const M = obs.mission || {};
  const x0 = num(obs.x, 200), y0 = num(obs.y, 200);
  const b = M.base || { x: x0, y: y0 };
  mem.base = { x: num(b.x, x0), y: num(b.y, y0) };
  mem.cap = num(M.capacity, 5);
  mem.hints = (M.hints || []).map(h => ({ x: num(h.x, 200), y: num(h.y, 200), est: num(h.estimate, 0), fails: 0, done: false }));
  mem.L = new Float32Array(GN * GN);
  mem.done = []; mem.bad = []; mem.visited = [];
  mem.mode = 'nav'; mem.task = null;
  mem.path = null; mem.pi = 0; mem.pgx = 0; mem.pgy = 0; mem.planT = -99; mem.replan = true; mem.planFail = 0;
  mem.ex = x0; mem.ey = y0; mem.glx = undefined; mem.gly = undefined; mem.gStill = 0;
  mem.bias = 0; mem.anc = { x: x0, y: y0 }; mem.segOK = true;
  mem.lastV = 0; mem.lastW = 0; mem.lastL = 0; mem.lastR = 0;
  mem.ei = 0; mem.avoidUntil = -1; mem.avoidSign = 1;
  mem.sRef = { x: x0, y: y0, h: 0, t: 0 }; mem.bumpT = -99;
  mem.backT = -1; mem.td = 1;
  mem.homeBlock = -1; mem.dT0 = null; mem.charging = false;
  mem.drT0 = 0; mem.dsx = 0; mem.dsy = 0; mem.dsPx = 0; mem.dsPy = 0; mem.dI = 0;
  mem.apPos = null; mem.apBest = 99; mem.apT = 0;
  mem.dyn = 0; mem.lastVisit = -99; mem.tk = 0; mem.init = true;
}

function act(obs, mem) {
  const out = { left: 0, right: 0, drill: false };
  if (!mem.init) initMem(obs, mem);
  mem.tk++;
  const t = num(obs.t, mem.tk * 0.1);
  const timeLeft = num(obs.timeLeft, 1200 - t);
  const bat = num(obs.battery, 1);
  const carried = num(obs.carried, 0);
  const cap = num(mem.cap, 5);
  const wl = num(obs.wheelLeft, 0), wr = num(obs.wheelRight, 0);
  const vW = (wl + wr) / 2;
  const hraw = num(obs.heading, 0);
  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  const rd = j => num(rays[j], 15);
  const front = Math.min(rd(3), rd(4), rd(5));
  const sci = num(obs.science, 0);
  const site = (obs.site && typeof obs.site.distance === 'number') ? obs.site : null;
  const lastV = mem.lastV, lastW = mem.lastW, lastL = mem.lastL, lastR = mem.lastR;

  // ---- localisation: wheel-speed dead reckoning fused with GPS
  const hdgPrev = wrap(hraw + mem.bias) * D2R;
  mem.ex += vW * 0.1 * Math.cos(hdgPrev);
  mem.ey += vW * 0.1 * Math.sin(hdgPrev);
  const gx = num(obs.x, NaN), gy = num(obs.y, NaN);
  if (isFinite(gx) && isFinite(gy)) {
    if (gx !== mem.glx || gy !== mem.gly) {
      const jx = gx - mem.ex, jy = gy - mem.ey;
      const fuse = Math.hypot(jx, jy) > 8 ? 0.2 : 0.5;
      mem.ex += fuse * jx; mem.ey += fuse * jy;
      mem.glx = gx; mem.gly = gy; mem.gStill = 0;
    } else mem.gStill++;
  }
  const px = mem.ex, py = mem.ey;

  // ---- compass bias from GPS course on straight runs
  const straight = lastV > 0.12 && Math.abs(lastL - lastR) < 0.3;
  if (!straight) mem.segOK = false;
  if (hyp(px, py, mem.anc.x, mem.anc.y) > 4) {
    if (mem.segOK && mem.gStill < 20) {
      const course = Math.atan2(py - mem.anc.y, px - mem.anc.x) * R2D;
      const diff = wrap(course - hraw);
      mem.bias = wrap(mem.bias + 0.2 * wrap(diff - mem.bias));
    }
    mem.anc = { x: px, y: py }; mem.segOK = true;
  }
  const hdg = wrap(hraw + mem.bias), hr = hdg * D2R;
  const dB = hyp(px, py, mem.base.x, mem.base.y);

  if (t - mem.lastVisit > 15) { mem.lastVisit = t; mem.visited.push({ x: px, y: py }); }
  if (mem.gStill < 40) mapUpdate(mem.L, px, py, hdg, rays);

  // ---- stuck / bump detection
  if (hyp(px, py, mem.sRef.x, mem.sRef.y) > 1.5 || Math.abs(wrap(hdg - mem.sRef.h)) > 25) {
    mem.sRef = { x: px, y: py, h: hdg, t: t };
  }
  const bumped = obs.bumped === true && t - mem.bumpT > 2;
  if (bumped) mem.bumpT = t;
  if (mem.mode === 'nav') {
    const cmdAct = lastV > 0.06 || Math.abs(lastW) > 0.1;
    if (bumped) startBack(mem, t, px, py, hdg, true);
    else if (cmdAct && t - mem.sRef.t > 10) startBack(mem, t, px, py, hdg, false);
  }

  // ---- backing off
  if (mem.mode === 'back') {
    if (t < mem.backT) return set(out, mem, -0.2 - 0.1 * mem.td, -0.2 + 0.1 * mem.td);
    mem.mode = 'nav'; mem.sRef = { x: px, y: py, h: hdg, t: t };
  }

  // ---- drilling: hold still for 6 s
  if (mem.mode === 'drill') {
    const dr = num(obs.drilling, 0);
    if (dr >= 6) {
      mem.done.push({ x: mem.dsx, y: mem.dsy });
      for (const h of mem.hints) if (hyp(h.x, h.y, mem.dsx, mem.dsy) < 8) h.done = true;
      mem.mode = 'nav'; mem.apPos = null; mem.path = null; mem.replan = true;
      mem.sRef = { x: px, y: py, h: hdg, t: t };
      return set(out, mem, 0, 0);
    }
    if (t - mem.drT0 > 16 || hyp(px, py, mem.dsPx, mem.dsPy) > 2.5) {
      mem.bad.push({ x: mem.dsx, y: mem.dsy });
      mem.mode = 'nav'; mem.apPos = null; mem.path = null; mem.replan = true;
      mem.sRef = { x: px, y: py, h: hdg, t: t };
      return set(out, mem, 0, 0);
    }
    mem.dI = clamp(mem.dI - 0.03 * vW, -0.3, 0.3);
    const u = clamp(-0.2 * vW + mem.dI, -0.3, 0.3);
    out.drill = true;
    return set(out, mem, u, u);
  }

  // ---- docked at base: unload and possibly charge
  if (mem.mode === 'dock') {
    const w = t - mem.dT0;
    if (carried > 0) {
      if (w > 30) leaveDock(mem, t, 60, px, py, hdg);
      return set(out, mem, 0, 0);
    }
    if (mem.charging && bat < 0.3 && w < 60 && timeLeft > 150) return set(out, mem, 0, 0);
    leaveDock(mem, t, 60, px, py, hdg);
    return set(out, mem, 0, 0);
  }

  // ---- go-home decision
  const openH = mem.hints.some(h => !h.done && h.fails < 2);
  let needHome = false;
  if (t >= mem.homeBlock) {
    if (carried > 0) {
      needHome = carried >= cap || carried >= 3 || (carried >= 1 && (dB < 20 || !openH)) ||
        timeLeft < dB / 0.35 + 60;
    }
    if (bat < 0.2 + 0.0005 * dB && timeLeft > 40) needHome = true;
  }
  if (needHome && (obs.docked === true || dB < 2.5)) {
    mem.mode = 'dock'; mem.dT0 = t; mem.charging = bat < 0.3;
    mem.apPos = null;
    return set(out, mem, 0, 0);
  }

  // ---- site sensor: approach and drill
  let sPos = null;
  if (site && site.distance <= 8.5 && carried < cap && !needHome) {
    const a = (hdg + num(site.bearing, 0)) * D2R;
    const q = { x: px + site.distance * Math.cos(a), y: py + site.distance * Math.sin(a) };
    if (!near(mem.done, q.x, q.y, 4) && !near(mem.bad, q.x, q.y, 3)) sPos = q;
  }
  if (!sPos) mem.apPos = null;
  if (sPos) {
    const sd = site.distance;
    if (sd <= 1.4) {
      mem.mode = 'drill'; mem.drT0 = t;
      mem.dsx = sPos.x; mem.dsy = sPos.y; mem.dsPx = px; mem.dsPy = py;
      mem.dI = 0; mem.apPos = null;
      out.drill = true;
      return set(out, mem, 0, 0);
    }
    if (!mem.apPos || sd < mem.apBest - 0.4) { mem.apBest = sd; mem.apT = t; }
    mem.apPos = sPos;
    if (t - mem.apT > 30) {
      mem.bad.push({ x: sPos.x, y: sPos.y });
      mem.apPos = null; sPos = null;
    }
  }
  if (sPos) {
    const sd = site.distance;
    if (sd > 3.0) {
      const aim = followPath(mem, px, py, t, sPos);
      const s = steer(mem, px, py, hdg, aim.x, aim.y, 0.18, rays, t);
      return drive(out, mem, s);
    }
    const b = num(site.bearing, 0), ab = Math.abs(b);
    let v, w;
    if (ab > 45) {
      v = 0; w = clamp(0.012 * b, -0.3, 0.3);
      if (Math.abs(w) < 0.15) w = b >= 0 ? 0.15 : -0.15;
    } else {
      v = clamp(0.08 + 0.08 * (sd - 1.2), 0.08, 0.15) * (1 - ab / 60);
      w = clamp(0.01 * b, -0.3, 0.3);
    }
    if (front < 0.8) v = 0;
    return set(out, mem, v - w, v + w);
  }

  // ---- delivering
  if (needHome) {
    const vmax = dB < 6 ? 0.1 : 0.18;
    const aim = followPath(mem, px, py, t, mem.base);
    const s = steer(mem, px, py, hdg, aim.x, aim.y, vmax, rays, t);
    return drive(out, mem, s);
  }

  // ---- hint / explore task
  updateTask(mem, px, py, t, timeLeft, sci);
  if (!mem.task) {
    const idx = pickHint(mem, px, py);
    if (idx >= 0) {
      const h = mem.hints[idx];
      mem.task = { kind: 'hint', idx: idx, phase: 'go', t0: t, d0: hyp(px, py, h.x, h.y), wps: null, wi: 0, wT: t, ring: 1, sciMax: 0, stuck: 0 };
    } else {
      const e = pickExplore(mem, px, py);
      mem.task = { kind: 'explore', x: e.x, y: e.y, t0: t, stuck: 0 };
    }
    mem.path = null; mem.replan = true;
  }
  const T = currentTarget(mem);
  if (!T || hyp(px, py, T.x, T.y) < T.stopR) return set(out, mem, 0, 0);
  const aim = followPath(mem, px, py, t, T);
  if (mem.planFail >= 4) {
    if (mem.task && mem.task.kind === 'hint') mem.hints[mem.task.idx].fails++;
    mem.task = null; mem.planFail = 0; mem.path = null; mem.replan = true;
    return set(out, mem, 0, 0);
  }
  const s = steer(mem, px, py, hdg, aim.x, aim.y, T.vmax, rays, t);
  return drive(out, mem, s);
}

const D2R = Math.PI / 180, R2D = 180 / Math.PI;
const GN = 200, GC = 2, OCC = 1.5;
const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
const VCRUISE = 0.4;

function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function hyp(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function num(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : d; }
function ci(v) { return clamp(Math.floor(v / GC), 0, GN - 1); }
function near(list, x, y, r) {
  for (let i = 0; i < list.length; i++) if (hyp(list[i].x, list[i].y, x, y) < r) return true;
  return false;
}
function ringWps(cx, cy, r, n, ph) {
  const o = [];
  for (let k = 0; k < n; k++) {
    const a = (k * 360 / n + ph) * D2R;
    o.push({ x: clamp(cx + r * Math.cos(a), 4, 396), y: clamp(cy + r * Math.sin(a), 4, 396) });
  }
  return o;
}

// ---- binary heap
function hpush(hk, hv, k, v) {
  let i = hk.length;
  hk.push(k); hv.push(v);
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (hk[p] <= k) break;
    hk[i] = hk[p]; hv[i] = hv[p]; i = p;
  }
  hk[i] = k; hv[i] = v;
}
function hpop(hk, hv) {
  const top = hv[0];
  const lk = hk.pop(), lv = hv.pop();
  const n = hk.length;
  if (n > 0) {
    let i = 0;
    for (;;) {
      let c = 2 * i + 1;
      if (c >= n) break;
      if (c + 1 < n && hk[c + 1] < hk[c]) c++;
      if (hk[c] >= lk) break;
      hk[i] = hk[c]; hv[i] = hv[c]; i = c;
    }
    hk[i] = lk; hv[i] = lv;
  }
  return top;
}

function nearOcc(L, x, y) {
  if (x > 0 && L[y * GN + x - 1] >= OCC) return true;
  if (x < GN - 1 && L[y * GN + x + 1] >= OCC) return true;
  if (y > 0 && L[(y - 1) * GN + x] >= OCC) return true;
  if (y < GN - 1 && L[(y + 1) * GN + x] >= OCC) return true;
  return false;
}

// A* on occupancy grid; returns world points (excluding start) or null
function plan(L, sx, sy, gx, gy) {
  const s = ci(sy) * GN + ci(sx), g = ci(gy) * GN + ci(gx);
  if (s === g) return [];
  const N = GN * GN;
  const gc = new Float32Array(N).fill(1e9);
  const par = new Int32Array(N).fill(-1);
  const closed = new Uint8Array(N);
  const gxc = g % GN, gyc = (g - gxc) / GN;
  const hk = [], hv = [];
  gc[s] = 0;
  hpush(hk, hv, 0, s);
  let found = false, exp = 0;
  while (hk.length > 0 && exp < 9000) {
    const u = hpop(hk, hv);
    if (closed[u]) continue;
    closed[u] = 1; exp++;
    if (u === g) { found = true; break; }
    const ux = u % GN, uy = (u - ux) / GN;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        const nx = ux + dx, ny = uy + dy;
        if (nx < 0 || ny < 0 || nx >= GN || ny >= GN) continue;
        const v = ny * GN + nx;
        if (closed[v]) continue;
        if (v !== g && L[v] >= OCC) continue;
        if (dx && dy && (L[uy * GN + nx] >= OCC || L[ny * GN + ux] >= OCC)) continue;
        let c = (dx && dy) ? 1.414 : 1;
        if (nearOcc(L, nx, ny)) c += 1.0;
        const ng = gc[u] + c;
        if (ng < gc[v]) {
          gc[v] = ng; par[v] = u;
          const ax = Math.abs(nx - gxc), ay = Math.abs(ny - gyc);
          hpush(hk, hv, ng + Math.max(ax, ay) + 0.414 * Math.min(ax, ay), v);
        }
      }
    }
  }
  if (!found) return null;
  const pts = [];
  let c = g;
  while (c !== s && c !== -1) {
    pts.push({ x: ((c % GN) + 0.5) * GC, y: (Math.floor(c / GN) + 0.5) * GC });
    c = par[c];
  }
  pts.reverse();
  return pts;
}

function mapUpdate(L, px, py, hdg, rays) {
  for (let j = 0; j < 9; j++) {
    const r0 = num(rays[j], 15);
    const hit = r0 < 14.5;
    const r = clamp(r0, 0, 15);
    const a = (hdg + ANG[j]) * D2R;
    const ca = Math.cos(a), sa = Math.sin(a);
    for (let s = 1.0; s < r - 0.5; s += 1.0) {
      const k = ci(py + sa * s) * GN + ci(px + ca * s);
      const nv = L[k] - 0.4;
      L[k] = nv < -2 ? -2 : nv;
    }
    if (hit && r > 1.0) {
      const k = ci(py + sa * r) * GN + ci(px + ca * r);
      const nv = L[k] + 1.0;
      L[k] = nv > 3 ? 3 : nv;
    }
  }
}

function pickHint(mem, px, py) {
  let best = null, bs = -1;
  const b = mem.base;
  for (const h of mem.hints) {
    if (h.done || h.fails >= 2) continue;
    const sc = (Math.max(h.est, 0) + 0.5) / (hyp(px, py, h.x, h.y) + 0.5 * hyp(h.x, h.y, b.x, b.y) + 30);
    if (sc > bs) { bs = sc; best = h; }
  }
  return best;
}

function pickExplore(mem, px, py) {
  let best = { x: 200, y: 200 }, bs = -1e9;
  for (let i = 0; i < 10; i++) {
    const x = 20 + Math.random() * 360, y = 20 + Math.random() * 360;
    let dm = 150;
    for (const v of mem.visited) {
      const d = hyp(x, y, v.x, v.y);
      if (d < dm) dm = d;
    }
    const sc = dm - 0.25 * hyp(x, y, px, py);
    if (sc > bs) { bs = sc; best = { x: x, y: y }; }
  }
  return best;
}

function cmdLR(mem, out, l, r) {
  out.left = clamp(l, -1, 1);
  out.right = clamp(r, -1, 1);
  mem.lastL = out.left; mem.lastR = out.right;
  mem.lastV = (out.left + out.right) / 2;
  mem.lastW = (out.right - out.left) / 2;
  return out;
}

// e: heading error in degrees (positive = target to the left)
function steerCmd(mem, out, e, vmax, rays) {
  const ae = Math.abs(e);
  const rd = j => { const r = num(rays[j], 15); return r < 0.25 ? 15 : r; };
  let v, w;
  if (ae > 55) {
    v = 0; w = e > 0 ? 0.3 : -0.3; mem.ei = 0;
  } else {
    const er = e * D2R;
    mem.ei = clamp(mem.ei + 0.02 * er, -0.2, 0.2);
    w = 0.4 * er + mem.ei;
    if (ae > 3 && Math.abs(w) < 0.08) w = e > 0 ? 0.08 : -0.08;
    v = vmax * (1 - ae / 70);
  }
  const front = Math.min(rd(3), rd(4), rd(5));
  const leftN = Math.min(rd(5), rd(6), rd(7), rd(8));
  const rightN = Math.min(rd(0), rd(1), rd(2), rd(3));
  if (front < 3) v = Math.min(v, vmax * clamp((front - 1) / 2, 0.15, 1));
  if (front < 0.6) v = -0.1;
  else if (front < 1.0) v = Math.min(v, 0.05);
  if (front < 2.0) {
    w += (leftN >= rightN ? 0.25 : -0.25);
  } else {
    if (leftN < 2.5) w -= 0.15;
    if (rightN < 2.5) w += 0.15;
  }
  w = clamp(w, -0.45, 0.45);
  return cmdLR(mem, out, v - w, v + w);
}

function followPath(mem, px, py, t, T) {
  let need = !mem.path || mem.replan || hyp(mem.pgx, mem.pgy, T.x, T.y) > 2.5 || t - mem.planT > 8;
  if (!need && mem.pi < mem.path.length - 1 && t - mem.planT > 2) {
    const a = mem.path[mem.pi];
    if (mem.L[ci(a.y) * GN + ci(a.x)] >= OCC) need = true;
  }
  if (need) {
    const P = plan(mem.L, px, py, T.x, T.y);
    if (P === null) { mem.path = [{ x: T.x, y: T.y }]; mem.planFail++; }
    else { mem.path = P.concat([{ x: T.x, y: T.y }]); mem.planFail = 0; }
    mem.pi = 0; mem.pgx = T.x; mem.pgy = T.y; mem.planT = t; mem.replan = false;
  }
  const P = mem.path;
  while (mem.pi < P.length - 1 && hyp(px, py, P[mem.pi].x, P[mem.pi].y) < 2.0) mem.pi++;
  return P[mem.pi];
}

function navStep(mem, out, px, py, t, T, vmax, rays) {
  const dT = hyp(px, py, T.x, T.y);
  const aim = followPath(mem, px, py, t, T);
  const e = wrap(Math.atan2(aim.y - py, aim.x - px) * R2D - mem.hdg);
  const v = Math.min(vmax, 0.08 + 0.1 * dT);
  return steerCmd(mem, out, e, v, rays);
}

function newTask(mem, px, py, t) {
  const h = pickHint(mem, px, py);
  if (h) {
    mem.task = { kind: 'hint', h: h, phase: 'go', t0: t, d0: hyp(px, py, h.x, h.y), wps: null, wi: 0, wT: t, ring: 1, sciMax: 0, esc: 0 };
  } else {
    const e = pickExplore(mem, px, py);
    mem.task = { kind: 'explore', x: e.x, y: e.y, t0: t, esc: 0 };
  }
  mem.path = null; mem.replan = true;
}

function taskTarget(mem, px, py, t, timeLeft, sci) {
  for (let guard = 0; guard < 3; guard++) {
    const k = mem.task;
    if (!k) return null;
    if (k.kind === 'explore') {
      if (hyp(px, py, k.x, k.y) < 4 || t - k.t0 > 120) {
        mem.task = null; mem.path = null; mem.replan = true; return null;
      }
      if (sci > 0.35 && mem.dyn < 6 && !near(mem.hints, px, py, 12)) {
        mem.dyn++;
        mem.task = { kind: 'hint', h: { x: px, y: py, est: 0, fails: 0, done: false }, phase: 'ring', t0: t, d0: 0,
          wps: ringWps(px, py, 5, 8, 0), wi: 0, wT: t, ring: 1, sciMax: 0, esc: 0 };
        mem.path = null; mem.replan = true;
        continue;
      }
      return { x: k.x, y: k.y, stopR: 3, vmax: VCRUISE };
    }
    const h = k.h;
    if (h.done || h.fails >= 2) { mem.task = null; mem.path = null; mem.replan = true; return null; }
    if (k.phase === 'go') {
      const d = hyp(px, py, h.x, h.y);
      if (d < 3.5) {
        k.phase = 'ring'; k.wps = ringWps(h.x, h.y, 5, 8, 0); k.wi = 0; k.wT = t;
        mem.path = null; mem.replan = true;
        continue;
      }
      if (t - k.t0 > 60 + k.d0 / 0.15) {
        h.fails++; mem.task = null; mem.path = null; mem.replan = true; return null;
      }
      return { x: h.x, y: h.y, stopR: 3.5, vmax: VCRUISE };
    }
    // ring search
    k.sciMax = Math.max(k.sciMax, sci);
    while (k.wi < k.wps.length) {
      const w = k.wps[k.wi];
      if (hyp(px, py, w.x, w.y) < 2.2 || t - k.wT > 40) {
        k.wi++; k.wT = t; mem.path = null; mem.replan = true;
      } else break;
    }
    if (k.wi >= k.wps.length) {
      if (k.ring === 1 && k.sciMax > 0.3 && timeLeft > 450) {
        k.ring = 2; k.wps = ringWps(h.x, h.y, 11, 10, 0.3); k.wi = 0; k.wT = t;
        mem.path = null; mem.replan = true;
        continue;
      }
      h.done = true; mem.task = null; mem.path = null; mem.replan = true;
      return null;
    }
    const w = k.wps[k.wi];
    return { x: w.x, y: w.y, stopR: 1.0, vmax: 0.3 };
  }
  return null;
}

function initMem(obs, mem) {
  const M = obs.mission || {};
  const x0 = num(obs.x, 200), y0 = num(obs.y, 200);
  const b = M.base || { x: x0, y: y0 };
  mem.base = { x: num(b.x, x0), y: num(b.y, y0) };
  mem.cap = num(M.capacity, 5);
  mem.hints = (Array.isArray(M.hints) ? M.hints : []).map(h => ({
    x: num(h.x, 200), y: num(h.y, 200), est: num(h.estimate, 1), fails: 0, done: false
  }));
  mem.L = new Float32Array(GN * GN);
  mem.done = []; mem.bad = []; mem.visited = [];
  mem.mode = 'move'; mem.task = null; mem.ap = null; mem.goHome = false; mem.homeBlock = -1; mem.dockT0 = 0;
  mem.path = null; mem.pi = 0; mem.pgx = -1e9; mem.pgy = -1e9; mem.planT = -99; mem.replan = true; mem.planFail = 0;
  mem.ex = x0; mem.ey = y0; mem.glx = undefined; mem.gly = undefined; mem.gStill = 0;
  mem.bias = 0; mem.anc = { x: x0, y: y0 }; mem.segOK = false;
  mem.lastV = 0; mem.lastW = 0; mem.lastL = 0; mem.lastR = 0; mem.ei = 0;
  mem.sa = { x: x0, y: y0, t: 0 }; mem.bumpT = -99; mem.escT = 0; mem.escDir = 1; mem.nEsc = 0;
  mem.drT0 = 0; mem.dsx = x0; mem.dsy = y0; mem.dsPx = x0; mem.dsPy = y0;
  mem.lastVisit = -99; mem.dyn = 0; mem.tk = 0; mem.hdg = 0; mem.init = true;
}

function act(obs, mem) {
  const out = { left: 0, right: 0, drill: false };
  if (!mem.init) initMem(obs, mem);
  mem.tk++;
  const t = num(obs.t, mem.tk * 0.1);
  const timeLeft = num(obs.timeLeft, 1200 - t);
  const bat = num(obs.battery, 1);
  const carried = num(obs.carried, 0);
  const cap = mem.cap;
  const vW = (num(obs.wheelLeft, 0) + num(obs.wheelRight, 0)) / 2;
  const hraw = num(obs.heading, 0);
  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  const rd = j => { const r = num(rays[j], 15); return r < 0.25 ? 15 : r; };
  const sci = num(obs.science, 0);
  const site = (obs.site && typeof obs.site.distance === 'number') ? obs.site : null;
  const lastV = mem.lastV, lastW = mem.lastW;

  // ---- localisation: wheel dead reckoning fused with GPS
  const hPrev = wrap(hraw + mem.bias) * D2R;
  mem.ex += vW * 0.1 * Math.cos(hPrev);
  mem.ey += vW * 0.1 * Math.sin(hPrev);
  const gx = num(obs.x, NaN), gy = num(obs.y, NaN);
  if (isFinite(gx) && isFinite(gy)) {
    if (gx !== mem.glx || gy !== mem.gly) {
      const jx = gx - mem.ex, jy = gy - mem.ey;
      const g = Math.hypot(jx, jy) > 10 ? 0.3 : 0.4;
      mem.ex += g * jx; mem.ey += g * jy;
      mem.glx = gx; mem.gly = gy; mem.gStill = 0;
    } else mem.gStill++;
  }
  const px = mem.ex, py = mem.ey;

  // ---- compass bias from GPS course on straight runs
  const straight = lastV > 0.12 && Math.abs(lastW) < 0.1;
  if (!straight) mem.segOK = false;
  if (hyp(px, py, mem.anc.x, mem.anc.y) > 5) {
    if (mem.segOK && mem.gStill < 15) {
      const course = Math.atan2(py - mem.anc.y, px - mem.anc.x) * R2D;
      const diff = wrap(course - hraw);
      const d = clamp(wrap(diff - mem.bias), -20, 20);
      mem.bias = wrap(mem.bias + 0.3 * d);
    }
    mem.anc = { x: px, y: py }; mem.segOK = true;
  }
  const hdg = wrap(hraw + mem.bias), hr = hdg * D2R;
  mem.hdg = hdg;
  const dB = hyp(px, py, mem.base.x, mem.base.y);

  if (t - mem.lastVisit > 15) { mem.lastVisit = t; mem.visited.push({ x: px, y: py }); }
  if (mem.gStill < 40) mapUpdate(mem.L, px, py, hdg, rays);

  // ---- stall / bump detection (position only)
  const moving = lastV > 0.1 || Math.abs(lastW) > 0.15;
  if (!moving || hyp(px, py, mem.sa.x, mem.sa.y) > 0.6) mem.sa = { x: px, y: py, t: t };
  const bumped = obs.bumped === true && t - mem.bumpT > 2;
  if (bumped) mem.bumpT = t;
  const stalled = moving && t - mem.sa.t > 8;
  if (mem.mode === 'move' && (bumped || stalled)) {
    mem.mode = 'esc'; mem.escT = t;
    let lo = 0, ro = 0;
    for (let j = 5; j < 9; j++) lo += Math.min(rd(j), 6);
    for (let j = 0; j < 4; j++) ro += Math.min(rd(j), 6);
    mem.escDir = lo >= ro ? 1 : -1;
    for (const d of [1.5, 2.5]) {
      const k = ci(py + d * Math.sin(hr)) * GN + ci(px + d * Math.cos(hr));
      mem.L[k] = 3;
    }
    mem.path = null; mem.replan = true; mem.nEsc++;
    if (mem.ap) { mem.bad.push({ x: mem.ap.x, y: mem.ap.y }); mem.ap = null; }
    if (mem.task) {
      mem.task.esc = (mem.task.esc || 0) + 1;
      if (mem.task.esc >= 3) {
        if (mem.task.kind === 'hint') mem.task.h.fails++;
        mem.task = null;
      }
    }
    return cmdLR(mem, out, -0.25, -0.25);
  }

  // ---- escape manoeuvre: back off, then turn toward open side
  if (mem.mode === 'esc') {
    const el = t - mem.escT;
    if (el < 1.6) return cmdLR(mem, out, -0.25, -0.25);
    if (el < 3.4) { const s = 0.35 * mem.escDir; return cmdLR(mem, out, -s, s); }
    mem.mode = 'move'; mem.sa = { x: px, y: py, t: t }; mem.ei = 0; mem.path = null; mem.replan = true;
    return cmdLR(mem, out, 0, 0);
  }

  // ---- drilling: hold still for 6 s
  if (mem.mode === 'drill') {
    const dr = num(obs.drilling, 0);
    if (dr >= 6) {
      mem.done.push({ x: mem.dsx, y: mem.dsy });
      for (const h of mem.hints) if (hyp(h.x, h.y, mem.dsx, mem.dsy) < 10) h.done = true;
      mem.mode = 'move'; mem.ap = null; mem.path = null; mem.replan = true;
      mem.sa = { x: px, y: py, t: t };
      return cmdLR(mem, out, 0, 0);
    }
    if (t - mem.drT0 > 16 || hyp(px, py, mem.dsPx, mem.dsPy) > 1.8) {
      mem.bad.push({ x: mem.dsx, y: mem.dsy });
      mem.mode = 'move'; mem.ap = null; mem.path = null; mem.replan = true;
      mem.sa = { x: px, y: py, t: t };
      return cmdLR(mem, out, 0, 0);
    }
    out.drill = true;
    const u = clamp(-1.5 * vW + 0.015 * num(obs.pitch, 0), -0.25, 0.25);
    return cmdLR(mem, out, u, u);
  }

  // ---- docked at base: unload, maybe charge
  if (mem.mode === 'dock') {
    const w = t - mem.dockT0;
    let stay = false;
    if (carried > 0 && w < 15) stay = true;
    else if (carried === 0 && bat < 0.4 && timeLeft > 200 && w < 80) stay = true;
    if (!stay) {
      mem.mode = 'move'; mem.goHome = false; mem.homeBlock = t + 20;
      mem.task = null; mem.path = null; mem.replan = true; mem.ap = null;
      mem.sa = { x: px, y: py, t: t };
    }
    return cmdLR(mem, out, 0, 0);
  }

  // ---- go-home decision
  if (!mem.goHome && carried > 0 && t >= mem.homeBlock) {
    const openH = mem.hints.some(h => !h.done && h.fails < 2);
    if (carried >= cap || (dB < 35 && carried >= 1) || (carried >= 3 && dB < 120) ||
        (!openH && carried >= 1) || timeLeft < dB / 0.3 + 100 || bat < 0.15 + 0.0008 * dB) {
      mem.goHome = true; mem.ap = null; mem.path = null; mem.replan = true;
    }
  }
  if (mem.goHome && (dB < 2.6 || obs.docked === true)) {
    mem.mode = 'dock'; mem.dockT0 = t; mem.path = null;
    return cmdLR(mem, out, 0, 0);
  }

  // ---- site sensor: approach and drill
  if (mem.goHome) mem.ap = null;
  if (!mem.goHome && site && site.distance <= 8.5 && carried < cap) {
    const b = num(site.bearing, 0);
    const a = (hdg + b) * D2R;
    const sx = px + site.distance * Math.cos(a), sy = py + site.distance * Math.sin(a);
    if (!near(mem.done, sx, sy, 4) && !near(mem.bad, sx, sy, 3)) {
      if (!mem.ap || hyp(mem.ap.x, mem.ap.y, sx, sy) > 6) {
        mem.ap = { x: sx, y: sy, seen: t, d: site.distance, b: b, best: site.distance, bestT: t };
      }
      const ap = mem.ap;
      ap.x = sx; ap.y = sy; ap.seen = t; ap.d = site.distance; ap.b = b;
      if (site.distance < ap.best - 0.3) { ap.best = site.distance; ap.bestT = t; }
    }
  }
  if (mem.ap && (t - mem.ap.seen > 6 || t - mem.ap.bestT > 15)) {
    mem.bad.push({ x: mem.ap.x, y: mem.ap.y });
    mem.ap = null;
  }
  if (mem.ap) {
    const ap = mem.ap;
    const vis = ap.seen === t;
    if (vis && ap.d <= 1.3) {
      mem.mode = 'drill'; mem.drT0 = t;
      mem.dsx = ap.x; mem.dsy = ap.y; mem.dsPx = px; mem.dsPy = py;
      mem.ap = null;
      out.drill = true;
      return cmdLR(mem, out, 0, 0);
    }
    if (vis) {
      const v = clamp(0.1 + 0.08 * (ap.d - 1.3), 0.12, 0.3);
      return steerCmd(mem, out, ap.b, v, rays);
    }
    if (hyp(px, py, ap.x, ap.y) < 0.8) return cmdLR(mem, out, 0, 0);
    return navStep(mem, out, px, py, t, { x: ap.x, y: ap.y }, 0.15, rays);
  }

  // ---- navigation: home or hint/explore task
  let T = null;
  if (mem.goHome) {
    T = { x: mem.base.x, y: mem.base.y, stopR: 2.2, vmax: 0.35 };
  } else {
    if (!mem.task) newTask(mem, px, py, t);
    T = taskTarget(mem, px, py, t, timeLeft, sci);
  }
  if (!T) { mem.task = null; return cmdLR(mem, out, 0, 0); }
  if (hyp(px, py, T.x, T.y) < T.stopR) return cmdLR(mem, out, 0, 0);
  const res = navStep(mem, out, px, py, t, T, T.vmax, rays);
  if (mem.planFail >= 3) {
    if (!mem.goHome && mem.task && mem.task.kind === 'hint') mem.task.h.fails++;
    if (!mem.goHome) mem.task = null;
    mem.planFail = 0; mem.path = null; mem.replan = true;
    return cmdLR(mem, out, 0, 0);
  }
  return res;
}

const D2R = Math.PI / 180, R2D = 180 / Math.PI;
const GN = 200, GC = 2, OCC = 1.5;
const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
const VC = 0.22;

function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function hyp(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function num(v, d) { return (typeof v === 'number' && isFinite(v)) ? v : d; }
function ci(v) { return clamp(Math.floor(v / GC), 0, GN - 1); }
function near(list, x, y, r) {
  for (let i = 0; i < list.length; i++) if (hyp(list[i].x, list[i].y, x, y) < r) return true;
  return false;
}
function ringWps(cx, cy, r, n, ph) {
  const o = [];
  for (let k = 0; k < n; k++) {
    const a = (k * 360 / n + ph) * D2R;
    o.push({ x: clamp(cx + r * Math.cos(a), 3, 397), y: clamp(cy + r * Math.sin(a), 3, 397) });
  }
  return o;
}

// ---- binary heap
function hpush(hk, hv, k, v) {
  let i = hk.length;
  hk.push(k); hv.push(v);
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (hk[p] <= k) break;
    hk[i] = hk[p]; hv[i] = hv[p]; i = p;
  }
  hk[i] = k; hv[i] = v;
}
function hpop(hk, hv) {
  const top = hv[0];
  const lk = hk.pop(), lv = hv.pop();
  const n = hk.length;
  if (n > 0) {
    let i = 0;
    for (;;) {
      let c = 2 * i + 1;
      if (c >= n) break;
      if (c + 1 < n && hk[c + 1] < hk[c]) c++;
      if (hk[c] >= lk) break;
      hk[i] = hk[c]; hv[i] = hv[c]; i = c;
    }
    hk[i] = lk; hv[i] = lv;
  }
  return top;
}

function nearOcc(L, x, y) {
  if (x > 0 && L[y * GN + x - 1] >= OCC) return true;
  if (x < GN - 1 && L[y * GN + x + 1] >= OCC) return true;
  if (y > 0 && L[(y - 1) * GN + x] >= OCC) return true;
  if (y < GN - 1 && L[(y + 1) * GN + x] >= OCC) return true;
  return false;
}

// A* on occupancy grid; returns world points (excluding start) or null
function plan(L, sx, sy, gx, gy) {
  const s = ci(sy) * GN + ci(sx), g = ci(gy) * GN + ci(gx);
  if (s === g) return [];
  const N = GN * GN;
  const gc = new Float32Array(N).fill(1e9);
  const par = new Int32Array(N).fill(-1);
  const closed = new Uint8Array(N);
  const gxc = g % GN, gyc = (g - gxc) / GN;
  const hk = [], hv = [];
  gc[s] = 0;
  hpush(hk, hv, 0, s);
  let found = false, exp = 0;
  while (hk.length > 0 && exp < 12000) {
    const u = hpop(hk, hv);
    if (closed[u]) continue;
    closed[u] = 1; exp++;
    if (u === g) { found = true; break; }
    const ux = u % GN, uy = (u - ux) / GN;
    for (let dy = -1; dy <= 1; dy++) {
      for (let dx = -1; dx <= 1; dx++) {
        if (dx === 0 && dy === 0) continue;
        const nx = ux + dx, ny = uy + dy;
        if (nx < 0 || ny < 0 || nx >= GN || ny >= GN) continue;
        const v = ny * GN + nx;
        if (closed[v]) continue;
        if (v !== g && L[v] >= OCC) continue;
        if (dx && dy && (L[uy * GN + nx] >= OCC || L[ny * GN + ux] >= OCC)) continue;
        let c = (dx && dy) ? 1.414 : 1;
        if (nearOcc(L, nx, ny)) c += 1.0;
        const ng = gc[u] + c;
        if (ng < gc[v]) {
          gc[v] = ng; par[v] = u;
          const ax = Math.abs(nx - gxc), ay = Math.abs(ny - gyc);
          hpush(hk, hv, ng + Math.max(ax, ay) + 0.414 * Math.min(ax, ay), v);
        }
      }
    }
  }
  if (!found) return null;
  const pts = [];
  let c = g;
  while (c !== s && c !== -1) {
    pts.push({ x: ((c % GN) + 0.5) * GC, y: (Math.floor(c / GN) + 0.5) * GC });
    c = par[c];
  }
  pts.reverse();
  return pts;
}

function mapUpdate(L, px, py, hdg, rays) {
  for (let j = 0; j < 9; j++) {
    const r0 = num(rays[j], 15);
    const hit = r0 < 14.5;
    const r = clamp(r0, 0, 15);
    const a = (hdg + ANG[j]) * D2R;
    const ca = Math.cos(a), sa = Math.sin(a);
    for (let s = 1.0; s < r - 0.5; s += 1.0) {
      const k = ci(py + sa * s) * GN + ci(px + ca * s);
      const nv = L[k] - 0.4;
      L[k] = nv < -2 ? -2 : nv;
    }
    if (hit && r > 1.0) {
      const k = ci(py + sa * r) * GN + ci(px + ca * r);
      const nv = L[k] + 1.0;
      L[k] = nv > 3 ? 3 : nv;
    }
  }
}

function pickHint(mem, px, py) {
  let best = null, bs = -1;
  const b = mem.base;
  for (const h of mem.hints) {
    if (h.done || h.fails >= 2) continue;
    const sc = (Math.max(h.est, 0) + 0.5) / (hyp(px, py, h.x, h.y) + 0.5 * hyp(h.x, h.y, b.x, b.y) + 30);
    if (sc > bs) { bs = sc; best = h; }
  }
  return best;
}

function pickExplore(mem, px, py) {
  let best = { x: 200, y: 200 }, bs = -1e9;
  for (let i = 0; i < 10; i++) {
    const x = 20 + Math.random() * 360, y = 20 + Math.random() * 360;
    let dm = 150;
    for (const v of mem.visited) {
      const d = hyp(x, y, v.x, v.y);
      if (d < dm) dm = d;
    }
    const sc = dm - 0.25 * hyp(x, y, px, py);
    if (sc > bs) { bs = sc; best = { x: x, y: y }; }
  }
  return best;
}

function cmd(out, mem, l, r) {
  out.left = clamp(num(l, 0), -1, 1);
  out.right = clamp(num(r, 0), -1, 1);
  mem.lastV = (out.left + out.right) / 2;
  mem.lastW = (out.right - out.left) / 2;
  return out;
}

// heading-error steering toward (ax, ay) with obstacle reaction
function steer(mem, out, px, py, hdg, ax, ay, vmax, rays) {
  const rd = j => { const r = num(rays[j], 15); return r < 0.25 ? 15 : r; };
  const e = wrap(Math.atan2(ay - py, ax - px) * R2D - hdg);
  const ae = Math.abs(e);
  let w = clamp(0.15 * e * D2R, -0.3, 0.3);
  if (ae > 5 && Math.abs(w) < 0.1) w = e > 0 ? 0.1 : -0.1;
  let v = vmax * clamp(1 - ae / 50, 0, 1);
  const front = Math.min(rd(3), rd(4), rd(5));
  const Ln = Math.min(rd(5), rd(6), rd(7), rd(8));
  const Rn = Math.min(rd(0), rd(1), rd(2), rd(3));
  if (front < 2.5) v = Math.min(v, vmax * clamp((front - 0.6) / 1.9, 0, 1));
  if (front < 0.8) w += (Ln >= Rn ? 0.25 : -0.25);
  w = clamp(w, -0.4, 0.4);
  return cmd(out, mem, v - w, v + w);
}

// bearing servo for the final approach to a visible site
function servo(mem, out, sd, b, front) {
  const br = b * D2R;
  let v = clamp(0.1 + 0.1 * (sd - 1.2), 0.1, 0.2);
  if (Math.abs(b) > 40) v = 0;
  else v *= clamp(1 - Math.abs(b) / 50, 0, 1);
  if (front < 0.5) v = 0;
  let w = clamp(0.2 * br, -0.3, 0.3);
  if (Math.abs(b) > 5 && Math.abs(w) < 0.1) w = b > 0 ? 0.1 : -0.1;
  return cmd(out, mem, v - w, v + w);
}

function followPath(mem, px, py, t, T) {
  let need = !mem.path || mem.replan || hyp(mem.pgx, mem.pgy, T.x, T.y) > 2.5 || t - mem.planT > 8;
  if (!need && mem.pi < mem.path.length - 1 && t - mem.planT > 2) {
    const a = mem.path[mem.pi];
    if (mem.L[ci(a.y) * GN + ci(a.x)] >= OCC) need = true;
  }
  if (need) {
    const P = plan(mem.L, px, py, T.x, T.y);
    if (P === null) { mem.path = [{ x: T.x, y: T.y }]; mem.planFail++; }
    else { mem.path = P.concat([{ x: T.x, y: T.y }]); mem.planFail = 0; }
    mem.pi = 0; mem.pgx = T.x; mem.pgy = T.y; mem.planT = t; mem.replan = false;
  }
  const P = mem.path;
  while (mem.pi < P.length - 1 && hyp(px, py, P[mem.pi].x, P[mem.pi].y) < 2.0) mem.pi++;
  return P[mem.pi];
}

function navStep(mem, out, px, py, t, T, vmax, rays, hdg) {
  if (mem.planFail >= 3) {
    if (mem.task && mem.task.kind === 'hint') mem.task.h.fails++;
    mem.task = null; mem.planFail = 0; mem.path = null; mem.replan = true;
    return cmd(out, mem, 0, 0);
  }
  const aim = followPath(mem, px, py, t, T);
  return steer(mem, out, px, py, hdg, aim.x, aim.y, vmax, rays);
}

function newTask(mem, px, py, t) {
  const h = pickHint(mem, px, py);
  if (h) {
    mem.task = { kind: 'hint', h: h, phase: 'go', t0: t, d0: hyp(px, py, h.x, h.y), wps: null, wi: 0, wT: t, ring: 1, sciMax: 0, esc: 0 };
  } else {
    const e = pickExplore(mem, px, py);
    mem.task = { kind: 'explore', x: e.x, y: e.y, t0: t, esc: 0 };
  }
  mem.path = null; mem.replan = true;
}

function taskTarget(mem, px, py, t, timeLeft, sci) {
  for (let guard = 0; guard < 3; guard++) {
    const k = mem.task;
    if (!k) return null;
    if (k.kind === 'explore') {
      if (hyp(px, py, k.x, k.y) < 4 || t - k.t0 > 120) {
        mem.task = null; mem.path = null; mem.replan = true; return null;
      }
      if (sci > 0.5 && mem.dyn < 6 && !near(mem.hints, px, py, 12)) {
        mem.dyn++;
        const h = { x: px, y: py, est: 1, fails: 0, done: false };
        mem.hints.push(h);
        mem.task = { kind: 'hint', h: h, phase: 'ring', t0: t, d0: 0, wps: ringWps(px, py, 5, 8, 0), wi: 0, wT: t, ring: 1, sciMax: 0, esc: 0 };
        mem.path = null; mem.replan = true;
        continue;
      }
      return { x: k.x, y: k.y, stopR: 3, vmax: VC };
    }
    const h = k.h;
    if (h.done || h.fails >= 2) { mem.task = null; mem.path = null; mem.replan = true; return null; }
    if (k.phase === 'go') {
      const d = hyp(px, py, h.x, h.y);
      if (d < 4) {
        k.phase = 'ring'; k.wps = ringWps(h.x, h.y, 6, 8, 0); k.wi = 0; k.wT = t;
        mem.path = null; mem.replan = true;
        continue;
      }
      if (t - k.t0 > 60 + k.d0 / 0.2) {
        h.fails++; mem.task = null; mem.path = null; mem.replan = true; return null;
      }
      return { x: h.x, y: h.y, stopR: 3.5, vmax: VC };
    }
    k.sciMax = Math.max(k.sciMax, sci);
    while (k.wi < k.wps.length) {
      const w = k.wps[k.wi];
      if (hyp(px, py, w.x, w.y) < 2.0 || t - k.wT > 40) {
        k.wi++; k.wT = t; mem.path = null; mem.replan = true;
      } else break;
    }
    if (k.wi >= k.wps.length) {
      if (k.ring === 1 && k.sciMax > 0.3 && timeLeft > 400) {
        k.ring = 2; k.wps = ringWps(h.x, h.y, 11, 10, 0.3); k.wi = 0; k.wT = t;
        mem.path = null; mem.replan = true;
        continue;
      }
      h.done = true; mem.task = null; mem.path = null; mem.replan = true;
      return null;
    }
    const w = k.wps[k.wi];
    return { x: w.x, y: w.y, stopR: 1.0, vmax: 0.18 };
  }
  return null;
}

function initMem(obs, mem) {
  const M = obs.mission || {};
  const x0 = num(obs.x, 200), y0 = num(obs.y, 200);
  const b = M.base || { x: x0, y: y0 };
  mem.base = { x: num(b.x, x0), y: num(b.y, y0) };
  mem.cap = num(M.capacity, 5);
  mem.hints = (Array.isArray(M.hints) ? M.hints : []).map(h => ({
    x: num(h.x, 200), y: num(h.y, 200), est: num(h.estimate, 1), fails: 0, done: false
  }));
  mem.L = new Float32Array(GN * GN);
  mem.done = []; mem.bad = []; mem.visited = [];
  mem.px = x0; mem.py = y0; mem.glx = undefined; mem.gly = undefined; mem.gStill = 0;
  mem.bias = 0; mem.anc = { x: x0, y: y0 };
  mem.lastV = 0; mem.lastW = 0;
  mem.mode = 'nav'; mem.task = null; mem.ap = null;
  mem.path = null; mem.pi = 0; mem.pgx = -1e9; mem.pgy = -1e9; mem.planT = -99; mem.replan = true; mem.planFail = 0;
  mem.goHome = false; mem.homeBlock = -1; mem.dockT0 = 0;
  mem.sa = { x: x0, y: y0, t: 0 }; mem.bumpT = -99; mem.escT = 0; mem.escDir = 1; mem.escN = 0;
  mem.drT0 = 0; mem.dsx = x0; mem.dsy = y0; mem.dsPx = x0; mem.dsPy = y0;
  mem.visitT = -99; mem.dyn = 0; mem.tk = 0; mem.hdg = 0; mem.nSamp = 0; mem.init = true;
}

function act(obs, mem) {
  const out = { left: 0, right: 0, drill: false };
  if (!mem.init) initMem(obs, mem);
  mem.tk++;
  const t = num(obs.t, mem.tk * 0.1);
  const timeLeft = num(obs.timeLeft, 1200 - t);
  const bat = num(obs.battery, 1);
  const carried = num(obs.carried, 0);
  const cap = mem.cap;
  const vW = (num(obs.wheelLeft, 0) + num(obs.wheelRight, 0)) / 2;
  const hraw = num(obs.heading, 0);
  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  const rd = j => { const r = num(rays[j], 15); return r < 0.25 ? 15 : r; };
  const front = Math.min(rd(3), rd(4), rd(5));
  const sci = num(obs.science, 0);
  const site = (obs.site && typeof obs.site.distance === 'number') ? obs.site : null;

  // ---- localisation: wheel dead reckoning blended with GPS
  const hP = wrap(hraw + mem.bias) * D2R;
  mem.px += vW * 0.1 * Math.cos(hP);
  mem.py += vW * 0.1 * Math.sin(hP);
  const gx = num(obs.x, NaN), gy = num(obs.y, NaN);
  if (isFinite(gx) && isFinite(gy)) {
    if (gx !== mem.glx || gy !== mem.gly) {
      const jx = gx - mem.px, jy = gy - mem.py;
      const g = Math.hypot(jx, jy) > 10 ? 0.2 : 0.4;
      mem.px += g * jx; mem.py += g * jy;
      mem.glx = gx; mem.gly = gy; mem.gStill = 0;
    } else mem.gStill++;
  }
  const px = mem.px, py = mem.py;

  // ---- compass bias from GPS course on straight legs
  if (mem.lastV > 0.12 && Math.abs(mem.lastW) < 0.15 && mem.gStill < 15) {
    const dA = hyp(px, py, mem.anc.x, mem.anc.y);
    if (dA > 6) {
      const course = Math.atan2(py - mem.anc.y, px - mem.anc.x) * R2D;
      const d = clamp(wrap(wrap(course - hraw) - mem.bias), -25, 25);
      mem.bias = wrap(mem.bias + 0.25 * d);
      mem.anc = { x: px, y: py };
    }
  } else {
    mem.anc = { x: px, y: py };
  }
  const hdg = wrap(hraw + mem.bias);
  mem.hdg = hdg;
  const dB = hyp(px, py, mem.base.x, mem.base.y);

  if (t - mem.visitT > 15) { mem.visitT = t; mem.visited.push({ x: px, y: py }); }
  if (mem.gStill < 40) mapUpdate(mem.L, px, py, hdg, rays);

  // ---- bump / stall detection (position only)
  if (mem.mode !== 'nav' || hyp(px, py, mem.sa.x, mem.sa.y) > 1.0) mem.sa = { x: px, y: py, t: t };
  const bumped = obs.bumped === true && t - mem.bumpT > 2;
  if (bumped) mem.bumpT = t;
  const moveCmd = mem.lastV > 0.05 || Math.abs(mem.lastW) > 0.05;
  const stalled = moveCmd && t - mem.sa.t > 8;
  if (mem.mode === 'nav' && (bumped || stalled)) {
    mem.mode = 'esc'; mem.escT = t; mem.escN++;
    let lo = 0, ro = 0;
    for (let j = 5; j < 9; j++) lo += Math.min(rd(j), 6);
    for (let j = 0; j < 4; j++) ro += Math.min(rd(j), 6);
    mem.escDir = lo >= ro ? 1 : -1;
    const hr = hdg * D2R;
    for (const d of [1.5, 2.5]) {
      const k = ci(py + d * Math.sin(hr)) * GN + ci(px + d * Math.cos(hr));
      mem.L[k] = Math.max(mem.L[k], 2);
    }
    if (mem.ap) { mem.bad.push({ x: mem.ap.x, y: mem.ap.y }); mem.ap = null; }
    if (mem.task) {
      mem.task.esc = (mem.task.esc || 0) + 1;
      if (mem.task.esc >= 3) {
        if (mem.task.kind === 'hint') mem.task.h.fails++;
        mem.task = null;
      }
    }
    mem.path = null; mem.replan = true;
  }

  // ---- escape: back off, then turn toward the open side
  if (mem.mode === 'esc') {
    const el = t - mem.escT;
    if (el < 2.0) return cmd(out, mem, -0.25, -0.25);
    if (el < 3.6) { const s = 0.35 * mem.escDir; return cmd(out, mem, -s, s); }
    mem.mode = 'nav'; mem.sa = { x: px, y: py, t: t }; mem.path = null; mem.replan = true;
    return cmd(out, mem, 0, 0);
  }

  // ---- drilling: hold still for 6 s
  if (mem.mode === 'drill') {
    out.drill = true;
    const dr = num(obs.drilling, 0);
    if (dr >= 6) {
      mem.done.push({ x: mem.dsx, y: mem.dsy });
      mem.nSamp++;
      for (const h of mem.hints) if (hyp(h.x, h.y, mem.dsx, mem.dsy) < 8) h.done = true;
      mem.mode = 'nav'; mem.ap = null; mem.path = null; mem.replan = true;
      mem.sa = { x: px, y: py, t: t };
      out.drill = false;
      return cmd(out, mem, 0, 0);
    }
    if (t - mem.drT0 > 14 || hyp(px, py, mem.dsPx, mem.dsPy) > 2.0) {
      mem.bad.push({ x: mem.dsx, y: mem.dsy });
      mem.mode = 'nav'; mem.ap = null; mem.path = null; mem.replan = true;
      mem.sa = { x: px, y: py, t: t };
      out.drill = false;
      return cmd(out, mem, 0, 0);
    }
    const u = clamp(-1.5 * vW + 0.02 * num(obs.pitch, 0), -0.2, 0.2);
    return cmd(out, mem, u, u);
  }

  // ---- docked at base: unload, maybe charge
  if (mem.mode === 'dock') {
    const w = t - mem.dockT0;
    const stay = (carried > 0 && w < 12) || (carried === 0 && bat < 0.35 && timeLeft > 200 && w < 60);
    if (!stay) {
      mem.mode = 'nav'; mem.goHome = false; mem.homeBlock = t + 15;
      mem.task = null; mem.ap = null; mem.path = null; mem.replan = true;
      mem.sa = { x: px, y: py, t: t };
    }
    return cmd(out, mem, 0, 0);
  }

  // ---- decide to go home
  const openH = mem.hints.some(h => !h.done && h.fails < 2);
  if (carried === 0) mem.goHome = false;
  if (!mem.goHome && carried > 0 && t >= mem.homeBlock) {
    if (carried >= cap || timeLeft < dB / 0.3 + 90 || (!openH && carried >= 1) ||
        (carried >= 2 && dB < 40) || dB < 12 || bat < 0.15 + 0.0006 * dB) {
      mem.goHome = true; mem.ap = null; mem.path = null; mem.replan = true;
    }
  }
  if (mem.goHome && (dB < 2.2 || obs.docked === true)) {
    mem.mode = 'dock'; mem.dockT0 = t; mem.path = null; mem.ap = null;
    return cmd(out, mem, 0, 0);
  }

  // ---- site sensor: approach and drill
  let sPos = null;
  if (site && !mem.goHome && carried < cap && site.distance <= 8.5) {
    const b = num(site.bearing, 0);
    const a = (hdg + b) * D2R;
    const sx = px + site.distance * Math.cos(a), sy = py + site.distance * Math.sin(a);
    if (!near(mem.done, sx, sy, 3) && !near(mem.bad, sx, sy, 3)) {
      sPos = { x: sx, y: sy, d: site.distance, b: b };
    }
  }
  if (sPos) {
    if (!mem.ap || hyp(mem.ap.x, mem.ap.y, sPos.x, sPos.y) > 5) {
      mem.ap = { x: sPos.x, y: sPos.y, t0: t, bestD: sPos.d, bestT: t };
    }
    const ap = mem.ap;
    ap.x = sPos.x; ap.y = sPos.y;
    if (sPos.d < ap.bestD - 0.3) { ap.bestD = sPos.d; ap.bestT = t; }
    if (sPos.d <= 1.35) {
      mem.mode = 'drill'; mem.drT0 = t;
      mem.dsx = sPos.x; mem.dsy = sPos.y; mem.dsPx = px; mem.dsPy = py;
      mem.ap = null;
      out.drill = true;
      return cmd(out, mem, 0, 0);
    }
  }
  if (mem.ap) {
    const ap = mem.ap;
    if (t - ap.bestT > (sPos && sPos.d > 3 ? 30 : 15) || t - ap.t0 > 100) {
      mem.bad.push({ x: ap.x, y: ap.y }); mem.ap = null; mem.path = null; mem.replan = true;
    }
  }
  if (mem.ap) {
    const ap = mem.ap;
    if (sPos && sPos.d <= 3.0) return servo(mem, out, sPos.d, sPos.b, front);
    const T = { x: ap.x, y: ap.y, stopR: 1.0, vmax: 0.2 };
    if (hyp(px, py, T.x, T.y) < 1.0) return cmd(out, mem, 0, 0);
    return navStep(mem, out, px, py, t, T, 0.2, rays, hdg);
  }

  // ---- delivering
  if (mem.goHome) {
    const T = { x: mem.base.x, y: mem.base.y, stopR: 2.2, vmax: dB < 6 ? 0.12 : 0.2 };
    return navStep(mem, out, px, py, t, T, T.vmax, rays, hdg);
  }

  // ---- hint / explore task
  if (!mem.task) newTask(mem, px, py, t);
  const T = taskTarget(mem, px, py, t, timeLeft, sci);
  if (!T) { mem.task = null; return cmd(out, mem, 0, 0); }
  if (hyp(px, py, T.x, T.y) < T.stopR) return cmd(out, mem, 0, 0);
  return navStep(mem, out, px, py, t, T, T.vmax, rays, hdg);
}
